window.__BOOK__ = {"meta": {"title_es": "El Principito", "title_zh": "小王子", "author_es": "Antoine de Saint-Exupéry", "author_zh": "安托万·德·圣埃克苏佩里", "voice": "es-ES-ElviraNeural (edge-tts)", "ipa_note": "音标为宽式音位转写（西班牙本土发音，ce/ci/z 发 θ），仅供参考；重音未标注。", "n_chapters": 28, "n_paras": 570, "n_sents": 1422, "audio_paras": 570}, "chapters": [{"id": "ch00", "title_es": "A Léon Werth", "title_zh": "献词", "paras": [{"id": "ch00p00", "audio": true, "sents": [{"es": "A Léon Werth.", "zh": "献给列翁·维尔特", "t": [100, 1762]}, {"es": "Pido perdón a los niños por haber dedicado este libro a una persona mayor.", "zh": "请孩子们原谅我把这本书献给了这位长者。", "t": [1762, 6400]}, {"es": "Tengo una excusa seria: esa persona mayor es el mejor amigo que tengo en el mundo.", "zh": "这位长者是我世间最挚的朋友。", "t": [6400, 11862]}, {"es": "Tengo otra excusa: esa persona mayor puede comprenderlo todo, hasta los libros para niños.", "zh": "这位长者能通晓一切，即便是对孩子的书籍。", "t": [11862, 18138]}, {"es": "Tengo una tercera excusa: esa persona mayor vive en Francia, donde tiene hambre y frío.", "zh": "这位长者住在法国，忍饥受寒。", "t": [18138, 24150]}, {"es": "Necesita ser consolada.", "zh": "需要安慰。", "t": [24150, 26588]}, {"es": "Si todas estas excusas no bastan, quiero dedicar este libro al niño que esa persona mayor fue antiguamente.", "zh": "若这些借口仍不足够，我想将此书献予那位长者曾身为孩童的往昔。", "t": [26588, 33475]}, {"es": "Todas las personas grandes han sido niños primero.", "zh": "所有的大人曾经都是孩子。", "t": [33475, 37075]}, {"es": "(Pero pocas lo recuerdan).", "zh": "但很少人记得。", "t": [37075, 39350]}, {"es": "Corrijo, pues, mi dedicatoria: A LEÓN WERTH, CUANDO ERA UN PEQUEÑO NIÑO.", "zh": "我修正我的献词：献予列翁·维尔特，他曾是孩童。", "t": [39350, 43437]}]}]}, {"id": "ch01", "title_es": "Capítulo 1", "title_zh": "第 1 章", "paras": [{"id": "ch01p00", "audio": true, "sents": [{"es": "Cuando yo tenía seis años vi en un libro sobre la selva virgen que se titulaba \"Historias vividas\", una magnífica lámina.", "zh": "六岁那一年，我在一本描写原始森林的书里看见一幅扣人心弦的图画。", "t": [100, 7538]}, {"es": "Representaba una serpiente boa que se tragaba a una fiera.", "zh": "那本书的书名叫做“丛林奇遇记”。", "t": [7538, 11612]}, {"es": "Esta es la copia del dibujo.", "zh": "图中画的是正在吞吃野兽的蟒蛇。", "t": [11612, 13200]}]}, {"id": "ch01p01", "audio": true, "sents": [{"es": "En el libro se afirmaba: \"La serpiente boa se traga su presa entera, sin masticarla.", "zh": "下面是这幅画的复印件。", "t": [100, 5725]}, {"es": "Luego ya no puede moverse y duerme durante los seis meses que dura su digestión\".", "zh": "书中说：“蟒蛇囫囵吞下猎物，肚子撑得它不能动弹，要躺六个月才能把猎物消化掉。", "t": [5725, 9776]}]}, {"id": "ch01p02", "audio": true, "sents": [{"es": "Reflexioné mucho en ese momento sobre las aventuras de la jungla y a mi vez logré trazar con un lápiz de colores mi primer dibujo.", "zh": "” 从此，我对丛林的种种奇事产生了无穷尽的遐想。", "t": [100, 7538]}, {"es": "Mi dibujo número 1 era de esta manera:", "zh": "我称它为一号画。", "t": [7538, 9737]}]}, {"id": "ch01p03", "audio": true, "sents": [{"es": "Enseñé mi obra de arte a las personas mayores y les pregunté si mi dibujo les daba miedo.", "zh": "一号画如下： 我把我的杰作拿给大人看，还问他们，我的画是否吓坏了他们。", "t": [100, 5550]}, {"es": "-¿por qué habría de asustar un sombrero?", "zh": "一号画如下： 我把我的杰作拿给大人看，还问他们，我的画是否吓坏了他们。", "t": [5550, 8475]}, {"es": "- me respondieron.", "zh": "他们回答我说：“一顶帽子有什么可怕的？", "t": [8475, 9438]}]}, {"id": "ch01p04", "audio": true, "sents": [{"es": "Mi dibujo no representaba un sombrero.", "zh": "他们回答我说：“一顶帽子有什么可怕的？", "t": [100, 3188]}, {"es": "Representaba una serpiente boa que digiere un elefante.", "zh": "” 我画的不是一顶帽子，而是一条正在消化大象的蟒蛇啊。", "t": [3188, 7125]}, {"es": "Dibujé entonces el interior de la serpiente boa a fin de que las personas mayores pudieran comprender.", "zh": "我又画了一张画，画的是蟒蛇和它肚子里的大象，好让大人看懂我的画。", "t": [7125, 13112]}, {"es": "Siempre estas personas tienen necesidad de explicaciones.", "zh": "我又画了一张画，画的是蟒蛇和它肚子里的大象，好让大人看懂我的画。", "t": [13112, 17250]}, {"es": "Mi dibujo número 2 era así:", "zh": "他们总是需要我们给他们解释的。", "t": [17250, 19038]}]}, {"id": "ch01p05", "audio": true, "sents": [{"es": "Las personas mayores me aconsejaron abandonar el dibujo de serpientes boas, ya fueran abiertas o cerradas, y poner más interés en la geografía, la historia, el cálculo y la gramática.", "zh": "我的二号画如下： 大人们劝我，别画这些肚子没打开或打开了的蟒蛇了，把心思放到地理、历史、算术、语法上去吧。", "t": [100, 11325]}, {"es": "De esta manera a la edad de seis años abandoné una magnífica carrera de pintor.", "zh": "就这样，我在六岁这一年放弃了画家的光辉生涯。", "t": [11325, 16412]}, {"es": "Había quedado desilusionado por el fracaso de mis dibujos número 1 y número 2.", "zh": "一号画、二号画的失败令我垂头丧气。", "t": [16412, 20350]}, {"es": "Las personas mayores nunca pueden comprender algo por sí solas y es muy aburrido para los niños tener que darles una y otra vez explicaciones.", "zh": "大人们老是需要孩子们费尽唇舌，给他们再三解释，不然就一窍不通，真把我们累得够呛。", "t": [20350, 29126]}]}, {"id": "ch01p06", "audio": true, "sents": [{"es": "Tuve, pues, que elegir otro oficio y aprendía pilotear aviones.", "zh": "我只好选择另一门职业。", "t": [100, 4538]}, {"es": "He volado un poco por todo el mundo y la geografía, en efecto, me ha servido de mucho; al primer vistazo podía distinguir perfectamente la China de Arizona.", "zh": "地理确实帮了我的大忙。", "t": [4538, 13800]}, {"es": "Esto es muy útil, sobre todo si se pierde uno durante la noche.A lo largo de mi vida he tenido multitud de contactos con multitud de gente seria.", "zh": "我一生与许多重要人物打过交道，我在大人当中生活了很长时间，我仔细地观察过他们，然而我对他们的看法没有多大的改善。", "t": [13800, 22300]}, {"es": "Viví mucho con personas mayores y las he conocido muy de cerca; pero esto no ha mejorado demasiado mi opinión sobre ellas.", "zh": "我一生与许多重要人物打过交道，我在大人当中生活了很长时间，我仔细地观察过他们，然而我对他们的看法没有多大的改善。", "t": [22300, 28713]}]}, {"id": "ch01p07", "audio": true, "sents": [{"es": "Cuando me he encontrado con alguien que me parecía un poco lúcido, lo he sometido a la experiencia de mi dibujo número 1 que he conservado siempre.", "zh": "遇到一个我认为略为懂事的大人，我就用这幅画做试验，看他是否真的懂事，但他们总是这样回答我：“这是一顶帽子。", "t": [100, 8275]}, {"es": "Quería saber si verdaderamente era un ser comprensivo.", "zh": "遇到一个我认为略为懂事的大人，我就用这幅画做试验，看他是否真的懂事，但他们总是这样回答我：“这是一顶帽子。", "t": [8275, 12038]}, {"es": "E invariablemente me contestaban siempre: \"Es un sombrero\".", "zh": "”听了这样的话，我就不再与他们谈蟒蛇、原始森林、星星了。", "t": [12038, 16175]}, {"es": "Me abstenía de hablarles de la serpiente boa, de la selva virgen y de las estrellas.", "zh": "”听了这样的话，我就不再与他们谈蟒蛇、原始森林、星星了。", "t": [16175, 21438]}, {"es": "Poniéndome a su altura, les hablaba del bridge, del golf, de política y de corbatas.", "zh": "我谈他们能理解的事情，例如桥牌啦，高尔夫球啦，政治啦，领带啦。", "t": [21438, 25837]}]}, {"id": "ch01p08", "audio": true, "sents": [{"es": "Y mi interlocutor se quedaba muy contento de conocer a un hombre tan razonable.", "zh": "大人们便很满意，以为他们认识了一个通情达理、善解人意的人。", "t": [100, 4038]}]}]}, {"id": "ch02", "title_es": "Capítulo 2", "title_zh": "第 2 章", "paras": [{"id": "ch02p00", "audio": true, "sents": [{"es": "Viví así, solo, nadie con quien poder hablar verdaderamente, hasta cuando hace seis años tuve una avería en el desierto de Sahara.", "zh": "这种状况一直延续至六年前。", "t": [100, 7888]}, {"es": "Algo se había estropeado en el motor.", "zh": "六年前，我的飞机出了故障，发动机里的某个部件被撞坏了，我被迫在撒哈拉沙漠降落。", "t": [7888, 10788]}, {"es": "Como no llevaba conmigo ni mecánico ni pasajero alguno, me dispuse a realizar, yo solo, una reparación difícil.", "zh": "身边没有机械师，没有一个乘客，我只好勉为其难，自己动手，试着修理部件。", "t": [10788, 18062]}, {"es": "Era para mí una cuestión de vida o muerte, pues apenas tenía agua de beber para ocho días.", "zh": "我带的水仅够喝一个星期，能否修好飞机，关系到我的生死存亡了。", "t": [18062, 22687]}]}, {"id": "ch02p01", "audio": true, "sents": [{"es": "La primera noche me dormí sobre la arena, a unas mil millas de distancia del lugar habitado más próximo.", "zh": "第一夜，我在远离人烟、千里之遥的沙漠上睡觉。", "t": [100, 6625]}, {"es": "Estaba más aislado que un náufrago en una balsa en medio del océano.", "zh": "比起那些乘着木排，在茫茫大洋中挣扎漂浮的遇险者，我更显得孤独无助。", "t": [6625, 11075]}, {"es": "Imagínense, pues, mi sorpresa cuando al amanecer me despertó una extraña vocecita que decía: - ¡Por favor…", "zh": "朝霞初露的时候，一个细细的奇妙的声音把我唤醒。", "t": [11075, 16725]}, {"es": "píntame un cordero!", "zh": "你不难想像我当时有多惊讶了。", "t": [16725, 18662]}, {"es": "-¿Eh?", "zh": "这细细的奇妙的声音说： “劳驾……请你给我画一只绵羊吧！", "t": [18662, 19838]}, {"es": "-¡Píntame un cordero!", "zh": "这细细的奇妙的声音说： “劳驾……请你给我画一只绵羊吧！", "t": [19838, 20874]}]}, {"id": "ch02p02", "audio": true, "sents": [{"es": "Me puse en pie de un salto como herido por el rayo.", "zh": "” “你说什么？", "t": [100, 2762]}]}, {"id": "ch02p03", "audio": true, "sents": [{"es": "Me froté los ojos.", "zh": "” “你说什么？", "t": [100, 2262]}, {"es": "Miré a mi alrededor.", "zh": "” “给我画一只绵羊……” 我像遭了雷击，一跃而起。", "t": [2262, 4462]}, {"es": "Vi a un extraordinario muchachito que me miraba gravemente.", "zh": "” “给我画一只绵羊……” 我像遭了雷击，一跃而起。", "t": [4462, 7587]}]}, {"id": "ch02p04", "audio": true, "sents": [{"es": "Ahí tienen el mejor retrato que más tarde logré hacer de él, aunque mi dibujo, ciertamente es menos encantador que el modelo.", "zh": "我使劲揉我的眼睛，仔细地看了看，只见一个很奇特的小小的人儿，他正在那儿注视我呢。", "t": [100, 7388]}, {"es": "Pero no es mía la culpa.", "zh": "下面就是以后我给他画的最为成功的一幅肖像画。", "t": [7388, 8637]}]}, {"id": "ch02p05", "audio": true, "sents": [{"es": "Las personas mayores me desanimaron de mi carrera de pintor a la edad de seis años y no había aprendido a dibujar otra cosa que boas cerradas y boas abiertas.", "zh": "当然，它没有他本人可爱俊美，这可不能怪我，该怪大人，是他们在我六岁那年葬送了我的画家生涯。", "t": [100, 8062]}]}, {"id": "ch02p06", "audio": true, "sents": [{"es": "Miré, pues, aquella aparición con los ojos redondos de admiración.", "zh": "除了画打开肚子和没打开肚子的蟒蛇之外，我没有画过一张画。", "t": [100, 4550]}, {"es": "No hay que olvidar que me encontraba a unas mil millas de distancia del lugar habitado más próximo.", "zh": "我大吃一惊，眼睛瞪得溜圆，看着这位突然出现的人儿。", "t": [4550, 10225]}, {"es": "Y ahora bien, el muchachito no me parecía ni perdido, ni muerto de cansancio, de hambre, de sed o de miedo.", "zh": "我的这个小人儿一点不像迷了路，也不像是累死、饿死、渴死、吓死的鬼魂。", "t": [10225, 17038]}, {"es": "No tenía en absoluto la apariencia de un niño perdido en el desierto, a mil millas de distancia del lugar habitado más próximo.", "zh": "他一点不像迷失于沙漠中的孩子，不像远离人烟、千里之遥的孩子。", "t": [17038, 24612]}, {"es": "Cuando logré, por fin, articular palabra, le dije:", "zh": "我终于能够张口说话了，我问他： “……你在这儿干什么？", "t": [24612, 27687]}]}, {"id": "ch02p07", "audio": true, "sents": [{"es": "-Pero…", "zh": "我终于能够张口说话了，我问他： “……你在这儿干什么？", "t": [100, 425]}, {"es": "¿qué haces tú por aquí?", "zh": "我终于能够张口说话了，我问他： “……你在这儿干什么？", "t": [425, 1575]}]}, {"id": "ch02p08", "audio": true, "sents": [{"es": "Y él respondió entonces, suavemente, como algo muy importante: -¡Por favor…", "zh": "” 他不慌不忙地重述他的要求，像说一件很严肃的事情： “请你给我画一只绵羊……” 当神秘的东西使得你心惊肉跳的时候，你不敢不听他的命令。", "t": [100, 4138]}, {"es": "píntame un cordero!", "zh": "” 他不慌不忙地重述他的要求，像说一件很严肃的事情： “请你给我画一只绵羊……” 当神秘的东西使得你心惊肉跳的时候，你不敢不听他的命令。", "t": [4138, 5138]}]}, {"id": "ch02p09", "audio": true, "sents": [{"es": "Cuando el misterio es demasiado impresionante, es imposible desobedecer.", "zh": "” 他不慌不忙地重述他的要求，像说一件很严肃的事情： “请你给我画一只绵羊……” 当神秘的东西使得你心惊肉跳的时候，你不敢不听他的命令。", "t": [100, 4800]}, {"es": "Por absurdo que aquello me pareciera, a mil millas de distancia de todo lugar habitado y en peligro de muerte, saqué de mi bolsillo una hoja de papel y una pluma fuente.", "zh": "虽然，身处远离人烟的荒漠，面临死亡的威胁，叫人画画的要求又未免荒堂，我还是从口袋里掏出一张纸和一枝钢笔。", "t": [4800, 14125]}, {"es": "Recordé que yo había estudiado especialmente geografía, historia, cálculo y gramática y le dije al muchachito (ya un poco malhumorado), que no sabía dibujar.", "zh": "他说：“不要紧，给我画一只绵羊吧。", "t": [14125, 22750]}]}, {"id": "ch02p10", "audio": true, "sents": [{"es": "-No importa - me respondió-, píntame un cordero!", "zh": "” 我从没画过绵羊，只画过那两张画。", "t": [100, 2675]}]}, {"id": "ch02p11", "audio": true, "sents": [{"es": "Como nunca había dibujado un cordero, rehíce para él uno de los dos únicos dibujos que yo era capaz de realizar: el de la serpiente boa cerrada.", "zh": "我吓了一跳，我听见小人儿说： “不！", "t": [100, 8650]}, {"es": "Y quedé estupefacto cuando oí decir al hombrecito: - ¡No, no!", "zh": "蟒蛇太可怕，象太占地方。", "t": [8650, 12762]}, {"es": "Yo no quiero un elefante en una serpiente.", "zh": "我要绵羊，给我画一只绵羊吧。", "t": [12762, 15888]}, {"es": "La serpiente es muy peligrosa y el elefante ocupa mucho sitio.", "zh": "他仔细看看，然后说： “不好！", "t": [15888, 20138]}, {"es": "En mi tierra es todo muy pequeño.", "zh": "这是一头患了重病的羊。", "t": [20138, 22838]}, {"es": "Necesito un cordero.", "zh": "给我画另一头吧。", "t": [22838, 25038]}, {"es": "Píntame un cordero.", "zh": "” 我又画了一只羊。", "t": [25038, 26075]}]}, {"id": "ch02p12", "audio": true, "sents": [{"es": "Dibujé un cordero.", "zh": "” 我又画了一只羊。", "t": [100, 1138]}]}, {"id": "ch02p13", "audio": true, "sents": [{"es": "Lo miró atentamente y dijo: ¡No!", "zh": "” 我又画了一只羊。", "t": [100, 2862]}, {"es": "Este está ya muy enfermo.", "zh": "我的朋友露出亲切可爱的微笑，并没有责怪我的意思，他说： “你瞧瞧，这不是小羊，是公羊，它长着角哩。", "t": [2862, 5312]}, {"es": "Haz otro.", "zh": "我的朋友露出亲切可爱的微笑，并没有责怪我的意思，他说： “你瞧瞧，这不是小羊，是公羊，它长着角哩。", "t": [5312, 5888]}]}, {"id": "ch02p14", "audio": true, "sents": [{"es": "Volví a dibujar.", "zh": "我的朋友露出亲切可爱的微笑，并没有责怪我的意思，他说： “你瞧瞧，这不是小羊，是公羊，它长着角哩。", "t": [100, 1038]}]}, {"id": "ch02p15", "audio": true, "sents": [{"es": "Mi amigo sonrió dulcemente, con indulgencia.", "zh": "” 我又画了一张。", "t": [100, 3538]}, {"es": "-¿Ves?", "zh": "” 我又画了一张。", "t": [3538, 4875]}, {"es": "Esto no es un cordero, es un carnero.", "zh": "” 我又画了一张。", "t": [4875, 8038]}, {"es": "Tiene Cuernos…", "zh": "这一张画和前面两张一样，遭到了他的拒绝： “这只太老了，我要一只能活很久的绵羊。", "t": [8038, 8876]}]}, {"id": "ch02p16", "audio": true, "sents": [{"es": "Rehice nuevamente mi dibujo: fue rechazado igual que los anteriores.", "zh": "这一张画和前面两张一样，遭到了他的拒绝： “这只太老了，我要一只能活很久的绵羊。", "t": [100, 3963]}]}, {"id": "ch02p17", "audio": true, "sents": [{"es": "-Este es demasiado viejo.", "zh": "” 我急于着手拆卸我的发动机，失去了耐性。", "t": [100, 2550]}, {"es": "Quiero un cordero que viva mucho tiempo.", "zh": "” 我急于着手拆卸我的发动机，失去了耐性。", "t": [2550, 4550]}]}, {"id": "ch02p18", "audio": true, "sents": [{"es": "Falto ya de paciencia y deseoso de comenzar a desmontar el motor, garrapateé rápidamente este dibujo, se lo enseñé, y le agregué:", "zh": "而且我冲他说： “这是一只箱子，你要的绵羊在里面。", "t": [100, 7487]}]}, {"id": "ch02p19", "audio": true, "sents": [{"es": "-Esta es la caja.", "zh": "” 然而我惊讶地看到，我的这位小法官竟眉开眼笑： “我要的正是这样的箱子！", "t": [100, 2100]}, {"es": "El cordero que quieres está adentro.", "zh": "” 然而我惊讶地看到，我的这位小法官竟眉开眼笑： “我要的正是这样的箱子！", "t": [2100, 4938]}, {"es": "Con gran sorpresa mía el rostro de mi joven juez se iluminó: -¡Así es como yo lo quería!", "zh": "这只绵羊要很多草吗？", "t": [4938, 10562]}, {"es": "¿Crees que sea necesario mucha hierba para este cordero?", "zh": "” “因为我的家太小啦……” “肯定够了。", "t": [10562, 14425]}, {"es": "-¿Por qué?", "zh": "” “因为我的家太小啦……” “肯定够了。", "t": [14425, 14812]}]}, {"id": "ch02p20", "audio": true, "sents": [{"es": "-Porque en mi tierra es todo tan pequeño…", "zh": "我给你的是一只很小很小的绵羊。", "t": [100, 2088]}]}, {"id": "ch02p21", "audio": true, "sents": [{"es": "Se inclinó hacia el dibujo y exclamó: -¡Bueno, no tan pequeño…!", "zh": "“没有这个这么小吧……咦！", "t": [100, 4450]}, {"es": "Está dormido…", "zh": "它睡熟了……” 我就这样认识了小王子。", "t": [4450, 5250]}]}, {"id": "ch02p22", "audio": true, "sents": [{"es": "Y así fue como conocí al principito.", "zh": "它睡熟了……” 我就这样认识了小王子。", "t": [100, 2075]}]}]}, {"id": "ch03", "title_es": "Capítulo 3", "title_zh": "第 3 章", "paras": [{"id": "ch03p00", "audio": true, "sents": [{"es": "Me costó mucho tiempo comprender de dónde venía.", "zh": "过了好久好久，我才弄明白他是打哪儿来的。", "t": [100, 3575]}, {"es": "El principito, que me hacía muchas preguntas, jamás parecía oír las mías.", "zh": "小王子向我提了许多问题，却从不理会我对他提的问题。", "t": [3575, 8712]}, {"es": "Fueron palabras pronunciadas al azar, las que poco a poco me revelaron todo.", "zh": "我从他无意中吐出的片言只语里，逐渐知道了他的来历。", "t": [8712, 13675]}, {"es": "Así, cuando distinguió por vez primera mi avión (no dibujaré mi avión, por tratarse de un dibujo demasiado complicado para mí) me preguntó: -¿Qué cosa es esa?", "zh": "例如，当他第一次看见我的飞机的时候（我不愿画飞机，太复杂了），就问我： “这是什么玩艺儿呀？", "t": [13675, 23188]}, {"es": "-Eso no es una cosa.", "zh": "这是飞机，是我的飞机。", "t": [23188, 25412]}, {"es": "Eso vuela.", "zh": "这是飞机，是我的飞机。", "t": [25412, 27038]}, {"es": "Es un avión, mi avión.", "zh": "” 我挺自豪地告诉他我会飞。", "t": [27038, 28488]}]}, {"id": "ch03p01", "audio": true, "sents": [{"es": "Me sentía orgulloso al decirle que volaba.", "zh": "他嚷起来： “怎么？", "t": [100, 3338]}, {"es": "El entonces gritó: -¡Cómo!", "zh": "你是从天上掉下来的吗？", "t": [3338, 5775]}, {"es": "¿Has caído del cielo?", "zh": "” “是的。", "t": [5775, 7912]}, {"es": "-Sí -le dije modestamente.", "zh": "”我并没有吹嘘的意思。", "t": [7912, 10462]}, {"es": "-¡Ah, que curioso!", "zh": "“啊！", "t": [10462, 11450]}]}, {"id": "ch03p02", "audio": true, "sents": [{"es": "Y el principito lanzó una graciosa carcajada que me irritó mucho.", "zh": "这就奇了……” 小王子发出清脆悦耳的笑声，他这一笑可惹恼了我。", "t": [100, 4400]}, {"es": "Me gusta que mis desgracias se tomen en serio.", "zh": "我不喜欢别人对我的不幸打哈哈。", "t": [4400, 7762]}, {"es": "Y añadió:", "zh": "然后他又说： “这么说，你也是从天上下来的！", "t": [7762, 8337]}]}, {"id": "ch03p03", "audio": true, "sents": [{"es": "-Entonces ¿tú también vienes del cielo?", "zh": "然后他又说： “这么说，你也是从天上下来的！", "t": [100, 3288]}, {"es": "¿De qué planeta eres tú?", "zh": "你住在哪一个星球上？", "t": [3288, 4537]}]}, {"id": "ch03p04", "audio": true, "sents": [{"es": "Divisé una luz en el misterio de su presencia y le pregunté bruscamente: -¿Tu vienes, pues, de otro planeta?", "zh": "” 这句话犹如一道亮光，让我马上瞥见了他突然出现的秘密。", "t": [100, 5613]}]}, {"id": "ch03p05", "audio": true, "sents": [{"es": "Pero no me respondió; movía lentamente la cabeza mirando detenidamente mi avión.", "zh": "” 他不答。", "t": [100, 4463]}]}, {"id": "ch03p06", "audio": true, "sents": [{"es": "-Es cierto, que, encima de eso, no puedes venir de muy lejos…", "zh": "他看着我的飞机，轻轻地点头： “从你乘的这玩艺来看，你确实不可能来自很远的地方……” 他陷入沉思。", "t": [100, 3462]}]}, {"id": "ch03p07", "audio": true, "sents": [{"es": "Y se hundió en un ensueño durante largo tiempo.", "zh": "他看着我的飞机，轻轻地点头： “从你乘的这玩艺来看，你确实不可能来自很远的地方……” 他陷入沉思。", "t": [100, 3575]}, {"es": "Luego sacando de su bolsillo mi cordero se abismó en la contemplación de su tesoro.", "zh": "过了很久，他从口袋里掏出我画的绵羊，低头凝视他的宝贝。", "t": [3575, 7787]}]}, {"id": "ch03p08", "audio": true, "sents": [{"es": "Imagínense cómo me intrigó esta semiconfidencia sobre los otros planetas.", "zh": "你们不难想像，听了他那句无意透露的“其他星球”的话后，我会怎样惊讶吧。", "t": [100, 4950]}, {"es": "Me esforcé, pues, en saber algo más: -¿De dónde vienes, muchachito?", "zh": "我竭力从中探听他的来历： “我的小人儿，你从哪儿来？", "t": [4950, 9525]}, {"es": "¿Dónde está \"tu casa\"?", "zh": "你的家在哪儿？", "t": [9525, 11712]}, {"es": "¿Dónde quieres llevarte mi cordero?", "zh": "你要把你的绵羊牵到哪儿去？", "t": [11712, 13425]}]}, {"id": "ch03p09", "audio": true, "sents": [{"es": "Después de meditar silenciosamente me respondió:", "zh": "” 他默默不答。", "t": [100, 2700]}]}, {"id": "ch03p10", "audio": true, "sents": [{"es": "-Lo bueno de la caja que me has dado es que por la noche le servirá de casa.", "zh": "夜里可以给绵羊做屋子了。", "t": [100, 4538]}, {"es": "-Sin duda.", "zh": "夜里可以给绵羊做屋子了。", "t": [4538, 6150]}, {"es": "Y si eres bueno te daré también una cuerda y una estaca para atarlo durante el día.", "zh": "” “是呀，如果你乖，我还要给你一根绳子，白天给你拴羊用。", "t": [6150, 10287]}]}, {"id": "ch03p11", "audio": true, "sents": [{"es": "Esta proposición pareció chocar al principito.", "zh": "” 我的建议显然惹恼了小王子： “拴住它？", "t": [100, 3488]}, {"es": "-¿Atarlo?", "zh": "” 我的建议显然惹恼了小王子： “拴住它？", "t": [3488, 4975]}, {"es": "¡Qué idea más rara!", "zh": "亏你想得出这样的主意！", "t": [4975, 7025]}, {"es": "-Si no lo atas, se irá quién sabe dónde y se perderá…", "zh": "亏你想得出这样的主意！", "t": [7025, 9676]}]}, {"id": "ch03p12", "audio": true, "sents": [{"es": "Mi amigo soltó una nueva carcajada.", "zh": "” “你不拴住它，它会乱跑的呀，会走失的呀。", "t": [100, 3112]}, {"es": "-¿Y dónde quieres que vaya?", "zh": "” 我的朋友发出清脆的笑声： “你以为它会跑到哪儿去呢？", "t": [3112, 5388]}, {"es": "-No sé, a cualquier parte.", "zh": "” 我的朋友发出清脆的笑声： “你以为它会跑到哪儿去呢？", "t": [5388, 7775]}, {"es": "Derecho camino adelante…", "zh": "” 我的朋友发出清脆的笑声： “你以为它会跑到哪儿去呢？", "t": [7775, 9175]}]}, {"id": "ch03p13", "audio": true, "sents": [{"es": "Entonces el principito señaló con gravedad: -¡No importa, es tan pequeña mi tierra!", "zh": "” “到处乱跑呗，朝前跑呗……” 小王子告诉我： “这倒不成问题，我的家小得很呢！", "t": [100, 4474]}]}, {"id": "ch03p14", "audio": true, "sents": [{"es": "Y agregó, quizás, con un poco de melancolía:", "zh": "” 他的神色略带忧伤，说： “朝前跑，也跑不了多远……”", "t": [100, 2462]}]}, {"id": "ch03p15", "audio": true, "sents": [{"es": "-Derecho, camino adelante…", "zh": "” 他的神色略带忧伤，说： “朝前跑，也跑不了多远……”", "t": [100, 1612]}, {"es": "no se puede ir muy lejos.", "zh": "” 他的神色略带忧伤，说： “朝前跑，也跑不了多远……”", "t": [1612, 3050]}]}]}, {"id": "ch04", "title_es": "Capítulo 4", "title_zh": "第 4 章", "paras": [{"id": "ch04p00", "audio": true, "sents": [{"es": "De esta manera supe una segunda cosa muy importante: su planeta de origen era apenas más grande que una casa.", "zh": "就这样，我知道了第二件很重要的事情：他打那儿来的星球比一幢房子大不了多少！", "t": [100, 5976]}]}, {"id": "ch04p01", "audio": true, "sents": [{"es": "Esto no podía asombrarme mucho.", "zh": "我并不因此大惊小怪。", "t": [100, 2988]}, {"es": "Sabía muy bien que aparte de los grandes planetas como la Tierra, Júpiter, Marte, Venus, a los cuales se les ha dado nombre, existen otros centenares de ellos tan pequeños a veces, que es difícil distinguirlos aun con la ayuda del telescopio.", "zh": "有些星球小到连望远镜都难以观测。", "t": [2988, 16462]}, {"es": "Cuando un astrónomo descubre uno de estos planetas, le da por nombre un número.", "zh": "天文学家发现一颗星，就用号码给它命名，例如叫它“小行星3251号”。", "t": [16462, 21600]}, {"es": "Le llama, por ejemplo, \"el asteroide 3251\".", "zh": "我有充分的证据认为小王子打那儿来的星球就是B612号小行星。", "t": [21600, 25200]}]}, {"id": "ch04p02", "audio": true, "sents": [{"es": "Tengo poderosas razones para creer que el planeta del cual venía el principito era el asteroide B 612.", "zh": "这颗小行星仅仅在一九〇九年被一位土耳其天文学家用望远镜看见过一回。", "t": [100, 4800]}, {"es": "Este asteroide ha sido visto sólo una vez con el telescopio en 1909, por un astrónomo turco.", "zh": "在国际天文会议上，他为他的发现做了雄辩的论证，但没有人相信他的报告。", "t": [4800, 12324]}]}, {"id": "ch04p03", "audio": true, "sents": [{"es": "Este astrónomo hizo una gran demostración de su descubrimiento en un congreso Internacional de Astronomía.", "zh": "因为他穿的是土耳其人的服装。", "t": [100, 6450]}, {"es": "Pero nadie le creyó a causa de su manera de vestir.", "zh": "大人们就这个德性：以衣冠取人。", "t": [6450, 9000]}]}, {"id": "ch04p04", "audio": true, "sents": [{"es": "Las personas mayores son así.", "zh": "幸好，为了维护B612小行星的声誉，土耳其独裁者颁布了一条法令，命令百姓改穿欧式服装，否则处以死刑。", "t": [100, 2875]}, {"es": "Felizmente para la reputación del asteroide B 612, un dictador turco impuso a su pueblo, bajo pena de muerte, el vestido a la europea.", "zh": "幸好，为了维护B612小行星的声誉，土耳其独裁者颁布了一条法令，命令百姓改穿欧式服装，否则处以死刑。", "t": [2875, 10875]}]}, {"id": "ch04p05", "audio": true, "sents": [{"es": "Entonces el astrónomo volvió a dar cuenta de su descubrimiento en 1920 y como lucía un traje muy elegante, todo el mundo aceptó su demostración.", "zh": "一九二〇年，这位土耳其天文学家身穿一套极考究的西服，再一次在国际会议上做了论证。", "t": [100, 8163]}]}, {"id": "ch04p06", "audio": true, "sents": [{"es": "Si les he contado de todos estos detalles sobre el asteroide B 612 y hasta les he confiado su número, es por consideración a las personas mayores.", "zh": "我对你们详细报告发现小行星B612的这些细节，把它的号码告诉你们，都是由于那些大人们的缘故。", "t": [100, 9312]}, {"es": "A los mayores les gustan las cifras.", "zh": "因为大人们对数字情有独钟。", "t": [9312, 12262]}, {"es": "Cuando se les habla de un nuevo amigo, jamás preguntan sobre lo esencial del mismo.", "zh": "如果你对他们介绍一个新朋友，他们从不打听他的基本情况，他们从不会问你：“他的嗓子怎么样？", "t": [12262, 17575]}, {"es": "Nunca se les ocurre preguntar: \"¿Qué tono tiene su voz?", "zh": "如果你对他们介绍一个新朋友，他们从不打听他的基本情况，他们从不会问你：“他的嗓子怎么样？", "t": [17575, 21512]}, {"es": "¿Qué juegos prefiere?", "zh": "他喜欢玩什么游戏？", "t": [21512, 23600]}, {"es": "¿Le gusta coleccionar mariposas?\" Pero en cambio preguntan: \"¿Qué edad tiene?", "zh": "他是否采集蝴蝶标本？", "t": [23600, 29488]}, {"es": "¿Cuántos hermanos?", "zh": "有多少个兄弟？", "t": [29488, 31450]}, {"es": "¿Cuánto pesa?", "zh": "体重多少？", "t": [31450, 33162]}, {"es": "¿Cuánto gana su padre?\" Solamente con estos detalles creen conocerle.", "zh": "他的父亲挣多少钱？", "t": [33162, 38738]}, {"es": "Si les decimos a las personas mayores: \"He visto una casa preciosa de ladrillo rosa, con geranios en las ventanas y palomas en el tejado\", jamás llegarán a imaginarse cómo es esa casa.", "zh": "如果你告诉大人：“我看见一幢漂亮的红砖房子，窗前摆着天竺葵，鸽子在屋顶栖息……”他们便无法想像这是一幢怎样的房子。", "t": [38738, 48876]}]}, {"id": "ch04p07", "audio": true, "sents": [{"es": "Es preciso decirles: \"He visto una casa que vale cien mil pesos\".", "zh": "你必须对他们说：“我看见一幢值十万法郎的房子！", "t": [100, 4762]}, {"es": "Entonces exclaman entusiasmados: \"¡Oh, qué preciosa es!\"", "zh": "你必须对他们说：“我看见一幢值十万法郎的房子！", "t": [4762, 8037]}]}, {"id": "ch04p08", "audio": true, "sents": [{"es": "De tal manera, si les decimos: \"La prueba de que el principito ha existido está en que era un muchachito encantador, que reía y quería un cordero.", "zh": "” 所以，如果你对他们说：“这世上确实存在一位王子，证据就是他可爱俊美，脸带笑容，他要一只绵羊。", "t": [100, 8462]}, {"es": "Querer un cordero es prueba de que se existe\", las personas mayores se encogerán de hombros y nos dirán que somos unos niños.", "zh": "一个人要一只绵羊，就是他存在的证明。", "t": [8462, 15825]}, {"es": "Pero si les decimos: \"el planeta de donde venía el principito era el asteroide B 612\", quedarán convencidas y no se preocuparán de hacer más preguntas.", "zh": "但如果你对他们说：“他打那儿来的星球是小行星B612。", "t": [15825, 25312]}, {"es": "Son así.", "zh": "”他们就深信不疑了，就不会用没完没了的问题烦你了。", "t": [25312, 25900]}]}, {"id": "ch04p09", "audio": true, "sents": [{"es": "No hay por qué guardarles rencor.", "zh": "”他们就深信不疑了，就不会用没完没了的问题烦你了。", "t": [100, 2825]}, {"es": "Los niños deben ser muy indulgentes con las personas mayores.", "zh": "他们就这副德性。", "t": [2825, 6137]}]}, {"id": "ch04p10", "audio": true, "sents": [{"es": "Pero nosotros, que sabemos comprender la vida, nos burlamos tranquilamente de los números.", "zh": "我们不要责怪埋怨他们，孩子对大人应当尽量地宽容。", "t": [100, 5850]}, {"es": "A mí me habría gustado más comenzar esta historia a la manera de los cuentos de hadas.", "zh": "当然，我们是理解生活的人，我们才不会把数字放在眼里呢！", "t": [5850, 10988]}, {"es": "Me habría gustado decir:", "zh": "我喜欢以讲童话的方式讲这个故事。", "t": [10988, 12375]}]}, {"id": "ch04p11", "audio": true, "sents": [{"es": "\"Era una vez un principito que habitaba un planeta apenas más grande que él y que tenía necesidad de un amigo…\" Para aquellos que comprenden la vida, esto hubiera parecido más real.", "zh": "这颗行星比他自己大不了多少。", "t": [100, 10087]}]}, {"id": "ch04p12", "audio": true, "sents": [{"es": "Porque no me gusta que mi libro sea tomado a la ligera.", "zh": "”对于理解生活的人，这样讲似乎要真实得多。", "t": [100, 3712]}, {"es": "Siento tanta pena al contar estos recuerdos.", "zh": "我不喜欢别人漫不经心地读我的书。", "t": [3712, 6163]}]}, {"id": "ch04p13", "audio": true, "sents": [{"es": "Hace ya seis años que mi amigo se fue con su cordero.", "zh": "提起这些往事，我还挺伤心的。", "t": [100, 3750]}, {"es": "Y si intento describirlo aquí es sólo con el fin de no olvidarlo.", "zh": "我在这儿讲述他的故事，是为了不忘记他。", "t": [3750, 8162]}, {"es": "Es muy triste olvidar a un amigo.", "zh": "忘了朋友是可悲的。", "t": [8162, 10900]}, {"es": "No todos han tenido un amigo.", "zh": "忘了朋友是可悲的。", "t": [10900, 13525]}, {"es": "Y yo puedo llegar a ser como las personas mayores, que sólo se interesan por las cifras.", "zh": "也许有一天我也像大人那样，除了数字，对别的东西都失去兴趣。", "t": [13525, 19125]}, {"es": "Para evitar esto he comprado una caja de lápices de colores.", "zh": "为了这个缘故，我买了一盒颜料和几枝铅笔。", "t": [19125, 23088]}, {"es": "¡Es muy duro, a mi edad, ponerse a aprender a dibujar, cuando en toda la vida no se ha hecho otra tentativa que la de una boa abierta y una boa cerrada a la edad de seis años!", "zh": "到了我这个年龄才重拾画笔是困难的。", "t": [23088, 32775]}, {"es": "Ciertamente que yo trataré de hacer retratos lo más parecido posibles, pero no estoy muy seguro de lograrlo.", "zh": "当然，我可以画最逼真的人像画。", "t": [32775, 39525]}, {"es": "Uno saldrá bien y otro no tiene parecido alguno.", "zh": "但能否成功，我把握不大。", "t": [39525, 43025]}, {"es": "En las proporciones me equivoco también un poco.", "zh": "这一幅画得可以，另一幅却画得不像。", "t": [43025, 46412]}, {"es": "Aquí el principito es demasiado grande y allá es demasiado pequeño.", "zh": "对他的个儿高矮，我也记得不太真切。", "t": [46412, 50888]}, {"es": "Dudo también sobre el color de su traje.", "zh": "这幅把他画得太高，另一幅把他画得太矮。", "t": [50888, 53925]}, {"es": "Titubeo sobre esto y lo otro y unas veces sale bien y otras mal.", "zh": "该给他的衣服抹什么颜色，我也犹豫不决。", "t": [53925, 58250]}, {"es": "Es posible, en fin, que me equivoque sobre ciertos detalles muy importantes.", "zh": "我在画纸上抹来抹去，画了张约莫相似的肖像，但某些重要部位也许弄错了。", "t": [58250, 63350]}, {"es": "Pero habrá que perdonármelo ya que mi amigo no me daba nunca muchas explicaciones.", "zh": "对这一点，你们一定要谅解。", "t": [63350, 68350]}, {"es": "Me creía semejante a sí mismo y yo, desgraciadamente, no sé ver un cordero a través de una caja.", "zh": "我的朋友从不向我解释，大概他以为我和他一样；可是我呢，很遗憾，我不能透过箱子看到里面的绵羊。", "t": [68350, 74512]}, {"es": "Es posible que yo sea un poco como las personas mayores.", "zh": "也许我有点像大人了。", "t": [74512, 78512]}, {"es": "He debido envejecer.", "zh": "我大概老了。", "t": [78512, 79550]}]}]}, {"id": "ch05", "title_es": "Capítulo 5", "title_zh": "第 5 章", "paras": [{"id": "ch05p00", "audio": true, "sents": [{"es": "Cada día yo aprendía algo nuevo sobre el planeta, sobre la partida y sobre el viaje.", "zh": "每一天，我都从他那儿获得一些有关星球、启程、旅行的知识。", "t": [100, 5388]}, {"es": "Esto venía suavemente al azar de las reflexiones.", "zh": "这些知识是逐渐得到的，只要想到什么问题就提什么问题。", "t": [5388, 9150]}, {"es": "De esta manera tuve conocimiento al tercer día, del drama de los baobabs.", "zh": "这些知识是逐渐得到的，只要想到什么问题就提什么问题。", "t": [9150, 13112]}]}, {"id": "ch05p01", "audio": true, "sents": [{"es": "Fue también gracias al cordero y como preocupado por una profunda duda, cuando el principito me preguntó: -¿Es verdad que los corderos se comen los arbustos?", "zh": "这一回还真亏了绵羊。", "t": [100, 8288]}]}, {"id": "ch05p02", "audio": true, "sents": [{"es": "-Sí, es cierto.", "zh": "因为小王子突然对一件事产生了极大的怀疑，突然问我： “羊吃灌木，这是真的吗？", "t": [100, 2150]}, {"es": "-¡Ah, qué contesto estoy!", "zh": "” “是呀，是真的呀。", "t": [2150, 3426]}]}, {"id": "ch05p03", "audio": true, "sents": [{"es": "No comprendí por qué era tan importante para él que los corderos se comieran los arbustos.", "zh": "” “啊，那我很高兴。", "t": [100, 5438]}, {"es": "Pero el principito añadió:", "zh": "” 我不明白，羊吃灌木为什么这么重要。", "t": [5438, 6738]}]}, {"id": "ch05p04", "audio": true, "sents": [{"es": "-Entonces se comen también los Baobabs.", "zh": "小王子又问： “这么说，它们也吃猴面包树啦？", "t": [100, 2137]}]}, {"id": "ch05p05", "audio": true, "sents": [{"es": "Le hice comprender al principito que los baobabs no son arbustos, sino árboles tan grandes como iglesias y que incluso si llevase consigo todo un rebaño de elefantes, el rebaño no lograría acabar con un solo baobab.", "zh": "” 我提醒小王子，猴面包树不是灌木丛，而是像教堂一样巍峨高大的树。", "t": [100, 11450]}]}, {"id": "ch05p06", "audio": true, "sents": [{"es": "Esta idea del rebaño de elefantes hizo reír al principito.", "zh": "即使他弄一群大象来，它们也啃不完一棵猴面包树。", "t": [100, 3250]}]}, {"id": "ch05p07", "audio": true, "sents": [{"es": "-Habría que poner los elefantes unos sobre otros…", "zh": "想到一群象啃猴面包树的情景，小王子忍不住笑了： “那它们非得叠罗汉了……” 他很机灵，指出： “猴面包树的树苗挺小的呢！", "t": [100, 2688]}]}, {"id": "ch05p08", "audio": true, "sents": [{"es": "Y luego añadió juiciosamente:", "zh": "想到一群象啃猴面包树的情景，小王子忍不住笑了： “那它们非得叠罗汉了……” 他很机灵，指出： “猴面包树的树苗挺小的呢！", "t": [100, 1825]}]}, {"id": "ch05p09", "audio": true, "sents": [{"es": "-Los baobabs, antes de crecer, son muy pequeñitos.", "zh": "” “你说得对！", "t": [100, 2913]}]}, {"id": "ch05p10", "audio": true, "sents": [{"es": "-Es cierto.", "zh": "” “你说得对！", "t": [100, 1738]}, {"es": "Pero ¿por qué quieres que tus corderos coman los baobabs?", "zh": "” “你说得对！", "t": [1738, 4475]}]}, {"id": "ch05p11", "audio": true, "sents": [{"es": "Me contestó: \"¡Bueno!", "zh": "可是你为什么希望你的绵羊吃猴面包树苗呢？", "t": [100, 2262]}, {"es": "¡Vamos!\" como si hablara de una evidencia.", "zh": "” 他说：“嘿！", "t": [2262, 5425]}, {"es": "Me fue necesario un gran esfuerzo de inteligencia para comprender por mí mismo este problema.", "zh": "”似乎这是再明白不过的事情。", "t": [5425, 10012]}]}, {"id": "ch05p12", "audio": true, "sents": [{"es": "En efecto, en el planeta del principito había, como en todos los planetas, hierbas buenas y hierbas malas.", "zh": "而要我自己想明白这个问题，我确实要绞尽脑汁了。", "t": [100, 6350]}, {"es": "Por consiguiente, de buenas semillas salían buenas hierbas y de las semillas malas, hierbas malas.", "zh": "是的，小王子的星球和其他星球一样，长着益草，也长着毒草，因此也就有了益草的种子和毒草的种子。", "t": [6350, 11187]}]}, {"id": "ch05p13", "audio": true, "sents": [{"es": "Pero las semillas son invisibles; duermen en el secreto de la tierra, hasta que un buen día una de ellas tiene la fantasía de despertarse.", "zh": "但种子是看不见的，它们沉埋在土地深处，直至其中一颗突然苏醒……它伸伸懒腰，羞羞答答，向着太阳伸出一株青嫩可爱、娇小玲珑、不伤人的幼苗来。", "t": [100, 8225]}, {"es": "Entonces se alarga extendiendo hacia el sol, primero tímidamente, una encantadora ramita inofensiva.", "zh": "倘若它是萝卜或玫瑰的幼苗，我们可以任由它茁壮成长；倘若它是有毒的植物，一经认出，我们就必须马上拔除。", "t": [8225, 14775]}, {"es": "Si se trata de una ramita de rábano o de rosal, se la puede dejar que crezca como quiera.", "zh": "倘若它是萝卜或玫瑰的幼苗，我们可以任由它茁壮成长；倘若它是有毒的植物，一经认出，我们就必须马上拔除。", "t": [14775, 19624]}]}, {"id": "ch05p14", "audio": true, "sents": [{"es": "Pero si se trata de una mala hierba, es preciso arrancarla inmediatamente en cuanto uno ha sabido reconocerla.", "zh": "小王子的星球上埋着可怕的种子……这就是猴面包树的种子，星球的土壤饱受其害，不及时动手除掉它们，你就永远别想摆脱它们的侵害。", "t": [100, 5888]}]}, {"id": "ch05p15", "audio": true, "sents": [{"es": "En el planeta del principito había semillas terribles…", "zh": "小王子的星球上埋着可怕的种子……这就是猴面包树的种子，星球的土壤饱受其害，不及时动手除掉它们，你就永远别想摆脱它们的侵害。", "t": [100, 3025]}, {"es": "como las semillas del baobab.", "zh": "小王子的星球上埋着可怕的种子……这就是猴面包树的种子，星球的土壤饱受其害，不及时动手除掉它们，你就永远别想摆脱它们的侵害。", "t": [3025, 5225]}, {"es": "El suelo del planeta está infestado de ellas.", "zh": "它的树身枝叶占据整个星球，如果星球小，而猴面包树过多，就会撑破星球。", "t": [5225, 8600]}, {"es": "Si un baobab no se arranca a tiempo, no hay manera de desembarazarse de él más tarde; cubre todo el planeta y lo perfora con sus raíces.", "zh": "它的树身枝叶占据整个星球，如果星球小，而猴面包树过多，就会撑破星球。", "t": [8600, 16900]}, {"es": "Y si el planeta es demasiado pequeño y los baobabs son numerosos, lo hacen estallar.", "zh": "后来小王子对我说：“人早上梳洗之后，一定要小心清理地球，要经常督促自己，要养成良好的习惯。", "t": [16900, 21350]}]}, {"id": "ch05p16", "audio": true, "sents": [{"es": "\"Es una cuestión de disciplina, me decía más tarde el principito.", "zh": "猴面包树的苗儿与玫瑰花的苗儿长得极相似，把它们区别开来之后，就要经常督促自己拔除猴面包树苗。", "t": [100, 4562]}, {"es": "Cuando por la mañana uno termina de arreglarse, hay que hacer cuidadosamente la limpieza del planeta.", "zh": "猴面包树的苗儿与玫瑰花的苗儿长得极相似，把它们区别开来之后，就要经常督促自己拔除猴面包树苗。", "t": [4562, 10575]}, {"es": "Hay que dedicarse regularmente a arrancar los baobabs, cuando se les distingue de los rosales, a los cuales se parecen mucho cuando son pequeñitos.", "zh": "” 有一天，他建议我用心画一幅猴面包树的画，要让我们那儿的孩子牢牢记住它。", "t": [10575, 19138]}, {"es": "Es un trabajo muy fastidioso pero muy fácil\".", "zh": "他对我说：“有朝一日他们外出旅行，这幅画就派上用场了。", "t": [19138, 21562]}]}, {"id": "ch05p17", "audio": true, "sents": [{"es": "Y un día me aconsejó que me dedicara a realizar un hermoso dibujo, que hiciera comprender a los niños de la tierra estas ideas.", "zh": "他对我说：“有朝一日他们外出旅行，这幅画就派上用场了。", "t": [100, 7688]}, {"es": "\"Si alguna vez viajan, me decía, esto podrá servirles mucho.", "zh": "有些时候，耽搁了的工夫造不成多大的恶果，然而对猴面包树的危害却不能轻视。", "t": [7688, 12275]}, {"es": "A veces no hay inconveniente en dejar para más tarde el trabajo que se ha de hacer; pero tratándose de baobabs, el retraso es siempre una catástrofe.", "zh": "我知道，有一颗星球上住着一个懒人，他忽略了剔除三棵猴面包树苗的事儿……” 在小王子的指点下，我画了这个星球。", "t": [12275, 20738]}, {"es": "Yo he conocido un planeta, habitado por un perezoso que descuidó tres arbustos…\"", "zh": "我知道，有一颗星球上住着一个懒人，他忽略了剔除三棵猴面包树苗的事儿……” 在小王子的指点下，我画了这个星球。", "t": [20738, 25175]}]}, {"id": "ch05p18", "audio": true, "sents": [{"es": "Siguiendo las indicaciones del principito, dibujé dicho planeta.", "zh": "我素来不喜欢装腔作势，摆出一副道学家的面孔训人，但许多人对猴面包树的危害认识不足，在小行星上迷路的人遇到的风险又那么大，我不能不一反平日矜持的常态，大声疾呼：“孩子们，当心猴面包树啊！", "t": [100, 4538]}, {"es": "Aunque no me gusta el papel de moralista, el peligro de los baobabs es tan desconocido y los peligros que puede correr quien llegue a perderse en un asteroide son tan grandes, que no vacilo en hacer una excepción y exclamar: \"¡Niños, atención a los baobabs!\" Y sólo con el fin de advertir a mis amigos de estos peligros a que se exponen desde hace ya tiempo sin saberlo, es por lo que trabajé y puse tanto empeño en realizar este dibujo.", "zh": "”为了向朋友们发出警告，让他们提防早已威胁我们的危险——而他们和我一样，对这样的危险一无所知——我对这幅画下足了功夫。", "t": [4538, 28175]}, {"es": "La lección que con él podía dar, valía la pena.", "zh": "也许你们看了这幅画后会纳闷：“为什么他在这本书里画的其他画没有这张猴面包树的画雄壮，有气势？", "t": [28175, 31638]}, {"es": "Es muy posible que alguien me pregunte por qué no hay en este libro otros dibujos tan grandiosos como el dibujo de los baobabs.", "zh": "”我的回答很简单：我尽了力去画其他的画，但心有余而力不足。", "t": [31638, 38525]}, {"es": "La respuesta es muy sencilla: he tratado de hacerlos, pero no lo he logrado.", "zh": "”我的回答很简单：我尽了力去画其他的画，但心有余而力不足。", "t": [38525, 43650]}, {"es": "Cuando dibujé los baobabs estaba animado por un sentimiento de urgencia.", "zh": "而画猴面包树的时候，为急迫的需要所激励，我的画便超出了原有的水平。", "t": [43650, 47300]}]}]}, {"id": "ch06", "title_es": "Capítulo 6", "title_zh": "第 6 章", "paras": [{"id": "ch06p00", "audio": true, "sents": [{"es": "¡Ah, principito, cómo he ido comprendiendo lentamente tu vida melancólica!", "zh": "我就是这样逐渐了解到，你过着并不顺心愉快的生活。", "t": [100, 4762]}, {"es": "Durante mucho tiempo tu única distracción fue la suavidad de las puestas de sol.", "zh": "长期以来，你惟一的消遣就是观赏夕阳西下的美景。", "t": [4762, 9625]}, {"es": "Este nuevo detalle lo supe al cuarto día, cuando me dijiste:", "zh": "第四天早晨，我又知道了这一件事。", "t": [9625, 12837]}]}, {"id": "ch06p01", "audio": true, "sents": [{"es": "-Me gustan mucho las puestas de sol; vamos a ver una puesta de sol…", "zh": "你对我说： “我喜欢夕阳。", "t": [100, 3676]}]}, {"id": "ch06p02", "audio": true, "sents": [{"es": "-Tendremos que esperar…", "zh": "我们去看日落的壮观吧……” “可是要等啊……” “等什么？", "t": [100, 1438]}, {"es": "-¿Esperar qué?", "zh": "我们去看日落的壮观吧……” “可是要等啊……” “等什么？", "t": [1438, 2138]}]}, {"id": "ch06p03", "audio": true, "sents": [{"es": "-Que el sol se ponga.", "zh": "” “等太阳下山的时刻呀。", "t": [100, 1175]}]}, {"id": "ch06p04", "audio": true, "sents": [{"es": "Pareciste muy sorprendido primero, y después te reíste de ti mismo.", "zh": "” “等太阳下山的时刻呀。", "t": [100, 4662]}, {"es": "Y me dijiste:", "zh": "” 你露出惊讶的神气，然后又自觉可笑，说道： “我老以为我是在自己家里呢！", "t": [4662, 5438]}]}, {"id": "ch06p05", "audio": true, "sents": [{"es": "-Siempre me creo que estoy en mi tierra.", "zh": "” 你露出惊讶的神气，然后又自觉可笑，说道： “我老以为我是在自己家里呢！", "t": [100, 2100]}]}, {"id": "ch06p06", "audio": true, "sents": [{"es": "En efecto, como todo el mundo sabe, cuando es mediodía en Estados Unidos, en Francia se está poniendo el sol.", "zh": "” 这话说得不错。", "t": [100, 6550]}, {"es": "Sería suficiente poder trasladarse a Francia en un minuto para asistir a la puesta del sol, pero desgraciadamente Francia está demasiado lejos.", "zh": "若能在一分钟之内赶到法国，就可以观看落日的壮景，遗憾的是法国离得太远了。", "t": [6550, 15125]}, {"es": "En cambio, sobre tu pequeño planeta te bastaba arrastrar la silla algunos pasos para presenciar el crepúsculo cada vez que lo deseabas…", "zh": "但是，在你那小小的星球上，你只要把椅子挪几步就能看到日落了。", "t": [15125, 22212]}, {"es": "-¡Un día vi ponerse el sol cuarenta y tres veces!", "zh": "什么时候要看夕晖都能看得到…… “有一天，我看了四十三次太阳下山！", "t": [22212, 24526]}]}, {"id": "ch06p07", "audio": true, "sents": [{"es": "Y un poco más tarde añadiste: -¿Sabes?", "zh": "” 过了一会儿，你又说： “你知道……一个人愁闷的时候，都爱看西下的夕阳……” “看了四十三次太阳西下的那一天，你的心情差得很吧？", "t": [100, 3262]}, {"es": "Cuando uno está verdaderamente triste le gusta ver las puestas de sol.", "zh": "” 过了一会儿，你又说： “你知道……一个人愁闷的时候，都爱看西下的夕阳……” “看了四十三次太阳西下的那一天，你的心情差得很吧？", "t": [3262, 6750]}]}, {"id": "ch06p08", "audio": true, "sents": [{"es": "-El día que la viste cuarenta y tres veces estabas muy triste ¿verdad?", "zh": "” 小王子没有答话。", "t": [100, 3537]}]}, {"id": "ch06p09", "audio": true, "sents": [{"es": "Pero el principito no respondió.", "zh": "” 小王子没有答话。", "t": [100, 1725]}]}]}, {"id": "ch07", "title_es": "Capítulo 7", "title_zh": "第 7 章", "paras": [{"id": "ch07p00", "audio": true, "sents": [{"es": "Al quinto día y también en relación con el cordero, me fue revelado este otro secreto de la vida del principito.", "zh": "第五天，仍然是多亏了那只绵羊，小王子生活中的秘密才被泄露了出来。", "t": [100, 6925]}, {"es": "Me preguntó bruscamente y sin preámbulo, como resultado de un problema largamente meditado en silencio:", "zh": "他似乎对一个问题反复思考了许久，然后开门见山，直截了当地突然问我： “绵羊吃灌木，它也吃花吗？", "t": [6925, 12312]}]}, {"id": "ch07p01", "audio": true, "sents": [{"es": "-Si un cordero se come los arbustos, se comerá también las flores ¿no?", "zh": "” “绵羊遇见什么吃什么。", "t": [100, 3912]}]}, {"id": "ch07p02", "audio": true, "sents": [{"es": "-Un cordero se come todo lo que encuentra.", "zh": "” “带刺的花也吃？", "t": [100, 3175]}, {"es": "-¿Y también las flores que tienen espinas?", "zh": "带刺的花也吃。", "t": [3175, 5337]}]}, {"id": "ch07p03", "audio": true, "sents": [{"es": "-Sí; también las flores que tienen espinas.", "zh": "” “那刺还有什么作用呢？", "t": [100, 2525]}]}, {"id": "ch07p04", "audio": true, "sents": [{"es": "-Entonces, ¿para qué le sirven las espinas?", "zh": "” 我不知道刺还有什么作用。", "t": [100, 2425]}]}, {"id": "ch07p05", "audio": true, "sents": [{"es": "Confieso que no lo sabía.", "zh": "当时我正忙于把发动机上拧得过紧的螺栓弄下来。", "t": [100, 2488]}, {"es": "Estaba yo muy ocupado tratando de destornillar un perno demasiado apretado del motor; la avería comenzaba a parecerme cosa grave y la circunstancia de que se estuviera agotando mi provisión de agua, me hacía temer lo peor.", "zh": "最让我担心的，是饮用水已经所剩不多了。", "t": [2488, 15012]}, {"es": "-¿Para qué sirven las espinas?", "zh": "” 小王子一旦提出疑问，就要寻根究底，追问个没完，绝不会中途而废。", "t": [15012, 16513]}]}, {"id": "ch07p06", "audio": true, "sents": [{"es": "El principito no permitía nunca que se dejara sin respuesta una pregunta formulada por él.", "zh": "” 小王子一旦提出疑问，就要寻根究底，追问个没完，绝不会中途而废。", "t": [100, 5512]}, {"es": "Irritado por la resistencia que me oponía el perno, le respondí lo primero que se me ocurrió:", "zh": "” “哦？", "t": [5512, 10275]}]}, {"id": "ch07p07", "audio": true, "sents": [{"es": "-Las espinas no sirven para nada; son pura maldad de las flores.", "zh": "” 沉默了一会儿，他悻悻地说： “我不信你说的话！", "t": [100, 4700]}, {"es": "-¡Oh!", "zh": "” 沉默了一会儿，他悻悻地说： “我不信你说的话！", "t": [4700, 4838]}]}, {"id": "ch07p08", "audio": true, "sents": [{"es": "Y después de un silencio, me dijo con una especie de rencor: -¡No te creo!", "zh": "花儿弱不禁风，花儿天真无邪，她们自顾不暇呢。", "t": [100, 4850]}, {"es": "Las flores son débiles.", "zh": "她们身上长了刺，是为了给自己壮胆，为了保护自己……” 我不说话。", "t": [4850, 7225]}, {"es": "Son ingenuas.", "zh": "她们身上长了刺，是为了给自己壮胆，为了保护自己……” 我不说话。", "t": [7225, 9162]}, {"es": "Se defienden como pueden.", "zh": "她们身上长了刺，是为了给自己壮胆，为了保护自己……” 我不说话。", "t": [9162, 11500]}, {"es": "Se creen terribles con sus espinas…", "zh": "她们身上长了刺，是为了给自己壮胆，为了保护自己……” 我不说话。", "t": [11500, 13538]}]}, {"id": "ch07p09", "audio": true, "sents": [{"es": "No le respondí nada; en aquel momento me estaba diciendo a mí mismo: \"Si este perno me resiste un poco más, lo haré saltar de un martillazo\".", "zh": "这时我的念头是：“如果这颗螺栓拧不下来，我就用锤子把它砸了。", "t": [100, 8700]}, {"es": "El principito me interrumpió de nuevo mis pensamientos: -¿Tú crees que las flores…?", "zh": "” 小王子打断我的思路： “你相信，你，相信花……” “别烦我了！", "t": [8700, 12763]}]}, {"id": "ch07p10", "audio": true, "sents": [{"es": "No, no creo nada!", "zh": "我什么也不信！", "t": [100, 2500]}, {"es": "Te he respondido cualquier cosa para que te calles.", "zh": "我不过在信口开河啊。", "t": [2500, 5975]}, {"es": "Tengo que ocuparme de cosas serias.", "zh": "我，我在忙正经事呢。", "t": [5975, 7875]}]}, {"id": "ch07p11", "audio": true, "sents": [{"es": "Me miró estupefacto.", "zh": "” 他瞪着我，愣住了。", "t": [100, 2262]}, {"es": "-¡De cosas serias!", "zh": "“你在忙正经事！", "t": [2262, 3287]}]}, {"id": "ch07p12", "audio": true, "sents": [{"es": "Me miraba con mi martillo en la mano, los dedos llenos de grasa e inclinado sobre algo que le parecía muy feo.", "zh": "” 他看见我手攥锤子，两手油污，俯身对着一件他认为很丑的物件。", "t": [100, 6575]}, {"es": "-¡Hablas como las personas mayores!", "zh": "“你说话的时候像个大人！", "t": [6575, 8400]}]}, {"id": "ch07p13", "audio": true, "sents": [{"es": "Me avergonzó un poco.", "zh": "” 听了这话，我有点难为情。", "t": [100, 2312]}, {"es": "Pero él, implacable, añadió: -¡Lo confundes todo…todo lo mezclas…!", "zh": "” 听了这话，我有点难为情。", "t": [2312, 6287]}]}, {"id": "ch07p14", "audio": true, "sents": [{"es": "Estaba verdaderamente irritado; sacudía la cabeza, agitando al viento sus cabellos dorados.", "zh": "” 他真的气坏了。", "t": [100, 5374]}]}, {"id": "ch07p15", "audio": true, "sents": [{"es": "-Conozco un planeta donde vive un señor muy colorado, que nunca ha olido una flor, ni ha mirado una estrella y que jamás ha querido a nadie.", "zh": "“我知道一颗行星，上面有一位红脸先生。", "t": [100, 8175]}, {"es": "En toda su vida no ha hecho más que sumas.", "zh": "他从未爱过一个人。", "t": [8175, 11438]}, {"es": "Y todo el día se lo pasa repitiendo como tú: \"¡Yo soy un hombre serio, yo soy un hombre serio!\"…", "zh": "他什么事也没干过，只会做算术中的加法。", "t": [11438, 17638]}, {"es": "Al parecer esto le llema de orgullo.", "zh": "我是正经人！", "t": [17638, 20450]}, {"es": "Pero eso no es un hombre, ¡es un hongo!", "zh": "’真是自命不凡，神气活现！", "t": [20450, 23412]}, {"es": "-¿Un qué?", "zh": "’真是自命不凡，神气活现！", "t": [23412, 23800]}]}, {"id": "ch07p16", "audio": true, "sents": [{"es": "-Un hongo.", "zh": "可他不是人，是蘑菇！", "t": [100, 650]}]}, {"id": "ch07p17", "audio": true, "sents": [{"es": "El principito estaba pálido de cólera.", "zh": "可他不是人，是蘑菇！", "t": [100, 2087]}]}, {"id": "ch07p18", "audio": true, "sents": [{"es": "-Hace millones de años que las flores tiene espinas y hace también millones de años que los corderos, a pesar de las espinas, se comen las flores.", "zh": "” 小王子气得脸色发白。", "t": [100, 8562]}, {"es": "¿Es que no es cosa seria averiguar por qué las flores pierden el tiempo fabricando unas espinas que no les sirven para nada?", "zh": "难道我想知道，花儿为什么憋足了劲长没用的刺，这是不正经的事吗？", "t": [8562, 15638]}, {"es": "¿Es que no es importante la guerra de los corderos y las flores?", "zh": "这不比红脸胖子的加法更正经，更重要吗？", "t": [15638, 19800]}, {"es": "¿No es esto más serio e importante que las sumas de un señor gordo y colorado?", "zh": "要是我认识的世界上的一朵独一无二的花，她哪儿也不去，就爱长在我的星球上，可是却在某天早晨，被小绵羊一不留神咬死了，难道这样的事也不重要吗？", "t": [19800, 24612]}, {"es": "Y si yo sé de una flor única en el mundo y que no existe en ninguna parte más que en mi planeta; si yo sé que un buen día un corderillo puede aniquilarla sin darse cuenta de ello, ¿es que esto no es importante?", "zh": "要是我认识的世界上的一朵独一无二的花，她哪儿也不去，就爱长在我的星球上，可是却在某天早晨，被小绵羊一不留神咬死了，难道这样的事也不重要吗？", "t": [24612, 35213]}]}, {"id": "ch07p19", "audio": true, "sents": [{"es": "El principito enrojeció y después continuó:", "zh": "” 他的脸由白转红，然后说： “要是有个人爱上了一朵花，这朵花不长在亿万颗星球上，只长在他的星球上，而他只要仰望星空，想到‘我的花儿就在那儿……’，心就陶醉在幸福里，羊却吃了他心爱的花——这对他而言，简直是整个星空都黯淡无光了，难道这样的事还不重要吗？", "t": [100, 2424]}]}, {"id": "ch07p20", "audio": true, "sents": [{"es": "-Si alguien ama a una flor de la que sólo existe un ejemplar en millones y millones de estrellas, basta que las mire para ser dichoso.", "zh": "” 他的脸由白转红，然后说： “要是有个人爱上了一朵花，这朵花不长在亿万颗星球上，只长在他的星球上，而他只要仰望星空，想到‘我的花儿就在那儿……’，心就陶醉在幸福里，羊却吃了他心爱的花——这对他而言，简直是整个星空都黯淡无光了，难道这样的事还不重要吗？", "t": [100, 7538]}, {"es": "Puede decir satisfecho: \"Mi flor está allí, en alguna parte…\" ¡Pero si el cordero se la come, para él es como si de pronto todas las estrellas se apagaran!", "zh": "” 他说不出话来，突然嚎啕大哭。", "t": [7538, 17575]}, {"es": "¡Y esto no es importante!", "zh": "” 他说不出话来，突然嚎啕大哭。", "t": [17575, 19013]}]}, {"id": "ch07p21", "audio": true, "sents": [{"es": "No pudo decir más y estalló bruscamente en sollozos.", "zh": "” 他说不出话来，突然嚎啕大哭。", "t": [100, 3050]}]}, {"id": "ch07p22", "audio": true, "sents": [{"es": "La noche había caído.", "zh": "夜幕降临，我扔下手里的工具，顾不得锤子、螺栓、干渴、死亡了。", "t": [100, 2275]}, {"es": "Yo había soltado las herramientas y ya no importaban nada el martillo, el perno, la sed y la muerte.", "zh": "在一颗星球上，在我的行星地球上，有一个小王子需要安慰！", "t": [2275, 8525]}, {"es": "¡Había en una estrella, en un planeta, el mío, la Tierra, un principito a quien consolar!", "zh": "我把他搂进怀里，轻柔地摇着他。", "t": [8525, 14100]}, {"es": "Lo tomé en mis brazos y lo mecí diciéndole: \"la flor que tú quieres no corre peligro…", "zh": "我把他搂进怀里，轻柔地摇着他。", "t": [14100, 18775]}, {"es": "te dibujaré un bozal para tu cordero y una armadura para la flor…te…\".", "zh": "我抚慰他：“你爱的那朵花不会有危险的……我给你的绵羊画一个口罩……我给你的花儿画一副铠甲……我……”我也不知道我还说了什么话，只觉得自己笨嘴笨舌，不懂得该怎样安慰他，打动他……眼泪的王国太神秘了。", "t": [18775, 23075]}, {"es": "No sabía qué decirle, cómo consolarle y hacer que tuviera nuevamente confianza en mí; me sentía torpe.", "zh": "我抚慰他：“你爱的那朵花不会有危险的……我给你的绵羊画一个口罩……我给你的花儿画一副铠甲……我……”我也不知道我还说了什么话，只觉得自己笨嘴笨舌，不懂得该怎样安慰他，打动他……眼泪的王国太神秘了。", "t": [23075, 29550]}, {"es": "¡Es tan misterioso el país de las lágrimas!", "zh": "我抚慰他：“你爱的那朵花不会有危险的……我给你的绵羊画一个口罩……我给你的花儿画一副铠甲……我……”我也不知道我还说了什么话，只觉得自己笨嘴笨舌，不懂得该怎样安慰他，打动他……眼泪的王国太神秘了。", "t": [29550, 31750]}]}]}, {"id": "ch08", "title_es": "Capítulo 8", "title_zh": "第 8 章", "paras": [{"id": "ch08p00", "audio": true, "sents": [{"es": "Aprendí bien pronto a conocer mejor esta flor.", "zh": "我很快就对这朵花有了更深的了解。", "t": [100, 3438]}, {"es": "Siempre había habido en el planeta del principito flores muy simples adornadas con una sola fila de pétalos que apenas ocupaban sitio y a nadie molestaban.", "zh": "小王子生活的星球上长着很朴素的单瓣花，她们一点儿也不占地方，也不扰人，在草地上朝开暮落。", "t": [3438, 12338]}, {"es": "Aparecían entre la hierba una mañana y por la tarde se extinguían.", "zh": "而这朵花的种子不知道是从哪儿来的。", "t": [12338, 16600]}, {"es": "Pero aquella había germinado un día de una semilla llegada de quién sabe dónde, y el principito había vigilado cuidadosamente desde el primer día aquella ramita tan diferente de las que él conocía.", "zh": "然而枝条很快就停止伸展，竟开始结花蕾。", "t": [16600, 27212]}, {"es": "Podía ser una nueva especie de Baobab.", "zh": "小王子看着硕大的花苞，预感到她会绽放出奇异的花朵。", "t": [27212, 30200]}, {"es": "Pero el arbusto cesó pronto de crecer y comenzó a echar su flor.", "zh": "然而花儿躲在绿莹莹的屋子里精心打扮。", "t": [30200, 34400]}, {"es": "El principito observó el crecimiento de un enorme capullo y tenía le convencimiento de que habría de salir de allí una aparición milagrosa; pero la flor no acababa de preparar su belleza al abrigo de su envoltura verde.", "zh": "她不肯像虞美人那样，皱巴巴地就往外跑，就亮相。", "t": [34400, 45100]}]}, {"id": "ch08p01", "audio": true, "sents": [{"es": "Elegía con cuidado sus colores, se vestía lentamente y se ajustaba uno a uno sus pétalos.", "zh": "她神秘兮兮地梳妆打扮了好几天，终于在一天早晨，在太阳出来的那一刻，她露脸亮相了。", "t": [100, 6100]}, {"es": "No quería salir ya ajada como las amapolas; quería aparecer en todo el esplendor de su belleza.", "zh": "精心打扮了几天，算准了出场的时间，她却打着哈欠说： “唉！", "t": [6100, 12275]}, {"es": "¡Ah, era muy coqueta aquella flor!", "zh": "精心打扮了几天，算准了出场的时间，她却打着哈欠说： “唉！", "t": [12275, 15225]}, {"es": "Su misteriosa preparación duraba días y días.", "zh": "精心打扮了几天，算准了出场的时间，她却打着哈欠说： “唉！", "t": [15225, 18825]}, {"es": "Hasta que una mañana, precisamente al salir el sol se mostró espléndida.", "zh": "我刚刚睡醒呢……请你原谅……我的妆还零乱呢……” 小王子忍不住赞叹： “您真美啊！", "t": [18825, 22526]}]}, {"id": "ch08p02", "audio": true, "sents": [{"es": "La flor, que había trabajado con tanta precisión, dijo bostezando: -¡Ah, perdóname…", "zh": "” “是吗，”花儿柔声说，“我和太阳同时诞生……” 小王子看准她并非谦恭的女子，不过，她确实美丽动人！", "t": [100, 4838]}, {"es": "apenas acabo de despertarme…", "zh": "” “是吗，”花儿柔声说，“我和太阳同时诞生……” 小王子看准她并非谦恭的女子，不过，她确实美丽动人！", "t": [4838, 6600]}, {"es": "estoy toda despeinada…!", "zh": "” “是吗，”花儿柔声说，“我和太阳同时诞生……” 小王子看准她并非谦恭的女子，不过，她确实美丽动人！", "t": [6600, 7900]}]}, {"id": "ch08p03", "audio": true, "sents": [{"es": "El principito no pudo contener su admiración: -¡Qué hermosa eres!", "zh": "“是吃早点的时候了吧。", "t": [100, 4575]}, {"es": "-¿Verdad?", "zh": "“是吃早点的时候了吧。", "t": [4575, 5962]}, {"es": "-respondió dulcemente la flor-.", "zh": "“是吃早点的时候了吧。", "t": [5962, 8600]}, {"es": "He nacido al mismo tiempo que el sol.", "zh": "”很快她又说。", "t": [8600, 11450]}, {"es": "El principito adivinó exactamente que ella no era muy modesta ciertamente, pero ¡era tan conmovedora!", "zh": "“劳驾您给我……” 小王子为自己的疏忽而感到羞惭，赶紧找了一壶清水，侍候花儿用餐。", "t": [11450, 16874]}]}, {"id": "ch08p04", "audio": true, "sents": [{"es": "-Me parece que ya es hora de desayunar - añadió la flor -; si tuvieras la bondad de pensar un poco en mí…", "zh": "不久，她爱慕虚荣的性情开始折磨他。", "t": [100, 5488]}]}, {"id": "ch08p05", "audio": true, "sents": [{"es": "Y el principito, muy confuso, habiendo ido a buscar una regadera la roció abundantemente con agua fresca.", "zh": "她说： “这儿也许有老虎吧，老虎的爪子锋利得很呢！", "t": [100, 5500]}]}, {"id": "ch08p06", "audio": true, "sents": [{"es": "Y así, ella lo había atormentado con su vanidad un poco sombría.", "zh": "” “我的星球上没有老虎。", "t": [100, 4650]}, {"es": "Un día, por ejemplo, hablando de sus cuatro espinas, dijo al principito: -¡Ya pueden venir los tigres, con sus garras!", "zh": "“我可不是草。", "t": [4650, 11074]}]}, {"id": "ch08p07", "audio": true, "sents": [{"es": "-No hay tigres en mi planeta -observó el principito- y, además, los tigres no comen hierba.", "zh": "您没有屏风吗？", "t": [100, 5112]}]}, {"id": "ch08p08", "audio": true, "sents": [{"es": "-Yo no soy una hierba -respondió dulcemente la flor.", "zh": "” “你居然讨厌风啊……这可不好。", "t": [100, 3050]}]}, {"id": "ch08p09", "audio": true, "sents": [{"es": "-Perdóname…", "zh": "”小王子对她有了看法。", "t": [100, 688]}]}, {"id": "ch08p10", "audio": true, "sents": [{"es": "-No temo a los tigres, pero tengo miedo a las corrientes de aire.", "zh": "“这朵花倒很复杂……” “晚上您用罩子把我罩起来吧。", "t": [100, 4438]}, {"es": "¿No tendrás un biombo?", "zh": "“这朵花倒很复杂……” “晚上您用罩子把我罩起来吧。", "t": [4438, 5625]}]}, {"id": "ch08p11", "audio": true, "sents": [{"es": "\"Miedo a las corrientes de aire no es una suerte para una planta -pensó el principito-.", "zh": "您这儿太冷，位置不好。", "t": [100, 5325]}, {"es": "Esta flor es demasiado complicada…\" -Por la noche me cubrirás con un fanal…", "zh": "来这儿的时候她还是一颗种子呢，怎么可能了解别的地方呢。", "t": [5325, 9525]}, {"es": "hace mucho frío en tu tierra.", "zh": "来这儿的时候她还是一颗种子呢，怎么可能了解别的地方呢。", "t": [9525, 11850]}, {"es": "No se está muy a gusto; allá de donde yo vengo…", "zh": "她撒的谎幼稚可笑，让人一下子就能识破。", "t": [11850, 14574]}]}, {"id": "ch08p12", "audio": true, "sents": [{"es": "La flor se interrumpió; había llegado allí en forma de semilla y no era posible que conociera otros mundos.", "zh": "她觉得丢脸，便咳嗽了两三声，想把过错推到小王子身上去： “我要的屏风呢？", "t": [100, 6076]}]}, {"id": "ch08p13", "audio": true, "sents": [{"es": "Humillada por haberse dejado sorprender inventando un mentira tan ingenua, tosió dos o tres veces para atraerse la simpatía del principito.", "zh": "……” “我正要去找屏风，是您和我说话的呀！", "t": [100, 8350]}, {"es": "-¿Y el biombo?", "zh": "” 她又故意咳嗽，存心让他内疚不安。", "t": [8350, 8987]}]}, {"id": "ch08p14", "audio": true, "sents": [{"es": "-Iba a buscarlo, pero como no dejabas de hablarme…", "zh": "小王子很怜爱她，但她的做作令他生疑。", "t": [100, 2638]}]}, {"id": "ch08p15", "audio": true, "sents": [{"es": "Insistió en su tos para darle al menos remordimientos.", "zh": "他是个做事一丝不苟的人，常把无关紧要的闲话当真，难免招来不少麻烦。", "t": [100, 3163]}]}, {"id": "ch08p16", "audio": true, "sents": [{"es": "De esta manera el principito, a pesar de la buena voluntad de su amor, había llegado a dudar de ella.", "zh": "有一天，他向我倾诉他的心事：“我本不该听信她的话的。", "t": [100, 6275]}, {"es": "Había tomado en serio palabras sin importancia y se sentía desgraciado.", "zh": "永远也别信花儿讲的话。", "t": [6275, 10000]}]}, {"id": "ch08p17", "audio": true, "sents": [{"es": "\"Yo no debía hacerle caso -me confesó un día el principito- nunca hay que hacer caso a las flores, basta con mirarlas y olerlas.", "zh": "我的花熏香了我的星球，但我不懂得为此高兴。", "t": [100, 8050]}, {"es": "Mi flor embalsamaba el planeta, pero yo no sabía gozar con eso…", "zh": "她说的老虎爪子的话，本来应该打动我的心，我却生了她的气。", "t": [8050, 12500]}, {"es": "Aquella historia de garra y tigres que tanto me molestó, hubiera debido enternecerme\".", "zh": "” 他还说： “那时我真是不懂事。", "t": [12500, 17113]}]}, {"id": "ch08p18", "audio": true, "sents": [{"es": "Y me contó todavía:", "zh": "要对一个人下定论，不应听其言，而应观其行。", "t": [100, 1224]}]}, {"id": "ch08p19", "audio": true, "sents": [{"es": "\"¡No supe comprender nada entonces!", "zh": "要对一个人下定论，不应听其言，而应观其行。", "t": [100, 3125]}, {"es": "Debí juzgarla por sus actos y no por sus palabras.", "zh": "她芬芳馥郁，赏心悦目，我不应抛下她一走了之！", "t": [3125, 6875]}, {"es": "¡La flor perfumaba e iluminaba mi vida y jamás debí huir de allí!", "zh": "我不理解她那不聪明的谎言饱含的深情。", "t": [6875, 11200]}, {"es": "¡No supe adivinar la ternura que ocultaban sus pobres astucias!", "zh": "花儿是缺点不少、但优点也很多的矛盾的东西！", "t": [11200, 15575]}, {"es": "¡Son tan contradictorias las flores!", "zh": "花儿是缺点不少、但优点也很多的矛盾的东西！", "t": [15575, 18662]}, {"es": "Pero yo era demasiado joven para saber amarla\".", "zh": "那时我年纪太轻，不懂得珍惜她，爱她。", "t": [18662, 21125]}]}]}, {"id": "ch09", "title_es": "Capítulo 9", "title_zh": "第 9 章", "paras": [{"id": "ch09p00", "audio": true, "sents": [{"es": "Creo que el principito aprovechó la migración de una bandada de pájaros silvestres para su evasión.", "zh": "我估计他是趁候鸟迁徙时出走的。", "t": [100, 5875]}, {"es": "La mañana de la partida, puso en orden el planeta.", "zh": "出走的那天早晨，他认真收拾整理他的星球，仔细疏通火山口。", "t": [5875, 9625]}, {"es": "Deshollinó cuidadosamente sus volcanes en actividad, de los cuales poseía dos, que le eran muy útiles para calentar el desayuno todas las mañanas.", "zh": "可是正如他说的：“日后的事很难说！", "t": [9625, 18538]}, {"es": "Tenía, además, un volcán extinguido.", "zh": "所以他也疏通死火山。", "t": [18538, 21625]}, {"es": "Deshollinó también el volcán extinguido, pues, como él decía, nunca se sabe lo que puede ocurrir.", "zh": "经过疏通，火山里的火焰缓缓燃烧，火山就不会喷发。", "t": [21625, 27662]}, {"es": "Si los volcanes están bien deshollinados, arden sus erupciones, lenta y regularmente.", "zh": "火山喷发的道理与炉火一样。", "t": [27662, 33450]}, {"es": "Las erupciones volcánicas son como el fuego de nuestras chimeneas.", "zh": "我们这些人太渺小，没有疏通火山的能力，所以火山才给我们造成很多麻烦。", "t": [33450, 37900]}, {"es": "Es evidente que en nuestra Tierra no hay posibilidad de deshollinar los volcanes; los hombres somos demasiado pequeños.", "zh": "他知道自己不会再回来了。", "t": [37900, 44875]}, {"es": "Por eso nos dan tantos disgustos.", "zh": "那天早晨，他觉得所有的家务活干起来都挺亲切的。", "t": [44875, 46837]}]}, {"id": "ch09p01", "audio": true, "sents": [{"es": "El principito arrancó también con un poco de melancolía los últimos brotes de baobabs.", "zh": "最后一次给花儿浇水，准备给她盖上罩子，他竟觉得他想哭。", "t": [100, 5338]}, {"es": "Creía que no iba a volver nunca.", "zh": "他对花儿说：“别了。", "t": [5338, 8112]}, {"es": "Pero todos aquellos trabajos le parecieron aquella mañana extremadamente dulces.", "zh": "”他又说。", "t": [8112, 13300]}, {"es": "Y cuando regó por última vez la flor y se dispuso a ponerla al abrigo del fanal, sintió ganas de llorar.", "zh": "她终于对他说：“我以前真傻，请你原谅。", "t": [13300, 18788]}]}, {"id": "ch09p02", "audio": true, "sents": [{"es": "-Adiós -le dijo a la flor.", "zh": "好好地享受生活吧，愿你幸福。", "t": [100, 2612]}, {"es": "Esta no respondió.", "zh": "” 她并没有责备他的意思。", "t": [2612, 3724]}]}, {"id": "ch09p03", "audio": true, "sents": [{"es": "-Adiós -repitió el principito.", "zh": "他觉得挺意外。", "t": [100, 1913]}]}, {"id": "ch09p04", "audio": true, "sents": [{"es": "La flor tosió, pero no porque estuviera resfriada.", "zh": "他不知所措地站在那儿，高举着罩子。", "t": [100, 2724]}]}, {"id": "ch09p05", "audio": true, "sents": [{"es": "-He sido una tonta -le dijo al fin la flor-.", "zh": "他不理解她的脉脉深情。", "t": [100, 3438]}, {"es": "Perdóname.", "zh": "他不理解她的脉脉深情。", "t": [3438, 5050]}, {"es": "Procura ser feliz.", "zh": "“是的，我爱你，”花儿对他说，“你丝毫没察觉到我对你的爱，这是我的错。", "t": [5050, 6100]}]}, {"id": "ch09p06", "audio": true, "sents": [{"es": "Se sorprendió por la ausencia de reproches y quedó desconcertado, con el fanal en el aire, no comprendiendo esta tranquila mansedumbre.", "zh": "如今说也没用了。", "t": [100, 7000]}]}, {"id": "ch09p07", "audio": true, "sents": [{"es": "-Sí, yo te quiero -le dijo la flor-, ha sido culpa mía que tú no lo sepas; pero eso no tiene importancia.", "zh": "好好地享受生活吧，愿你幸福……你把这罩子放一边去吧，我不需要它。", "t": [100, 5750]}]}, {"id": "ch09p08", "audio": true, "sents": [{"es": "Y tú has sido tan tonto como yo.", "zh": "” “可是风……” “我并非如此的弱不禁风……清新的夜风对我的健康有好处，我是一朵花儿嘛。", "t": [100, 2850]}, {"es": "Trata de ser feliz…", "zh": "” “可是风……” “我并非如此的弱不禁风……清新的夜风对我的健康有好处，我是一朵花儿嘛。", "t": [2850, 4862]}, {"es": "Y suelta de una vez ese fanal; ya no lo quiero.", "zh": "” “可是风……” “我并非如此的弱不禁风……清新的夜风对我的健康有好处，我是一朵花儿嘛。", "t": [4862, 7562]}]}, {"id": "ch09p09", "audio": true, "sents": [{"es": "-Pero el viento…", "zh": "” “可是风……” “我并非如此的弱不禁风……清新的夜风对我的健康有好处，我是一朵花儿嘛。", "t": [100, 800]}]}, {"id": "ch09p10", "audio": true, "sents": [{"es": "-No estoy tan resfriada como para…", "zh": "” “可是动物……” “如果我想认识蝴蝶，就必须能承受两三条毛虫。", "t": [100, 2938]}, {"es": "El aire fresco de la noche me hará bien.", "zh": "” “可是动物……” “如果我想认识蝴蝶，就必须能承受两三条毛虫。", "t": [2938, 5912]}, {"es": "Soy una flor.", "zh": "” “可是动物……” “如果我想认识蝴蝶，就必须能承受两三条毛虫。", "t": [5912, 6763]}]}, {"id": "ch09p11", "audio": true, "sents": [{"es": "-Y los animales…", "zh": "” “可是动物……” “如果我想认识蝴蝶，就必须能承受两三条毛虫。", "t": [100, 1000]}]}, {"id": "ch09p12", "audio": true, "sents": [{"es": "-Será necesario que soporte dos o tres orugas, si quiero conocer las mariposas; creo que son muy hermosas.", "zh": "要不，谁会看望我呢？", "t": [100, 7100]}, {"es": "Si no ¿quién vendrá a visitarme?", "zh": "我一点不畏惧大的动物，我有爪子呀。", "t": [7100, 9938]}, {"es": "Tú estarás muy lejos.", "zh": "我一点不畏惧大的动物，我有爪子呀。", "t": [9938, 12162]}, {"es": "En cuanto a las fieras, no las temo: yo tengo mis garras.", "zh": "” 她天真地伸出她的四根刺。", "t": [12162, 15537]}]}, {"id": "ch09p13", "audio": true, "sents": [{"es": "Y le mostraba ingenuamente sus cuatro espinas.", "zh": "然后又说： “别婆婆妈妈，磨磨蹭蹭的了，闹得人心乱。", "t": [100, 3600]}, {"es": "Luego añadió:", "zh": "然后又说： “别婆婆妈妈，磨磨蹭蹭的了，闹得人心乱。", "t": [3600, 4450]}]}, {"id": "ch09p14", "audio": true, "sents": [{"es": "-Y no prolongues más tu despedida.", "zh": "你既已下了决心，那就走吧。", "t": [100, 2912]}, {"es": "Puesto que has decidido partir, vete de una vez.", "zh": "” 她不愿让小王子看见她哭。", "t": [2912, 5450]}]}, {"id": "ch09p15", "audio": true, "sents": [{"es": "La flor no quería que la viese llorar: era tan orgullosa..", "zh": "她是一朵多么骄傲的花儿哟……", "t": [100, 3238]}]}]}, {"id": "ch10", "title_es": "Capítulo 10", "title_zh": "第 10 章", "paras": [{"id": "ch10p00", "audio": true, "sents": [{"es": "Se encontraba en la región de los asteroides 325, 326, 327, 328, 329 y 330.", "zh": "他居住的星球位于小行星325号、326号、327号、328号、329号、330号所在的地区。", "t": [100, 8712]}, {"es": "Para ocuparse en algo e instruirse al mismo tiempo decidió visitarlos.", "zh": "他居住的星球位于小行星325号、326号、327号、328号、329号、330号所在的地区。", "t": [8712, 14426]}]}, {"id": "ch10p01", "audio": true, "sents": [{"es": "El primero estaba habitado por un rey.", "zh": "于是他决定首先拜访它们，在那儿找事干，并增长见识。", "t": [100, 3025]}, {"es": "El rey, vestido de púrpura y armiño, estaba sentado sobre un trono muy sencillo y, sin embargo, majestuoso.", "zh": "325号行星上住着一位国王。", "t": [3025, 9113]}]}, {"id": "ch10p02", "audio": true, "sents": [{"es": "-¡Ah, -exclamó el rey al divisar al principito-, aquí tenemos un súbdito!", "zh": "他穿着镶有紫红色袖口和领口的白鼬皮衣服，坐在式样简单然而威严的宝座上。", "t": [100, 3963]}]}, {"id": "ch10p03", "audio": true, "sents": [{"es": "El principito se preguntó:", "zh": "看见小王子，国王大声嚷： “哈！", "t": [100, 1500]}]}, {"id": "ch10p04", "audio": true, "sents": [{"es": "\"¿Cómo es posible que me reconozca si nunca me ha visto?\"", "zh": "来了一个老百姓。", "t": [100, 2813]}]}, {"id": "ch10p05", "audio": true, "sents": [{"es": "Ignoraba que para los reyes el mundo está muy simplificado.", "zh": "” 小王子心想： “他从未见过我，怎么认得出我呢？", "t": [100, 4025]}, {"es": "Todos los hombres son súbditos.", "zh": "” 他不知道，国王们把世界看得很简单，他们以为普天下的人都是他的百姓。", "t": [4025, 5738]}]}, {"id": "ch10p06", "audio": true, "sents": [{"es": "-Aproxímate para que te vea mejor -le dijo el rey, que estaba orgulloso de ser por fin el rey de alguien.", "zh": "” 他不知道，国王们把世界看得很简单，他们以为普天下的人都是他的百姓。", "t": [100, 6588]}, {"es": "El principito buscó donde sentarse, pero el planeta estaba ocupado totalmente por el magnífico manto de armiño.", "zh": "他对小王子说：“过来，让我好好地瞧瞧你。", "t": [6588, 12425]}]}, {"id": "ch10p07", "audio": true, "sents": [{"es": "Se quedó, pues, de pie, pero como estaba cansado, bostezó.", "zh": "” 小王子用眼睛搜寻可坐之处，可是行星被国王豪华的鼬皮塞满了，他只好站着，因为累了，他打了个哈欠。", "t": [100, 3237]}]}, {"id": "ch10p08", "audio": true, "sents": [{"es": "-La etiqueta no permite bostezar en presencia del rey -le dijo el monarca-.", "zh": "” 小王子用眼睛搜寻可坐之处，可是行星被国王豪华的鼬皮塞满了，他只好站着，因为累了，他打了个哈欠。", "t": [100, 5000]}, {"es": "Te lo prohíbo.", "zh": "“在国王面前打哈欠，违反礼节，我不准你打哈欠。", "t": [5000, 5674]}]}, {"id": "ch10p09", "audio": true, "sents": [{"es": "-No he podido evitarlo -respondió el principito muy confuso-, he hecho un viaje muy largo y apenas he dormido…", "zh": "”国王说道。", "t": [100, 6025]}]}, {"id": "ch10p10", "audio": true, "sents": [{"es": "-Entonces -le dijo el rey- te ordeno que bosteces.", "zh": "我长途跋涉，没有睡眠……” “既然如此，”国王对他说，“我命令你打哈欠。", "t": [100, 4088]}, {"es": "Hace años que no veo bostezar a nadie.", "zh": "我长途跋涉，没有睡眠……” “既然如此，”国王对他说，“我命令你打哈欠。", "t": [4088, 7150]}, {"es": "Los bostezos son para mí algo curioso.", "zh": "我已经多年没看见别人打哈欠了。", "t": [7150, 10288]}, {"es": "¡Vamos, bosteza otra vez, te lo ordeno!", "zh": "我已经多年没看见别人打哈欠了。", "t": [10288, 12413]}]}, {"id": "ch10p11", "audio": true, "sents": [{"es": "-Me da vergüenza…", "zh": "依我看，打哈欠挺好玩的。", "t": [100, 1138]}, {"es": "ya no tengo ganas…", "zh": "快！", "t": [1138, 2400]}, {"es": "-dijo el principito enrojeciendo.", "zh": "这是命令。", "t": [2400, 5025]}, {"es": "-¡Hum, hum!", "zh": "” “您的命令让我害怕……我打不了……”小王子涨红了脸。", "t": [5025, 6662]}, {"es": "-respondió el rey-.", "zh": "” “您的命令让我害怕……我打不了……”小王子涨红了脸。", "t": [6662, 8688]}, {"es": "¡Bueno!", "zh": "” “您的命令让我害怕……我打不了……”小王子涨红了脸。", "t": [8688, 10088]}, {"es": "Te ordeno tan pronto que bosteces y que no bosteces…", "zh": "” “您的命令让我害怕……我打不了……”小王子涨红了脸。", "t": [10088, 12725]}]}, {"id": "ch10p12", "audio": true, "sents": [{"es": "Tartamudeaba un poco y parecía vejado, pues el rey daba gran importancia a que su autoridad fuese respetada.", "zh": "“嗯，嗯，”国王说，“那么我……我命令你一会儿打，一会儿不打……” 显然，挨了小王子的冲撞，他有点气恼，话也说不流利了。", "t": [100, 5850]}]}, {"id": "ch10p13", "audio": true, "sents": [{"es": "Era un monarca absoluto, pero como era muy bueno, daba siempre órdenes razonables.", "zh": "“嗯，嗯，”国王说，“那么我……我命令你一会儿打，一会儿不打……” 显然，挨了小王子的冲撞，他有点气恼，话也说不流利了。", "t": [100, 4638]}]}, {"id": "ch10p14", "audio": true, "sents": [{"es": "Si yo ordenara -decía frecuentemente-, si yo ordenara a un general que se transformara en ave marina y el general no me obedeciese, la culpa no sería del general, sino mía\".", "zh": "国王最关心的是别人尊重他的权威，他不允许别人违抗他的命令，他是一个典型的专制君王，但他毕竟是个善良之辈，下达的命令都合乎情理。", "t": [100, 10375]}, {"es": "-¿Puedo sentarme?", "zh": "“要是我向一个将军下令，要他变成海鸟，将军是不愿服从的。", "t": [10375, 12212]}, {"es": "-preguntó tímidamente el principito.", "zh": "“要是我向一个将军下令，要他变成海鸟，将军是不愿服从的。", "t": [12212, 14124]}]}, {"id": "ch10p15", "audio": true, "sents": [{"es": "-Te ordeno sentarte -le respondió el rey-, recogiendo majestuosamente un faldón de su manto de armiño.", "zh": "这样，错不在将军，错在我身上。", "t": [100, 5475]}]}, {"id": "ch10p16", "audio": true, "sents": [{"es": "El principito estaba sorprendido.", "zh": "”小王子怯怯地问。", "t": [100, 2862]}, {"es": "Aquel planeta era tan pequeño que no se explicaba sobre quién podría reinar aquel rey.", "zh": "“我命令你坐下。", "t": [2862, 7275]}]}, {"id": "ch10p17", "audio": true, "sents": [{"es": "-Señor -le dijo-, perdóneme si le pregunto…", "zh": "小王子有个问题弄不明白：这颗星球小得惊人，国王统治什么？", "t": [100, 2476]}]}, {"id": "ch10p18", "audio": true, "sents": [{"es": "-Te ordeno que me preguntes -se apresuró a decir el rey.", "zh": "小王子有个问题弄不明白：这颗星球小得惊人，国王统治什么？", "t": [100, 3050]}]}, {"id": "ch10p19", "audio": true, "sents": [{"es": "-Señor…", "zh": "小王子有个问题弄不明白：这颗星球小得惊人，国王统治什么？", "t": [100, 775]}, {"es": "¿sobre qué ejerce su poder?", "zh": "“陛下……”他说，“请原谅我向您提个问题……” “我命令你向我提问题……”国王急忙说。", "t": [775, 2188]}]}, {"id": "ch10p20", "audio": true, "sents": [{"es": "-Sobre todo -contestó el rey con gran ingenuidad.", "zh": "“陛下……”他说，“请原谅我向您提个问题……” “我命令你向我提问题……”国王急忙说。", "t": [100, 3588]}, {"es": "-¿Sobre todo?", "zh": "“陛下……”他说，“请原谅我向您提个问题……” “我命令你向我提问题……”国王急忙说。", "t": [3588, 4250]}]}, {"id": "ch10p21", "audio": true, "sents": [{"es": "El rey, con un gesto sencillo, señaló su planeta, los otros planetas y las estrellas.", "zh": "“陛下……您统治什么？", "t": [100, 6088]}, {"es": "-¿Sobre todo eso?", "zh": "” “统治一切！", "t": [6088, 8050]}, {"es": "-volvió a preguntar el principito.", "zh": "” 国王指指他的星球，其他星球，所有的星球。", "t": [8050, 9713]}]}, {"id": "ch10p22", "audio": true, "sents": [{"es": "-Sobre todo eso…", "zh": "“所有这一切？", "t": [100, 1300]}, {"es": "-respondió el rey.", "zh": "“所有这一切？", "t": [1300, 2338]}]}, {"id": "ch10p23", "audio": true, "sents": [{"es": "No era sólo un monarca absoluto, era, además, un monarca universal.", "zh": "“所有这一切……”国王答道。", "t": [100, 4888]}, {"es": "-¿Y las estrellas le obedecen?", "zh": "因为他不但是个专制君主，还是宇宙之王。", "t": [4888, 7450]}, {"es": "-¡Naturalmente!", "zh": "因为他不但是个专制君主，还是宇宙之王。", "t": [7450, 9362]}, {"es": "-le dijo el rey-.", "zh": "“所有的星星都听命于您吗？", "t": [9362, 11212]}, {"es": "Y obedecen en seguida, pues yo no tolero la indisciplina.", "zh": "“所有的星星都听命于您吗？", "t": [11212, 14362]}]}, {"id": "ch10p24", "audio": true, "sents": [{"es": "Un poder semejante dejó maravillado al principito.", "zh": "” “当然啦，”国王说，“它们令出即行。", "t": [100, 3750]}, {"es": "Si él disfrutara de un poder de tal naturaleza, hubiese podido asistir en el mismo día, no a cuarenta y tres, sino a setenta y dos, a cien, o incluso a doscientas puestas de sol, sin tener necesidad de arrastrar su silla.", "zh": "如果他也掌握这样的权力，一天之内他就可以不止观赏四十三次，而是观赏七十二次，甚至一百次，或两百次日落，还不用挪动椅子！", "t": [3750, 17088]}, {"es": "Y como se sentía un poco triste al recordar su pequeño planeta abandonado, se atrevió a solicitar una gracia al rey:", "zh": "想到被他遗弃的小行星，他有点伤感惆怅。", "t": [17088, 23263]}]}, {"id": "ch10p25", "audio": true, "sents": [{"es": "-Me gustaría ver una puesta de sol…", "zh": "想到被他遗弃的小行星，他有点伤感惆怅。", "t": [100, 2862]}, {"es": "Deme ese gusto…", "zh": "他壮壮胆，请求国王开恩： “我想观看夕阳西下……求您开恩……命令太阳下去吧……” “如果我命令将军像蝴蝶那样，在花间飞来飞去，或命令他写一部悲剧，或变成海鸟，如果将军接到命令后不愿执行，你说是他的错还是我的错？", "t": [2862, 4938]}, {"es": "Ordénele al sol que se ponga…", "zh": "他壮壮胆，请求国王开恩： “我想观看夕阳西下……求您开恩……命令太阳下去吧……” “如果我命令将军像蝴蝶那样，在花间飞来飞去，或命令他写一部悲剧，或变成海鸟，如果将军接到命令后不愿执行，你说是他的错还是我的错？", "t": [4938, 6512]}]}, {"id": "ch10p26", "audio": true, "sents": [{"es": "-Si yo le diera a un general la orden de volar de flor en flor como una mariposa, o de escribir una tragedia, o de transformarse en ave marina y el general no ejecutase la orden recibida ¿de quién sería la culpa, mía o de él?", "zh": "他壮壮胆，请求国王开恩： “我想观看夕阳西下……求您开恩……命令太阳下去吧……” “如果我命令将军像蝴蝶那样，在花间飞来飞去，或命令他写一部悲剧，或变成海鸟，如果将军接到命令后不愿执行，你说是他的错还是我的错？", "t": [100, 12537]}]}, {"id": "ch10p27", "audio": true, "sents": [{"es": "-La culpa sería de usted -le dijo el principito con firmeza.", "zh": "”小王子不假思索便脱口而出。", "t": [100, 3326]}]}, {"id": "ch10p28", "audio": true, "sents": [{"es": "-Exactamente.", "zh": "“你说得对，不能强人所难。", "t": [100, 1950]}, {"es": "Sólo hay que pedir a cada uno, lo que cada uno puede dar -continuó el rey.", "zh": "“权威首先必须建筑在理性上。", "t": [1950, 6800]}, {"es": "La autoridad se apoya antes que nada en la razón.", "zh": "如果你命令你的人民跳海，他们定会造反。", "t": [6800, 10300]}, {"es": "Si ordenas a tu pueblo que se tire al mar, el pueblo hará la revolución.", "zh": "我有命令百姓服从的权利，那是因为我的命令合符情理。", "t": [10300, 14912]}, {"es": "Yo tengo derecho a exigir obediencia, porque mis órdenes son razonables.", "zh": "” “那么，我要求的日落呢？", "t": [14912, 20000]}, {"es": "-¿Entonces mi puesta de sol?", "zh": "一旦提出一个问题，他是不会中途而废的。", "t": [20000, 22425]}, {"es": "-recordó el principito, que jamás olvidaba su pregunta una vez que la había formulado.", "zh": "“你会看到你要求的日落的，我会发布命令。", "t": [22425, 26576]}]}, {"id": "ch10p29", "audio": true, "sents": [{"es": "-Tendrás tu puesta de sol.", "zh": "要科学管理一个国家，下命令应等时机成熟。", "t": [100, 2412]}, {"es": "La exigiré.", "zh": "要科学管理一个国家，下命令应等时机成熟。", "t": [2412, 4138]}, {"es": "Pero, según me dicta mi ciencia gobernante, esperaré que las condiciones sean favorables.", "zh": "” “什么时候时机才成熟呢？", "t": [4138, 9538]}, {"es": "-¿Y cuándo será eso?", "zh": "“嗯，嗯，首先我要查看大皇历。", "t": [9538, 11588]}, {"es": "-¡Ejem, ejem!", "zh": "“嗯，嗯，首先我要查看大皇历。", "t": [11588, 13512]}, {"es": "-le respondió el rey, consultando previamente un enorme calendario-, ¡ejem, ejem!", "zh": "嗯，嗯，要等到……今晚……十时四十分左右……左右……你会看到他们怎样执行我的命令。", "t": [13512, 18488]}, {"es": "será hacia…", "zh": "嗯，嗯，要等到……今晚……十时四十分左右……左右……你会看到他们怎样执行我的命令。", "t": [18488, 19538]}, {"es": "hacia…", "zh": "嗯，嗯，要等到……今晚……十时四十分左右……左右……你会看到他们怎样执行我的命令。", "t": [19538, 20125]}, {"es": "será hacia las siete cuarenta.", "zh": "” 小王子打了个哈欠。", "t": [20125, 22575]}, {"es": "Ya verás cómo se me obedece.", "zh": "” 小王子打了个哈欠。", "t": [22575, 24150]}]}, {"id": "ch10p30", "audio": true, "sents": [{"es": "El principito bostezó.", "zh": "他感到惋惜，因为他的要求泡汤了。", "t": [100, 2288]}, {"es": "Lamentaba su puesta de sol frustrada y además se estaba aburriendo ya un poco.", "zh": "再说，他已经有点儿腻烦了。", "t": [2288, 6400]}]}, {"id": "ch10p31", "audio": true, "sents": [{"es": "-Ya no tengo nada que hacer aquí -le dijo al rey-.", "zh": "“我在这儿没事可干了，”他对国王说，“我要告辞了！", "t": [100, 3588]}, {"es": "Me voy.", "zh": "“我在这儿没事可干了，”他对国王说，“我要告辞了！", "t": [3588, 4062]}]}, {"id": "ch10p32", "audio": true, "sents": [{"es": "-No partas -le respondió el rey que se sentía muy orgulloso de tener un súbdito-, no te vayas y te hago ministro.", "zh": "”国王说，拥有一个百姓，对他来说是一件值得自豪的事。", "t": [100, 7075]}, {"es": "-¿Ministro de qué?", "zh": "“别走，我任命你为部长！", "t": [7075, 8925]}, {"es": "-¡De…", "zh": "“别走，我任命你为部长！", "t": [8925, 9175]}, {"es": "de justicia!", "zh": "“别走，我任命你为部长！", "t": [9175, 10962]}, {"es": "-¡Pero si aquí no hay nadie a quien juzgar!", "zh": "” “哪个部的部长？", "t": [10962, 12987]}]}, {"id": "ch10p33", "audio": true, "sents": [{"es": "-Eso no se sabe -le dijo el rey-.", "zh": "” “可这儿没人可审呀！", "t": [100, 2925]}, {"es": "Nunca he recorrido todo mi reino.", "zh": "” “可这儿没人可审呀！", "t": [2925, 5900]}, {"es": "Estoy muy viejo y el caminar me cansa.", "zh": "” “这可就难说了，”国王说，“我还没视察过我的王国呢。", "t": [5900, 8988]}, {"es": "Y como no hay sitio para una carroza…", "zh": "” “这可就难说了，”国王说，“我还没视察过我的王国呢。", "t": [8988, 11250]}, {"es": "-¡Oh!", "zh": "我上了年纪，这儿又没有停马车的地方，走路又太累了。", "t": [11250, 12300]}, {"es": "Pero yo ya he visto…", "zh": "我上了年纪，这儿又没有停马车的地方，走路又太累了。", "t": [12300, 13588]}, {"es": "-dijo el principito que se inclinó para echar una ojeada al otro lado del planeta-.", "zh": "” “啊，我已经看过了。", "t": [13588, 18688]}, {"es": "Allá abajo no hay nadie tampoco..", "zh": "”小王子俯身朝星球的另一端又瞟了一眼。", "t": [18688, 20525]}]}, {"id": "ch10p34", "audio": true, "sents": [{"es": "-Te juzgarás a ti mismo -le respondió el rey-.", "zh": "”小王子俯身朝星球的另一端又瞟了一眼。", "t": [100, 3650]}, {"es": "Es lo más difícil.", "zh": "“那儿也没一个人……” “你就审你自己吧，”国王说，“这是最难办的事。", "t": [3650, 5662]}, {"es": "Es mucho más difícil juzgarse a sí mismo, que juzgar a los otros.", "zh": "“那儿也没一个人……” “你就审你自己吧，”国王说，“这是最难办的事。", "t": [5662, 10288]}, {"es": "Si consigues juzgarte rectamente es que eres un verdadero sabio.", "zh": "你若能审自己，你就是真正的聪明人。", "t": [10288, 13800]}]}, {"id": "ch10p35", "audio": true, "sents": [{"es": "-Yo puedo juzgarme a mí mismo en cualquier parte y no tengo necesidad de vivir aquí.", "zh": "” “我嘛，”小王子说，“无论在什么地方我都能审自己，无需住在这儿。", "t": [100, 5062]}, {"es": "-¡Ejem, ejem!", "zh": "” “我嘛，”小王子说，“无论在什么地方我都能审自己，无需住在这儿。", "t": [5062, 6988]}, {"es": "Creo -dijo el rey- que en alguna parte del planeta vive una rata vieja; yo la oigo por la noche.", "zh": "”国王说。", "t": [6988, 13262]}, {"es": "Tu podrás juzgar a esta rata vieja.", "zh": "我在夜里听到的。", "t": [13262, 16188]}, {"es": "La condenarás a muerte de vez en cuando.", "zh": "你可以审这只老耗子。", "t": [16188, 19162]}, {"es": "Su vida dependería de tu justicia y la indultarás en cada juicio para conservarla, ya que no hay más que una.", "zh": "这样，它的死活就由你的裁判决定了。", "t": [19162, 24637]}]}, {"id": "ch10p36", "audio": true, "sents": [{"es": "-A mí no me gusta condenar a muerte a nadie -dijo el principito-.", "zh": "但你每一次都要免除它的死罪，你要悠着点，因为就只有这一个犯人了。", "t": [100, 4488]}, {"es": "Creo que me voy a marchar.", "zh": "” “我可不喜欢判人死刑。", "t": [4488, 5800]}]}, {"id": "ch10p37", "audio": true, "sents": [{"es": "-No -dijo el rey.", "zh": "” “我可不喜欢判人死刑。", "t": [100, 1362]}]}, {"id": "ch10p38", "audio": true, "sents": [{"es": "Pero el principito, que habiendo terminado ya sus preparativos no quiso disgustar al viejo monarca, dijo:", "zh": "” “别走。", "t": [100, 5337]}]}, {"id": "ch10p39", "audio": true, "sents": [{"es": "-Si Vuestra Majestad deseara ser obedecido puntualmente, podría dar una orden razonable.", "zh": "小王子已经做好走的准备，但他不愿伤老国王的心，他对老国王说：“如果陛下您希望令出即行，您可以向我下达合理的命令。", "t": [100, 5925]}, {"es": "Podría ordenarme, por ejemplo, partir antes de un minuto.", "zh": "小王子已经做好走的准备，但他不愿伤老国王的心，他对老国王说：“如果陛下您希望令出即行，您可以向我下达合理的命令。", "t": [5925, 9788]}, {"es": "Me parece que las condiciones son favorables…", "zh": "例如说，可以命令我在一分钟之内离开。", "t": [9788, 12137]}]}, {"id": "ch10p40", "audio": true, "sents": [{"es": "Como el rey no respondiera nada, el principito vaciló primero y con un suspiro emprendió la marcha.", "zh": "我认为时机已经成熟……” 国王一言不发。", "t": [100, 6150]}, {"es": "-¡Te nombro mi embajador!", "zh": "小王子犹豫片刻，然后叹口气，抬腿走了。", "t": [6150, 8238]}, {"es": "-se apresuró a gritar el rey.", "zh": "国王急忙大叫：“我封你为大使。", "t": [8238, 10788]}, {"es": "Tenía un aspecto de gran autoridad.", "zh": "国王急忙大叫：“我封你为大使。", "t": [10788, 12738]}]}, {"id": "ch10p41", "audio": true, "sents": [{"es": "\"Las personas mayores son muy extrañas\", se decía el principito para sí mismo durante el viaje.", "zh": "小王子一面赶路，一面自言自语： “大人们真怪。", "t": [100, 5063]}]}]}, {"id": "ch11", "title_es": "Capítulo 11", "title_zh": "第 11 章", "paras": [{"id": "ch11p00", "audio": true, "sents": [{"es": "El segundo planeta estaba habitado por un vanidoso:", "zh": "第二颗星球住着一个爱慕虚荣的人。", "t": [100, 2787]}]}, {"id": "ch11p01", "audio": true, "sents": [{"es": "-¡Ah!", "zh": "“啊！", "t": [100, 1362]}, {"es": "¡Ah!", "zh": "啊！", "t": [1362, 2625]}, {"es": "¡Un admirador viene a visitarme!", "zh": "崇拜我的人访问我啦！", "t": [2625, 5388]}, {"es": "-Gritó el vanidoso al divisar a lo lejos al principito.", "zh": "”看见小王子，这位爱慕虚荣的人打老远就高声喊。", "t": [5388, 8100]}]}, {"id": "ch11p02", "audio": true, "sents": [{"es": "Para los vanidosos todos los demás hombres son admiradores.", "zh": "爱慕虚荣的人以为别人都崇拜他。", "t": [100, 4125]}, {"es": "-¡Buenos días!", "zh": "“您好。", "t": [4125, 5975]}, {"es": "-dijo el principito-.", "zh": "”小王子说。", "t": [5975, 8050]}, {"es": "¡Qué sombrero tan raro tiene!", "zh": "“您的帽子真怪。", "t": [8050, 9587]}]}, {"id": "ch11p03", "audio": true, "sents": [{"es": "-Es para saludar a los que me aclaman -respondió el vanidoso.", "zh": "” “这顶帽子是用来敬礼的，”爱慕虚荣的人说，“有人向我欢呼的时候，我就用它敬礼。", "t": [100, 3375]}]}, {"id": "ch11p04", "audio": true, "sents": [{"es": "Desgraciadamente nunca pasa nadie por aquí.", "zh": "” “这顶帽子是用来敬礼的，”爱慕虚荣的人说，“有人向我欢呼的时候，我就用它敬礼。", "t": [100, 3438]}, {"es": "-¿Ah, sí?", "zh": "可惜这儿没一个人来。", "t": [3438, 5050]}, {"es": "-preguntó sin comprender el principito.", "zh": "可惜这儿没一个人来。", "t": [5050, 7100]}]}, {"id": "ch11p05", "audio": true, "sents": [{"es": "-Golpea tus manos una contra otra -le aconsejó el vanidoso.", "zh": "”小王子听不懂他的话。", "t": [100, 3438]}]}, {"id": "ch11p06", "audio": true, "sents": [{"es": "El principito aplaudió y el vanidoso le saludó modestamente levantando el sombrero.", "zh": "小王子依言鼓掌。", "t": [100, 4225]}]}, {"id": "ch11p07", "audio": true, "sents": [{"es": "\"Esto parece más divertido que la visita al rey\", se dijo para sí el principito, que continuó aplaudiendo mientras el vanidoso volvía a saludarle quitándose el sombrero.", "zh": "”小王子暗自想。", "t": [100, 8787]}]}, {"id": "ch11p08", "audio": true, "sents": [{"es": "A los cinco minutos el principito se cansó con la monotonía de aquel juego.", "zh": "反复操练了五分钟之后，小王子厌倦了这个单调的游戏。", "t": [100, 4788]}, {"es": "-¿Qué hay que hacer para que el sombrero se caiga?", "zh": "“该怎样做才能让您放下帽子？", "t": [4788, 7938]}, {"es": "-preguntó el principito.", "zh": "爱慕虚荣的人听不见这句话。", "t": [7938, 9137]}]}, {"id": "ch11p09", "audio": true, "sents": [{"es": "Pero el vanidoso no le oyó.", "zh": "爱慕虚荣的人听不见这句话。", "t": [100, 2462]}, {"es": "Los vanidosos sólo oyen las alabanzas.", "zh": "爱慕虚荣的人只听得见赞扬声。", "t": [2462, 5712]}, {"es": "-¿Tú me admiras mucho, verdad?", "zh": "“你对我真的崇拜到了五体投地？", "t": [5712, 8175]}, {"es": "-preguntó el vanidoso al principito.", "zh": "”他问小王子。", "t": [8175, 11012]}, {"es": "-¿Qué significa admirar?", "zh": "“什么叫做‘崇拜’？", "t": [11012, 12250]}]}, {"id": "ch11p10", "audio": true, "sents": [{"es": "-Admirar significa reconocer que yo soy el hombre más bello, el mejor vestido, el más rico y el más ïnteligente del planeta.", "zh": "” “‘崇拜’就是承认我是星球上最帅、衣着最讲究、最富有、最聪明的人。", "t": [100, 7688]}, {"es": "-¡Si tú estás solo en tu planeta!", "zh": "” “在你的星球上只有你一个人啊！", "t": [7688, 10400]}, {"es": "-¡Hazme ese favor, admírame de todas maneras!", "zh": "” “你就让我享受被人崇拜的快乐吧，仍然崇拜我吧！", "t": [10400, 14050]}, {"es": "-¡Bueno!", "zh": "” “你就让我享受被人崇拜的快乐吧，仍然崇拜我吧！", "t": [14050, 15450]}, {"es": "Te admiro -dijo el principito encogiéndose de hombros-, pero ¿para qué te sirve?", "zh": "” “我崇拜你，”小王子耸耸肩，“这有什么值得你快乐的呢？", "t": [15450, 19362]}]}, {"id": "ch11p11", "audio": true, "sents": [{"es": "Y el principito se marchó.", "zh": "” 小王子走了。", "t": [100, 1475]}]}, {"id": "ch11p12", "audio": true, "sents": [{"es": "\"Decididamente, las personas mayores son muy extrañas\", se decía para sí el principito durante su viaje.", "zh": "“大人们确实怪得出奇。", "t": [100, 5650]}]}]}, {"id": "ch12", "title_es": "Capítulo 12", "title_zh": "第 12 章", "paras": [{"id": "ch12p00", "audio": true, "sents": [{"es": "El planeta siguiente estaba habitado por un bebedor.", "zh": "下一颗星球住着一个酒鬼。", "t": [100, 3612]}, {"es": "Fue una visita muy corta, pues hundió al principito en una gran melancolía.", "zh": "这次访问时间不长，但小王子极为不快。", "t": [3612, 7387]}]}, {"id": "ch12p01", "audio": true, "sents": [{"es": "-¿Qué haces ahí?", "zh": "“你在干什么？", "t": [100, 1838]}, {"es": "-preguntó al bebedor que estaba sentado en silencio ante un sinnúmero de botellas vacías y otras tantas botellas llenas.", "zh": "”小王子看见酒鬼在喝闷酒，面前摆着一大堆空瓶子和装满了酒的瓶子，就这样问他。", "t": [1838, 8775]}, {"es": "-¡Bebo!", "zh": "“我在喝酒呀。", "t": [8775, 10175]}, {"es": "-respondió el bebedor con tono lúgubre.", "zh": "”酒鬼闷闷不乐地回答。", "t": [10175, 13275]}, {"es": "-¿Por qué bebes?", "zh": "“你为什么喝酒呢？", "t": [13275, 15000]}, {"es": "-volvió a preguntar el principito.", "zh": "”小王子问他。", "t": [15000, 16663]}]}, {"id": "ch12p02", "audio": true, "sents": [{"es": "-Para olvidar.", "zh": "“为了忘记呗。", "t": [100, 1762]}, {"es": "-¿Para olvidar qué?", "zh": "“为了忘记呗。", "t": [1762, 3588]}, {"es": "-inquirió el principito ya compadecido.", "zh": "“为了忘记什么？", "t": [3588, 5638]}]}, {"id": "ch12p03", "audio": true, "sents": [{"es": "-Para olvidar que siento vergüenza -confesó el bebedor bajando la cabeza.", "zh": "”小王子有点可怜他，又问。", "t": [100, 4775]}, {"es": "-¿Vergüenza de qué?", "zh": "”酒鬼低着头，老老实实地承认。", "t": [4775, 6612]}, {"es": "-se informó el principito deseoso de ayudarle.", "zh": "”酒鬼低着头，老老实实地承认。", "t": [6612, 10112]}, {"es": "-¡Vergüenza de beber!", "zh": "“为了什么事羞愧呢？", "t": [10112, 12088]}, {"es": "-concluyó el bebedor, que se encerró nueva y definitivamente en el silencio.", "zh": "“我为喝酒羞愧！", "t": [12088, 15750]}]}, {"id": "ch12p04", "audio": true, "sents": [{"es": "Y el principito, perplejo, se marchó.", "zh": "”酒鬼讲完后，闭了嘴巴不再讲话。", "t": [100, 2076]}]}, {"id": "ch12p05", "audio": true, "sents": [{"es": "\"No hay la menor duda de que las personas mayores son muy extrañas\", seguía diciéndose para sí el principito durante su viaje.", "zh": "“大人们真是没法理解。", "t": [100, 6400]}]}]}, {"id": "ch13", "title_es": "Capítulo 13", "title_zh": "第 13 章", "paras": [{"id": "ch13p00", "audio": true, "sents": [{"es": "El cuarto planeta estaba ocupado por un hombre de negocios.", "zh": "第四颗星球是商人的星球。", "t": [100, 4062]}, {"es": "Este hombre estaba tan abstraído que ni siquiera levantó la cabeza a la llegada del principito.", "zh": "“您好！", "t": [4062, 8538]}]}, {"id": "ch13p01", "audio": true, "sents": [{"es": "-¡Buenos días!", "zh": "“您的香烟已经熄灭了。", "t": [100, 1950]}, {"es": "-le dijo éste-.", "zh": "“您的香烟已经熄灭了。", "t": [1950, 3788]}, {"es": "Su cigarro se ha apagado.Tres y dos cinco.", "zh": "” “三加二等于五，五加七等于十二，十二加三等于十五，你好。", "t": [3788, 7475]}, {"es": "Cinco y siete doce.", "zh": "” “三加二等于五，五加七等于十二，十二加三等于十五，你好。", "t": [7475, 9750]}, {"es": "Doce y tres quince.", "zh": "十五加七等于二十二，二十二加六等于二十八，我没时间点烟。", "t": [9750, 11962]}, {"es": "¡Buenos días!", "zh": "十五加七等于二十二，二十二加六等于二十八，我没时间点烟。", "t": [11962, 13812]}, {"es": "Quince y siete veintidós.", "zh": "十五加七等于二十二，二十二加六等于二十八，我没时间点烟。", "t": [13812, 16300]}, {"es": "Veintidós y seis veintiocho.", "zh": "十五加七等于二十二，二十二加六等于二十八，我没时间点烟。", "t": [16300, 18950]}, {"es": "No tengo tiempo de encenderlo.", "zh": "二十六加五等于三十一。", "t": [18950, 21638]}, {"es": "Veintiocho y tres treinta y uno.", "zh": "嗬！", "t": [21638, 24375]}, {"es": "¡Uf!", "zh": "一共是五亿零一百六十二万二千七百三十一。", "t": [24375, 25738]}, {"es": "Esto suma quinientos un millones seiscientos veintidós mil setecientos treinta y uno.", "zh": "” “五亿个什么？", "t": [25738, 31062]}, {"es": "-¿Quinientos millones de qué?", "zh": "你还在这儿？", "t": [31062, 33338]}, {"es": "-¿Eh?", "zh": "五亿零一百……我也闹糊涂了……我的活太忙了！", "t": [33338, 34512]}, {"es": "¿Estás ahí todavía?", "zh": "五亿零一百……我也闹糊涂了……我的活太忙了！", "t": [34512, 36588]}, {"es": "Quinientos millones de…", "zh": "我是个正经人，不爱讲废话！", "t": [36588, 37875]}, {"es": "ya no sé…", "zh": "我是个正经人，不爱讲废话！", "t": [37875, 39438]}, {"es": "¡He trabajado tanto!", "zh": "我是个正经人，不爱讲废话！", "t": [39438, 41488]}, {"es": "¡Yo soy un hombre serio y no me entretengo en tonterías!", "zh": "二加五等于七……” “五亿零一百万个什么？", "t": [41488, 45375]}, {"es": "Dos y cinco siete…", "zh": "二加五等于七……” “五亿零一百万个什么？", "t": [45375, 47612]}, {"es": "¿Quinientos millones de qué?", "zh": "”小王子还在追问，他一旦提出问题，绝不中途而废。", "t": [47612, 49888]}, {"es": "-volvió a preguntar el principito, que nunca en su vida había renunciado a una pregunta una vez que la había formulado.", "zh": "商人抬起头： “我住在这个星球已经五十四年了，只受过三次干扰。", "t": [49888, 55438]}]}, {"id": "ch13p02", "audio": true, "sents": [{"es": "El hombre de negocios levantó la cabeza:", "zh": "商人抬起头： “我住在这个星球已经五十四年了，只受过三次干扰。", "t": [100, 2162]}]}, {"id": "ch13p03", "audio": true, "sents": [{"es": "-Desde hace cincuenta y cuatro años que habito este planeta, sólo me han molestado tres veces.", "zh": "第一次干扰发生在二十二年前，鬼知道从哪儿掉下一个愣头青，发出的声音大得吓人，弄得我的加法出了四个错；第二次干扰发生在十一年前，我患了关节炎，我缺乏体育锻炼，我没时间闲逛，我是个正经人；第三次……就是这一次！", "t": [100, 5888]}, {"es": "La primera, hace veintidós años, fue por un abejorro que había caído aquí de Dios sabe dónde.", "zh": "第一次干扰发生在二十二年前，鬼知道从哪儿掉下一个愣头青，发出的声音大得吓人，弄得我的加法出了四个错；第二次干扰发生在十一年前，我患了关节炎，我缺乏体育锻炼，我没时间闲逛，我是个正经人；第三次……就是这一次！", "t": [5888, 11738]}, {"es": "Hacía un ruido insoportable y me hizo cometer cuatro errores en una suma.", "zh": "我刚好算到五亿零一百万个……” “五亿零一百万个什么？", "t": [11738, 16512]}, {"es": "La segunda vez por una crisis de reumatismo, hace once años.", "zh": "我刚好算到五亿零一百万个……” “五亿零一百万个什么？", "t": [16512, 20038]}]}, {"id": "ch13p04", "audio": true, "sents": [{"es": "Yo no hago ningún ejercicio, pues no tengo tiempo de callejear.", "zh": "” 商人知道他休想安宁了： “五亿零一百万个小东西，有时在天上看得到的小东西。", "t": [100, 4362]}, {"es": "Soy un hombre serio.", "zh": "” 商人知道他休想安宁了： “五亿零一百万个小东西，有时在天上看得到的小东西。", "t": [4362, 6512]}, {"es": "Y la tercera vez…", "zh": "” 商人知道他休想安宁了： “五亿零一百万个小东西，有时在天上看得到的小东西。", "t": [6512, 7662]}, {"es": "¡la tercera vez es ésta!", "zh": "” “苍蝇吗？", "t": [7662, 9938]}, {"es": "Decía, pues, quinientos un millones…", "zh": "” “苍蝇吗？", "t": [9938, 12212]}, {"es": "-¿Millones de qué?", "zh": "” “不是，是闪闪发亮的小东西。", "t": [12212, 13000]}]}, {"id": "ch13p05", "audio": true, "sents": [{"es": "El hombre de negocios comprendió que no tenía ninguna esperanza de que lo dejaran en paz.", "zh": "” “蜜蜂吗？", "t": [100, 4300]}]}, {"id": "ch13p06", "audio": true, "sents": [{"es": "-Millones de esas pequeñas cosas que algunas veces se ven en el cielo.", "zh": "” “不是，是金色的小东西，能教闲得发慌的人发痴做梦的小东西，可我是正经人，我没时间遐想做梦。", "t": [100, 4625]}, {"es": "-¿Moscas?", "zh": "” “啊！", "t": [4625, 6212]}, {"es": "-¡No, cositas que brillan!", "zh": "” “啊！", "t": [6212, 8500]}, {"es": "-¿Abejas?", "zh": "是满天的繁星吗？", "t": [8500, 9000]}]}, {"id": "ch13p07", "audio": true, "sents": [{"es": "-No.", "zh": "是满天的繁星吗？", "t": [100, 1450]}, {"es": "Unas cositas doradas que hacen desvariar a los holgazanes.", "zh": "满天的星星。", "t": [1450, 5550]}, {"es": "¡Yo soy un hombre serio y no tengo tiempo de desvariar!", "zh": "” “你要五亿多颗星星做什么？", "t": [5550, 9288]}, {"es": "-¡Ah!", "zh": "” “是五亿零一百六十二万二千七百三十一颗。", "t": [9288, 10550]}, {"es": "¿Estrellas?", "zh": "” “是五亿零一百六十二万二千七百三十一颗。", "t": [10550, 11212]}]}, {"id": "ch13p08", "audio": true, "sents": [{"es": "-Eso es.", "zh": "” “是五亿零一百六十二万二千七百三十一颗。", "t": [100, 1662]}, {"es": "Estrellas.", "zh": "” “是五亿零一百六十二万二千七百三十一颗。", "t": [1662, 3400]}, {"es": "-¿Y qué haces tú con quinientos millones de estrellas?", "zh": "我是个一丝不苟的人，我务求精确。", "t": [3400, 5875]}]}, {"id": "ch13p09", "audio": true, "sents": [{"es": "-Quinientos un millones seiscientos veintidós mil setecientos treinta y uno.", "zh": "” “我要它们干什么？", "t": [100, 5075]}, {"es": "Yo soy un hombre serio y exacto.", "zh": "” “没什么用。", "t": [5075, 7938]}, {"es": "-¿Y qué haces con esas estrellas?", "zh": "” “你拥有星星？", "t": [7938, 10675]}, {"es": "-¿Que qué hago con ellas?", "zh": "” “是呀。", "t": [10675, 11800]}]}, {"id": "ch13p10", "audio": true, "sents": [{"es": "-Sí.", "zh": "” “是呀。", "t": [100, 338]}]}, {"id": "ch13p11", "audio": true, "sents": [{"es": "-Nada.", "zh": "” “是呀。", "t": [100, 1525]}, {"es": "Las poseo.", "zh": "” “我见过一个国王，他……” “国王不是‘拥有’，他是‘统治’。", "t": [1525, 3275]}, {"es": "-¿Que las estrellas son tuyas?", "zh": "” “我见过一个国王，他……” “国王不是‘拥有’，他是‘统治’。", "t": [3275, 4838]}]}, {"id": "ch13p12", "audio": true, "sents": [{"es": "-Sí.", "zh": "” “我见过一个国王，他……” “国王不是‘拥有’，他是‘统治’。", "t": [100, 338]}]}, {"id": "ch13p13", "audio": true, "sents": [{"es": "-Yo he visto un rey que…", "zh": "” “我见过一个国王，他……” “国王不是‘拥有’，他是‘统治’。", "t": [100, 1450]}]}, {"id": "ch13p14", "audio": true, "sents": [{"es": "-Los reyes no poseen nada…", "zh": "大不相同。", "t": [100, 2688]}, {"es": "Reinan.", "zh": "大不相同。", "t": [2688, 4238]}, {"es": "Es muy diferente.", "zh": "” “你拥有星星又怎么样呢？", "t": [4238, 6200]}, {"es": "-¿Y de qué te sirve poseer las estrellas?", "zh": "” “拥有了星星，我就成了大富翁呗。", "t": [6200, 8338]}]}, {"id": "ch13p15", "audio": true, "sents": [{"es": "-Me sirve para ser rico.", "zh": "” “拥有了星星，我就成了大富翁呗。", "t": [100, 2488]}, {"es": "-¿Y de qué te sirve ser rico?", "zh": "” “成了富翁有什么好处？", "t": [2488, 3937]}]}, {"id": "ch13p16", "audio": true, "sents": [{"es": "-Me sirve para comprar más estrellas si alguien las descubre.", "zh": "” “如果又有人发现了新的星星，我就把它们买下来呀。", "t": [100, 3137]}]}, {"id": "ch13p17", "audio": true, "sents": [{"es": "\"Este, se dijo a sí mismo el principito, razona poco más o menos como mi borracho\".", "zh": "” 小王子心想：“这个人的推理方法有点像我见过的那个酒鬼。", "t": [100, 4400]}]}, {"id": "ch13p18", "audio": true, "sents": [{"es": "No obstante le siguió preguntando: -¿Y cómo es posible poseer estrellas?", "zh": "” 他仍然提出问题： “怎样才能拥有星星？", "t": [100, 5062]}, {"es": "-¿De quién son las estrellas?", "zh": "” 他仍然提出问题： “怎样才能拥有星星？", "t": [5062, 7600]}, {"es": "-contestó punzante el hombre de negocios.", "zh": "” 商人烦了，没好气地反问： “你说，这满天的星星属于谁？", "t": [7600, 9688]}]}, {"id": "ch13p19", "audio": true, "sents": [{"es": "-No sé…", "zh": "” 商人烦了，没好气地反问： “你说，这满天的星星属于谁？", "t": [100, 1650]}, {"es": "De nadie.", "zh": "” “我不知道。", "t": [1650, 2237]}]}, {"id": "ch13p20", "audio": true, "sents": [{"es": "-Entonces son mías, puesto que he sido el primero a quien se le ha ocurrido la idea.", "zh": "它们不属于任何人。", "t": [100, 5075]}, {"es": "-¿Y eso basta?", "zh": "” “那么它们属于我。", "t": [5075, 5862]}]}, {"id": "ch13p21", "audio": true, "sents": [{"es": "-Naturalmente.", "zh": "因为我是第一个想到要拥有它们的人。", "t": [100, 2012]}, {"es": "Si te encuentras un diamante que nadie reclama, el diamante es tuyo.", "zh": "” “光是想就行了吗？", "t": [2012, 6638]}, {"es": "Si encontraras una isla que a nadie pertenece, la isla es tuya.", "zh": "你发现一颗没有主人的钻石，这颗钻石就归你了。", "t": [6638, 11200]}, {"es": "Si eres el primero en tener una idea y la haces patentar, nadie puede aprovecharla: es tuya.", "zh": "你发现一个不属于任何人的岛，这岛就是你的了。", "t": [11200, 17250]}, {"es": "Las estrellas son mías, puesto que nadie, antes que yo, ha pensado en poseerlas.", "zh": "你头一个想出一个主意，你就可以申请专利，这个主意就是你的了。", "t": [17250, 21450]}]}, {"id": "ch13p22", "audio": true, "sents": [{"es": "-Eso es verdad -dijo el principito- ¿y qué haces con ellas?", "zh": "而我呢，我拥有星星，因为在我之前没有一个人想过要拥有星星。", "t": [100, 3263]}]}, {"id": "ch13p23", "audio": true, "sents": [{"es": "-Las administro.", "zh": "” “这倒是真的。", "t": [100, 2012]}, {"es": "Las cuento y las recuento una y otra vez -contestó el hombre de negocios-.", "zh": "”小王子想。", "t": [2012, 6775]}, {"es": "Es algo difícil.", "zh": "” “我管理它们。", "t": [6775, 8688]}, {"es": "¡Pero yo soy un hombre serio!", "zh": "” “我管理它们。", "t": [8688, 10188]}]}, {"id": "ch13p24", "audio": true, "sents": [{"es": "El principito no quedó del todo satisfecho.", "zh": "”商人说。", "t": [100, 2412]}]}, {"id": "ch13p25", "audio": true, "sents": [{"es": "-Si yo tengo una bufanda, puedo ponérmela al cuello y llevármela.", "zh": "“这是件困难的事，但我是个正经人！", "t": [100, 4612]}, {"es": "Si soy dueño de una flor, puedo cortarla y llevármela también.", "zh": "” 小王子对这个回答还不满意： “我若拥有一条围巾，我可以把它围在脖子上带走；我若拥有一朵花，我可以把它摘下带走；可你摘不下星星呀！", "t": [4612, 9088]}, {"es": "¡Pero tú no puedes llevarte las estrellas!", "zh": "” 小王子对这个回答还不满意： “我若拥有一条围巾，我可以把它围在脖子上带走；我若拥有一朵花，我可以把它摘下带走；可你摘不下星星呀！", "t": [9088, 11113]}]}, {"id": "ch13p26", "audio": true, "sents": [{"es": "-Pero puedo colocarlas en un banco.", "zh": "” 小王子对这个回答还不满意： “我若拥有一条围巾，我可以把它围在脖子上带走；我若拥有一朵花，我可以把它摘下带走；可你摘不下星星呀！", "t": [100, 2825]}, {"es": "-¿Qué quiere decir eso?", "zh": "” “我不能摘星星，但我能把它们存入银行。", "t": [2825, 3938]}]}, {"id": "ch13p27", "audio": true, "sents": [{"es": "-Quiere decir que escribo en un papel el número de estrellas que tengo y guardo bajo llave en un cajón ese papel.", "zh": "” “我不能摘星星，但我能把它们存入银行。", "t": [100, 6338]}, {"es": "-¿Y eso es todo?", "zh": "” “我在一张小纸条上写上我的星星的数目，然后把它锁进抽屉里。", "t": [6338, 8162]}, {"es": "-¡Es suficiente!", "zh": "” “我在一张小纸条上写上我的星星的数目，然后把它锁进抽屉里。", "t": [8162, 9024]}]}, {"id": "ch13p28", "audio": true, "sents": [{"es": "\"Es divertido\", pensó el principito.", "zh": "” “我在一张小纸条上写上我的星星的数目，然后把它锁进抽屉里。", "t": [100, 3025]}, {"es": "\"Es incluso bastante poético.", "zh": "” “就这样？", "t": [3025, 5775]}, {"es": "Pero no es muy serio\".", "zh": "” “这就行啦！", "t": [5775, 6913]}]}, {"id": "ch13p29", "audio": true, "sents": [{"es": "El principito tenía sobre las cosas serias ideas muy diferentes de las ideas de las personas mayores.", "zh": "” 小王子想：“这倒是挺好玩的，还挺有诗意的呢，但算不上是严肃正经的事儿。", "t": [100, 5162]}]}, {"id": "ch13p30", "audio": true, "sents": [{"es": "-Yo -dijo aún- tengo una flor a la que riego todos los días; poseo tres volcanes a los que deshollino todas las semanas, pues también me ocupo del que está extinguido; nunca se sabe lo que puede ocurrir.", "zh": "” 对“严肃正经的事儿”，小王子的看法与大人的看法极不相同。", "t": [100, 12038]}, {"es": "Es útil, pues, para mis volcanes y para mi flor que yo las posea.", "zh": "我也疏通死火山，因为日后的事难说。", "t": [12038, 16500]}, {"es": "Pero tú, tú no eres nada útil para las estrellas…", "zh": "我能做对火山、对花有益的事，才叫做拥有它们。", "t": [16500, 19363]}]}, {"id": "ch13p31", "audio": true, "sents": [{"es": "El hombre de negocios abrió la boca, pero no encontró respuesta.", "zh": "但你却不给星星做有益的事。", "t": [100, 3575]}]}, {"id": "ch13p32", "audio": true, "sents": [{"es": "El principito abandonó aquel planeta.", "zh": "” 商人张口结舌，找不到话回答。", "t": [100, 2076]}]}, {"id": "ch13p33", "audio": true, "sents": [{"es": "\"Las personas mayores, decididamente, son extraordinarias\", se decía a sí mismo con sencillez durante el viaje.", "zh": "“大人们真是怪得没法说。", "t": [100, 6112]}]}]}, {"id": "ch14", "title_es": "Capítulo 14", "title_zh": "第 14 章", "paras": [{"id": "ch14p00", "audio": true, "sents": [{"es": "El quinto planeta era muy curioso.", "zh": "第五颗星球稀奇古怪，它是熠熠繁星中最小的一颗，它仅能容纳一盏路灯和一个点灯人。", "t": [100, 3075]}, {"es": "Era el más pequeño de todos, pues apenas cabían en él un farol y el farolero que lo habitaba.", "zh": "第五颗星球稀奇古怪，它是熠熠繁星中最小的一颗，它仅能容纳一盏路灯和一个点灯人。", "t": [3075, 8700]}, {"es": "El principito no lograba explicarse para qué servirían allí, en el cielo, en un planeta sin casas y sin población un farol y un farolero.", "zh": "小王子怎么想都想不明白，这颗位于太空中不起眼的星球，既没有房屋，又没有居民，这路灯和点灯人有何用途。", "t": [8700, 16800]}, {"es": "Sin embargo, se dijo a sí mismo:", "zh": "小王子怎么想都想不明白，这颗位于太空中不起眼的星球，既没有房屋，又没有居民，这路灯和点灯人有何用途。", "t": [16800, 18525]}]}, {"id": "ch14p01", "audio": true, "sents": [{"es": "\"Este hombre, quizás, es absurdo.", "zh": "他想：“这个点灯人也许古怪，然而他不会比国王、爱慕虚荣的人、商人、酒鬼更荒谬吧，至少他干的工作还有意义。", "t": [100, 3025]}, {"es": "Sin embargo, es menos absurdo que el rey, el vanidoso, el hombre de negocios y el bebedor.", "zh": "他想：“这个点灯人也许古怪，然而他不会比国王、爱慕虚荣的人、商人、酒鬼更荒谬吧，至少他干的工作还有意义。", "t": [3025, 8700]}, {"es": "Su trabajo, al menos, tiene sentido.", "zh": "他想：“这个点灯人也许古怪，然而他不会比国王、爱慕虚荣的人、商人、酒鬼更荒谬吧，至少他干的工作还有意义。", "t": [8700, 11700]}, {"es": "Cuando enciende su farol, es igual que si hiciera nacer una estrella más o una flor y cuando lo apaga hace dormir a la flor o a la estrella.", "zh": "他点亮路灯，如同给太空增添一颗星星，或一朵鲜花；他熄灭路灯，就是让花儿和星星休息睡眠。", "t": [11700, 19538]}, {"es": "Es una ocupación muy bonita y por ser bonita es verdaderamente útil\".", "zh": "这活儿充满诗意，既然充满诗意，那就是有益的工作。", "t": [19538, 23224]}]}, {"id": "ch14p02", "audio": true, "sents": [{"es": "Cuando llegó al planeta saludó respetuosamente al farolero: -¡Buenos días!", "zh": "” 他走近星球，毕恭毕敬地向点灯人行礼： “你好。", "t": [100, 4962]}, {"es": "¿Por qué acabas de apagar tu farol?", "zh": "你刚才为什么把灯灭了？", "t": [4962, 6738]}]}, {"id": "ch14p03", "audio": true, "sents": [{"es": "-Es la consigna -respondió el farolero-.", "zh": "” “这是规定。", "t": [100, 3450]}, {"es": "¡Buenos días!", "zh": "“早上好。", "t": [3450, 5300]}, {"es": "-¿Y qué es la consigna?", "zh": "” “什么规定？", "t": [5300, 6462]}]}, {"id": "ch14p04", "audio": true, "sents": [{"es": "-Apagar mi farol.", "zh": "” “什么规定？", "t": [100, 2012]}, {"es": "¡Buenas noches!", "zh": "” “熄灯的规定。", "t": [2012, 3962]}, {"es": "Y encendió el farol.", "zh": "晚上好。", "t": [3962, 6075]}, {"es": "-¿Y por qué acabas de volver a encenderlo?", "zh": "” 他点上灯。", "t": [6075, 8000]}]}, {"id": "ch14p05", "audio": true, "sents": [{"es": "-Es la consigna.", "zh": "“你怎么又把灯点着了？", "t": [100, 1012]}]}, {"id": "ch14p06", "audio": true, "sents": [{"es": "-No lo comprendo -dijo el principito.", "zh": "” “这是规定。", "t": [100, 2050]}]}, {"id": "ch14p07", "audio": true, "sents": [{"es": "-No hay nada que comprender -dijo el farolero-.", "zh": "”小王子说。", "t": [100, 3388]}, {"es": "La consigna es la consigna.", "zh": "“用不着明白，”点灯人说，“规定就是规定。", "t": [3388, 5938]}, {"es": "¡Buenos días!", "zh": "“用不着明白，”点灯人说，“规定就是规定。", "t": [5938, 6762]}]}, {"id": "ch14p08", "audio": true, "sents": [{"es": "Y apagó su farol.", "zh": "早上好。", "t": [100, 1163]}]}, {"id": "ch14p09", "audio": true, "sents": [{"es": "Luego se enjugó la frente con un pañuelo de cuadros rojos.", "zh": "” 他灭掉路灯。", "t": [100, 3263]}]}, {"id": "ch14p10", "audio": true, "sents": [{"es": "-Mi trabajo es algo terrible.", "zh": "然后他用红方格手帕抹抹额头。", "t": [100, 2662]}, {"es": "En otros tiempos era razonable; apagaba el farol por la mañana y lo encendía por la tarde.", "zh": "从前的规定还合乎情理，早上熄灯，晚上点灯。", "t": [2662, 8550]}, {"es": "Tenía el resto del día para reposar y el resto de la noche para dormir.", "zh": "熄灯之后休息，点灯之后睡觉……” “现在的规定改了？", "t": [8550, 13138]}, {"es": "-¿Y luego cambiaron la consigna?", "zh": "熄灯之后休息，点灯之后睡觉……” “现在的规定改了？", "t": [13138, 14750]}]}, {"id": "ch14p11", "audio": true, "sents": [{"es": "-Ese es el drama, que la consigna no ha cambiado -dijo el farolero-.", "zh": "” “规定倒没有改，”点灯人说，“倒霉就倒霉在这儿！", "t": [100, 4925]}, {"es": "El planeta gira cada vez más de prisa de año en año y la consigna sigue siendo la misma.", "zh": "行星一年转得比一年快，而规定却没有改变！", "t": [4925, 10412]}, {"es": "-¿Y entonces?", "zh": "” “这是怎么回事？", "t": [10412, 12162]}, {"es": "-dijo el principito.", "zh": "” “现在它一分钟转一次，我连一秒钟的休息时间都没有。", "t": [12162, 13250]}]}, {"id": "ch14p12", "audio": true, "sents": [{"es": "-Como el planeta da ahora una vuelta completa cada minuto, yo no tengo un segundo de reposo.", "zh": "” “现在它一分钟转一次，我连一秒钟的休息时间都没有。", "t": [100, 5762]}, {"es": "Enciendo y apago una vez por minuto.", "zh": "” “这怎么可能呢？", "t": [5762, 8825]}, {"es": "-¡Eso es raro!", "zh": "” “这怎么可能呢？", "t": [8825, 10650]}, {"es": "¡Los días sólo duran en tu tierra un minuto!", "zh": "你这儿一分钟就是一天？", "t": [10650, 12976]}]}, {"id": "ch14p13", "audio": true, "sents": [{"es": "-Esto no tiene nada de divertido -dijo el farolero-.", "zh": "” “怎么不可能，”点灯人说，“我们已经聊了一个月了。", "t": [100, 3925]}, {"es": "Hace ya un mes que tú y yo estamos hablando.", "zh": "” “一个月？", "t": [3925, 7150]}, {"es": "-¿Un mes?", "zh": "” “一个月？", "t": [7150, 7638]}]}, {"id": "ch14p14", "audio": true, "sents": [{"es": "-Sí, treinta minutos.", "zh": "” “是的，三十分钟，就是三十天！", "t": [100, 2425]}, {"es": "¡Treinta días!", "zh": "” “是的，三十分钟，就是三十天！", "t": [2425, 4250]}, {"es": "¡Buenas noches!", "zh": "晚上好。", "t": [4250, 5200]}]}, {"id": "ch14p15", "audio": true, "sents": [{"es": "Y volvió a encender su farol.", "zh": "” 点灯人又点亮了路灯。", "t": [100, 1663]}]}, {"id": "ch14p16", "audio": true, "sents": [{"es": "El principito lo miró y le gustó este farolero que tan fielmente cumplía la consigna.", "zh": "小王子看着他，小王子喜欢这个一丝不苟，按章办事的点灯人。", "t": [100, 5225]}, {"es": "Recordó las puestas de sol que en otro tiempo iba a buscar arrastrando su silla.", "zh": "他记起自己以前必须挪动椅子才能看到日落的情景。", "t": [5225, 10300]}, {"es": "Quiso ayudarle a su amigo.", "zh": "他很愿意帮助他的朋友。", "t": [10300, 12825]}, {"es": "-¿Sabes?", "zh": "他很愿意帮助他的朋友。", "t": [12825, 14375]}, {"es": "Yo conozco un medio para que descanses cuando quieras…", "zh": "他很愿意帮助他的朋友。", "t": [14375, 17150]}]}, {"id": "ch14p17", "audio": true, "sents": [{"es": "-Yo quiero descansar siempre -dijo el farolero.", "zh": "“你知道吗……我有个办法，你什么时候想休息就可以休息……” “我一直想找个办法呢。", "t": [100, 2663]}]}, {"id": "ch14p18", "audio": true, "sents": [{"es": "Se puede ser a la vez fiel y perezoso.", "zh": "”点灯人说。", "t": [100, 2162]}]}, {"id": "ch14p19", "audio": true, "sents": [{"es": "El principito prosiguió:", "zh": "”点灯人说。", "t": [100, 1388]}]}, {"id": "ch14p20", "audio": true, "sents": [{"es": "-Tu planeta es tan pequeño que puedes darle la vuelta en tres zancadas.", "zh": "有个办法既能按章办事又能偷懒就好了。", "t": [100, 4475]}, {"es": "No tienes que hacer más que caminar muy lentamente para quedar siempre al sol.", "zh": "小王子继续说道： “你的星球这么小，走三步就绕了一个圈。", "t": [4475, 9238]}, {"es": "Cuando quieras descansar, caminarás…", "zh": "你只要放慢脚步，太阳就老在你的头顶上。", "t": [9238, 11400]}, {"es": "y el día durará tanto tiempo cuanto quieras.", "zh": "你想休息的时候，你就往前走……你的白天要多长有多长。", "t": [11400, 13562]}]}, {"id": "ch14p21", "audio": true, "sents": [{"es": "-Con eso no adelanto gran cosa -dijo el farolero-, lo que a mí me gusta en la vida es dormir.", "zh": "你想休息的时候，你就往前走……你的白天要多长有多长。", "t": [100, 5062]}]}, {"id": "ch14p22", "audio": true, "sents": [{"es": "-No es una suerte -dijo el principito.", "zh": "” “这个办法解决不了我多大的问题，”点灯人说，“我平生喜欢的就是睡觉。", "t": [100, 2137]}]}, {"id": "ch14p23", "audio": true, "sents": [{"es": "-No, no es una suerte -replicó el farolero-.", "zh": "” “那你就太不走运了。", "t": [100, 3475]}, {"es": "¡Buenos días!", "zh": "” “那你就太不走运了。", "t": [3475, 4300]}]}, {"id": "ch14p24", "audio": true, "sents": [{"es": "Y apagó su farol.", "zh": "” “那你就太不走运了。", "t": [100, 1163]}]}, {"id": "ch14p25", "audio": true, "sents": [{"es": "Mientras el principito proseguía su viaje, se iba diciendo para sí: \"Este sería despreciado por los otros, por el rey, por el vanidoso, por el bebedor, por el hombre de negocios.", "zh": "”他又灭了路灯。", "t": [100, 10500]}, {"es": "Y, sin embargo, es el único que no me parece ridículo, quizás porque se ocupa de otra cosa y no de sí mismo.", "zh": "会被国王、爱慕虚荣的人、酒鬼、商人瞧不起。", "t": [10500, 17075]}, {"es": "Lanzó un suspiro de pena y continuó diciéndose:", "zh": "可是他是惟一的我不觉得可笑的人，也许因为他没有光顾自己吧！", "t": [17075, 19825]}]}, {"id": "ch14p26", "audio": true, "sents": [{"es": "\"Es el único de quien pude haberme hecho amigo.", "zh": "可是他是惟一的我不觉得可笑的人，也许因为他没有光顾自己吧！", "t": [100, 3350]}, {"es": "Pero su planeta es demasiado pequeño y no hay lugar para dos…", "zh": "” 他惋惜地叹口气，又想： “这个人本来是惟一可做我的朋友的人，但他的星球实在太小了，搁不下两个人……” 小王子不敢承认，他对这颗星球颇有好感的原因是，它得天独厚，二十四小时之内就可以观看一千四百四十次日落。", "t": [3350, 6587]}, {"es": "\"", "zh": "” 他惋惜地叹口气，又想： “这个人本来是惟一可做我的朋友的人，但他的星球实在太小了，搁不下两个人……” 小王子不敢承认，他对这颗星球颇有好感的原因是，它得天独厚，二十四小时之内就可以观看一千四百四十次日落。", "t": [6587, 7087]}]}, {"id": "ch14p27", "audio": true, "sents": [{"es": "Lo que el principito no se atrevía a confesarse, era que la causa por la cual lamentaba no quedarse en este bendito planeta se debía a las mil cuatrocientas cuarenta puestas de sol que podría disfrutar cada veinticuatro horas.", "zh": "” 他惋惜地叹口气，又想： “这个人本来是惟一可做我的朋友的人，但他的星球实在太小了，搁不下两个人……” 小王子不敢承认，他对这颗星球颇有好感的原因是，它得天独厚，二十四小时之内就可以观看一千四百四十次日落。", "t": [100, 11263]}]}]}, {"id": "ch15", "title_es": "Capítulo 15", "title_zh": "第 15 章", "paras": [{"id": "ch15p00", "audio": true, "sents": [{"es": "El sexto planeta era diez veces más grande.", "zh": "第六颗星球比刚才那颗大十倍。", "t": [100, 3588]}, {"es": "Estaba habitado por un anciano que escribía grandes libros.", "zh": "星球上住着一位老先生，正在撰写大部头著作。", "t": [3588, 7625]}, {"es": "-¡Anda, un explorador!", "zh": "看见小王子，他大声嚷： “嗬！", "t": [7625, 10012]}, {"es": "-exclamó cuando divisó al principito.", "zh": "来了一个勘探人员！", "t": [10012, 12038]}]}, {"id": "ch15p01", "audio": true, "sents": [{"es": "Este se sentó sobre la mesa y reposó un poco.", "zh": "” 小王子有点气喘，坐在桌子上。", "t": [100, 3575]}, {"es": "¡Había viajado ya tanto!", "zh": "他赶了大老远的路呢！", "t": [3575, 5938]}, {"es": "-¿De dónde vienes tú?", "zh": "他赶了大老远的路呢！", "t": [5938, 8062]}, {"es": "-le preguntó el anciano.", "zh": "“你从哪儿来？", "t": [8062, 10288]}, {"es": "-¿Qué libro es ese tan grande?", "zh": "”老先生问他。", "t": [10288, 12700]}, {"es": "-preguntó a su vez el principito-.", "zh": "”小王子问。", "t": [12700, 15400]}, {"es": "¿Qué hace usted aquí?", "zh": "“您在这儿干什么？", "t": [15400, 16375]}]}, {"id": "ch15p02", "audio": true, "sents": [{"es": "-Soy geógrafo -dijo el anciano.", "zh": "” “我是地理学家。", "t": [100, 2912]}, {"es": "-¿Y qué es un geógrafo?", "zh": "”老先生说。", "t": [2912, 4137]}]}, {"id": "ch15p03", "audio": true, "sents": [{"es": "-Es un sabio que sabe donde están los mares, los ríos, las ciudades, las montañas y los desiertos.", "zh": "” “地理学家是学者，知道哪儿有大海、江河、城市、山脉、沙漠。", "t": [100, 5513]}]}, {"id": "ch15p04", "audio": true, "sents": [{"es": "-Eso es muy interesante -dijo el principito-.", "zh": "” “这倒挺有趣的。", "t": [100, 3525]}, {"es": "¡Y es un verdadero oficio!", "zh": "”小王子说。", "t": [3525, 5000]}]}, {"id": "ch15p05", "audio": true, "sents": [{"es": "Dirigió una mirada a su alrededor sobre el planeta del geógrafo; nunca había visto un planeta tan majestuoso.", "zh": "”他环顾地理学家的行星。", "t": [100, 6000]}]}, {"id": "ch15p06", "audio": true, "sents": [{"es": "-Es muy hermoso su planeta.", "zh": "这儿有大洋吗？", "t": [100, 2588]}, {"es": "¿Hay océanos aquí?", "zh": "” “我不可能知道这事。", "t": [2588, 3612]}]}, {"id": "ch15p07", "audio": true, "sents": [{"es": "-No puedo saberlo -dijo el geógrafo.", "zh": "”地理学家说。", "t": [100, 3288]}, {"es": "-¡Ah!", "zh": "”地理学家说。", "t": [3288, 3462]}, {"es": "(El principito se sintió decepcionado).", "zh": "“啊（小王子有点失望）！", "t": [3462, 6400]}, {"es": "¿Y montañas?", "zh": "有山脉吗？", "t": [6400, 7137]}]}, {"id": "ch15p08", "audio": true, "sents": [{"es": "-No puedo saberlo -repitió el geógrafo.", "zh": "” “我不可能知道。", "t": [100, 3462]}, {"es": "-¿Y ciudades, ríos y desiertos?", "zh": "“有城市、河流、沙漠吗？", "t": [3462, 5362]}]}, {"id": "ch15p09", "audio": true, "sents": [{"es": "-Tampoco puedo saberlo.", "zh": "“有城市、河流、沙漠吗？", "t": [100, 2338]}, {"es": "-¡Pero usted es geógrafo!", "zh": "” “我也不可能知道。", "t": [2338, 3676]}]}, {"id": "ch15p10", "audio": true, "sents": [{"es": "-Exactamente -dijo el geógrafo-, pero no soy explorador, ni tengo exploradores que me informen.", "zh": "“可你是地理学家啊！", "t": [100, 6075]}, {"es": "El geógrafo no puede estar de acá para allá contando las ciudades, los ríos, las montañas, los océanos y los desiertos; es demasiado importante para deambnlar por ahí.", "zh": "计算城市、江河、山脉、大海、大洋、沙漠的数目，不是地理学家干的事。", "t": [6075, 15800]}, {"es": "Se queda en su despacho y allí recibe a los exploradores.", "zh": "他必须寸步不离办公室。", "t": [15800, 19850]}, {"es": "Les interroga y toma nota de sus informes.", "zh": "他在办公室接见勘探人员，询问他们，记下他们的回忆。", "t": [19850, 23212]}, {"es": "Si los informes de alguno de ellos le parecen interesantes, manda hacer una investigación sobre la moralidad del explorador.", "zh": "勘探人员引起了地理学家的兴趣，地理学家就要调查这位勘探人员的品质。", "t": [23212, 30538]}, {"es": "-¿Para qué?", "zh": "” “为什么？", "t": [30538, 30950]}]}, {"id": "ch15p11", "audio": true, "sents": [{"es": "-Un explorador que mintiera sería una catástrofe para los libros de geografía.", "zh": "” “为什么？", "t": [100, 5138]}, {"es": "Y también lo sería un explorador que bebiera demasiado.", "zh": "” “为什么？", "t": [5138, 8975]}, {"es": "-¿Por qué?", "zh": "” “为什么？", "t": [8975, 10338]}, {"es": "-preguntó el principito.", "zh": "” “为什么？", "t": [10338, 11537]}]}, {"id": "ch15p12", "audio": true, "sents": [{"es": "-Porque los borrachos ven doble y el geógrafo pondría dos montañas donde sólo habría una.", "zh": "” “酒鬼看的东西是重叠的，地理学家就会在有一座山的地方记下两座山。", "t": [100, 4600]}]}, {"id": "ch15p13", "audio": true, "sents": [{"es": "-Conozco a alguien -dijo el principito-, que sería un mal explorador.", "zh": "” 小王子说：“我认识一个人，他会成为糟糕的勘探员。", "t": [100, 3512]}]}, {"id": "ch15p14", "audio": true, "sents": [{"es": "-Es posible.", "zh": "” “很可能。", "t": [100, 1838]}, {"es": "Cuando se está convencído de que la moralidad del explorador es buena, se hace una investigación sobre su descubrimiento.", "zh": "” “你亲自去实地调查吗？", "t": [1838, 7800]}, {"es": "-¿", "zh": "” “不，那太复杂了。", "t": [7800, 8775]}, {"es": "Se va a ver?", "zh": "我要求勘探人员提供证据。", "t": [8775, 9474]}]}, {"id": "ch15p15", "audio": true, "sents": [{"es": "-No, eso sería demasiado complicado.", "zh": "我要求勘探人员提供证据。", "t": [100, 3125]}, {"es": "Se exige al explorador que suministre pruebas.", "zh": "比如说，他发现了一座大山，我就要求他带大石来。", "t": [3125, 6738]}, {"es": "Por ejemplo, si se trata del descubrimiento de una gran montaña, se le pide que traiga grandes piedras.", "zh": "” 地理学家突然兴奋起来： “你呢，你是从远方来的！", "t": [6738, 11988]}]}, {"id": "ch15p16", "audio": true, "sents": [{"es": "Súbitamente el geógrafo se sintió emocionado:", "zh": "你给我描写你的星球吧！", "t": [100, 2626]}]}, {"id": "ch15p17", "audio": true, "sents": [{"es": "-Pero…", "zh": "” 地理学家打开他的登记册，削尖铅笔。", "t": [100, 450]}, {"es": "¡tú vienes de muy lejos!", "zh": "” 地理学家打开他的登记册，削尖铅笔。", "t": [450, 2688]}, {"es": "¡Tú eres un explorador!", "zh": "” 地理学家打开他的登记册，削尖铅笔。", "t": [2688, 4938]}, {"es": "Vas a describirme tu planeta.", "zh": "他先用铅笔记下勘探人员的口述。", "t": [4938, 6550]}]}, {"id": "ch15p18", "audio": true, "sents": [{"es": "Y el geógrafo abriendo su regístro afiló su lápiz.", "zh": "勘探人员提供证据后，再用钢笔誊写。", "t": [100, 3875]}, {"es": "Los relatos de los exploradores se escriben primero con lápiz.", "zh": "”地理学家说。", "t": [3875, 7063]}]}, {"id": "ch15p19", "audio": true, "sents": [{"es": "Se espera que el explorador presente sus pruebas para pasarlos a tinta.", "zh": "我们那儿，可没意思了，”小王子说，“它才一点大，我有三座火山：两座活火山，一座死火山，可谁知道以后会有什么变化呢。", "t": [100, 4825]}, {"es": "-¿Y bien?", "zh": "我们那儿，可没意思了，”小王子说，“它才一点大，我有三座火山：两座活火山，一座死火山，可谁知道以后会有什么变化呢。", "t": [4825, 6250]}, {"es": "-interrogó el geógrafo.", "zh": "我们那儿，可没意思了，”小王子说，“它才一点大，我有三座火山：两座活火山，一座死火山，可谁知道以后会有什么变化呢。", "t": [6250, 8575]}, {"es": "-¡Oh!", "zh": "我们那儿，可没意思了，”小王子说，“它才一点大，我有三座火山：两座活火山，一座死火山，可谁知道以后会有什么变化呢。", "t": [8575, 9788]}, {"es": "Mi tierra -dijo el principito- no es interesante, todo es muy pequeño.", "zh": "” “以后的事谁知道呢。", "t": [9788, 14638]}, {"es": "Tengo tres volcanes, dos en actividad y uno extinguido; pero nunca se sabe…", "zh": "“我还有一朵花。", "t": [14638, 18888]}]}, {"id": "ch15p20", "audio": true, "sents": [{"es": "-No, nunca se sabe -dijo el geógrafo.", "zh": "”地理学家说。", "t": [100, 2188]}]}, {"id": "ch15p21", "audio": true, "sents": [{"es": "-Tengo también una flor.", "zh": "“为什么不记录花呢？", "t": [100, 1312]}]}, {"id": "ch15p22", "audio": true, "sents": [{"es": "-De las flores no tomamos nota.", "zh": "它是最美的东西！", "t": [100, 2812]}, {"es": "-¿Por qué?", "zh": "” “因为它‘昙花一现’。", "t": [2812, 4175]}, {"es": "¡Son lo más bonito!", "zh": "” “因为它‘昙花一现’。", "t": [4175, 5250]}]}, {"id": "ch15p23", "audio": true, "sents": [{"es": "-Porque las flores son efímeras.", "zh": "” “什么叫做‘昙花一现’？", "t": [100, 2812]}, {"es": "-¿Qué significa \"efímera\"?", "zh": "” “什么叫做‘昙花一现’？", "t": [2812, 4100]}]}, {"id": "ch15p24", "audio": true, "sents": [{"es": "-Las geografías -dijo el geógrafo- son los libros más preciados e interesantes; nunca pasan de moda.", "zh": "” “地理书是一切书籍中最珍贵的书籍，从不会过时。", "t": [100, 6900]}, {"es": "Es muy raro que una montaña cambie de sitio o que un océano quede sin agua.", "zh": "我们写的是永恒不变的东西。", "t": [6900, 11825]}, {"es": "Los geógrafos escribimos sobre cosas eternas.", "zh": "”小王子打断他的话。", "t": [11825, 14425]}]}, {"id": "ch15p25", "audio": true, "sents": [{"es": "-Pero los volcanes extinguidos pueden despertarse -interrumpió el principito-.", "zh": "” “火山死与不死，在我们看来都是一回事。", "t": [100, 5012]}, {"es": "¿Qué significa \"efímera\"?", "zh": "”地理学家说。", "t": [5012, 6300]}]}, {"id": "ch15p26", "audio": true, "sents": [{"es": "-Que los volcanes estén o no en actividad es igual para nosotros.", "zh": "“我们重视的是山，山不会改变。", "t": [100, 4325]}, {"es": "Lo interesante es la montaña que nunca cambia.", "zh": "” “什么叫做‘昙花一现’？", "t": [4325, 6725]}]}, {"id": "ch15p27", "audio": true, "sents": [{"es": "-Pero, ¿qué significa \"efímera\"?", "zh": "”小王子继续追问。", "t": [100, 2700]}, {"es": "-repitió el principito que en su vida había renunciado a una pregunta una vez formulada.", "zh": "“‘昙花一现’的意思就是‘面临很快消失的危险’。", "t": [2700, 7074]}]}, {"id": "ch15p28", "audio": true, "sents": [{"es": "-Significa que está amenazado de próxima desaparición.", "zh": "” “我的花儿也有很快消失的危险吗？", "t": [100, 3975]}, {"es": "-¿Mi flor está amenazada de desaparecer próximamente?", "zh": "” “当然。", "t": [3975, 6975]}]}, {"id": "ch15p29", "audio": true, "sents": [{"es": "-Indudablemente.", "zh": "” “当然。", "t": [100, 1050]}]}, {"id": "ch15p30", "audio": true, "sents": [{"es": "\"Mi flor as efímera -se dijo el principito- y no tiene más que cuatro espinas para defenderse contra el mundo.", "zh": "” “我的花会‘昙花一现’，”小王子想，“而她只有四根刺保护自己，应付这个世界！", "t": [100, 6625]}, {"es": "¡Y la he dejado allá sola en mi casa!\" Por primera vez se arrepintió de haber dejado su planeta, pero bien pronto recobró su valor.", "zh": "” 他头一次体会到悔恨的感觉。", "t": [6625, 15125]}, {"es": "-¿Qué me aconseja usted que visite ahora?", "zh": "然而他还是鼓起勇气问： “您能否指点我，我该去哪儿访问？", "t": [15125, 18150]}, {"es": "-preguntó.", "zh": "” “到地球上去吧，”地理学家说，“它非常有名……” 小王子走了，一路上都在思念他的花儿。", "t": [18150, 18688]}]}, {"id": "ch15p31", "audio": true, "sents": [{"es": "-La Tierra -le contestó el geógrafo-.", "zh": "” “到地球上去吧，”地理学家说，“它非常有名……” 小王子走了，一路上都在思念他的花儿。", "t": [100, 3162]}, {"es": "Tiene muy buena reputación…", "zh": "” “到地球上去吧，”地理学家说，“它非常有名……” 小王子走了，一路上都在思念他的花儿。", "t": [3162, 4713]}]}, {"id": "ch15p32", "audio": true, "sents": [{"es": "Y el principito partió pensando en su flor.", "zh": "” “到地球上去吧，”地理学家说，“它非常有名……” 小王子走了，一路上都在思念他的花儿。", "t": [100, 2313]}]}]}, {"id": "ch16", "title_es": "Capítulo 16", "title_zh": "第 16 章", "paras": [{"id": "ch16p00", "audio": true, "sents": [{"es": "El séptimo planeta fue, por consiguiente, la Tierra.", "zh": "第七颗星球就是地球。", "t": [100, 3788]}, {"es": "¡La Tierra no es un planeta cualquiera!", "zh": "地球可不是等闲之辈！", "t": [3788, 6712]}, {"es": "Se cuentan en él ciento once reyes (sin olvidar, naturalmente, los reyes negros), siete mil geógrafos, novecientos mil hombres de negocios, siete millones y medio de borrachos, trescientos once millones de vanidosos, es decir, alrededor de dos mil millones de personas mayores.", "zh": "地球上有一百一十一位国王（我当然没有忘记算上黑人国王）、七千位地理学家、九十万个商人、七百五十万个酒鬼、三亿一千一百万个爱慕虚荣的人，也就是说，约莫有二十亿个大人。", "t": [6712, 22012]}]}, {"id": "ch16p01", "audio": true, "sents": [{"es": "Para darles una idea de las dimensiones de la Tierra yo les diría que antes de la invención de la electricidad había que mantener sobre el conjunto de los seis continentes un verdadero ejército de cuatrocientos sesenta y dos mil quinientos once faroleros.", "zh": "我告诉你们，世界上还没有人发明电的时候，六大洲需要维持一支由四十六万二千五百一十一个点灯人组成的真正大军。", "t": [100, 12000]}]}, {"id": "ch16p02", "audio": true, "sents": [{"es": "Vistos desde lejos, hacían un espléndido efecto.", "zh": "从稍远处眺望这支大军，真是蔚为壮观。", "t": [100, 3862]}, {"es": "Los movimientos de este ejército estaban regulados como los de un ballet de ópera.", "zh": "点灯人的动作犹如芭蕾舞演员的动作：整齐划一，井然有序。", "t": [3862, 8800]}, {"es": "Primero venía el turno de los faroleros de Nueva Zelandia y de Australia.", "zh": "首先上场的是新西兰、澳大利亚的点灯人，他们点亮路灯后就去睡觉。", "t": [8800, 13438]}, {"es": "Encendían sus faroles y se iban a dormir.", "zh": "首先上场的是新西兰、澳大利亚的点灯人，他们点亮路灯后就去睡觉。", "t": [13438, 16812]}, {"es": "Después tocaba el turno en la danza a los faroleros de China y Siberia, que a su vez se perdían entre bastidores.", "zh": "接着加入舞蹈行列的是中国和西伯利亚的点灯人，然后他们也隐没于后台。", "t": [16812, 23662]}, {"es": "Luego seguían los faroleros de Rusia y la India, después los de Africa y Europa y finalmente, los de América del Sur y América del Norte.", "zh": "然后轮到俄罗斯和印度的点灯人，接着是非洲和欧洲的，然后是南美洲、北美洲。", "t": [23662, 32200]}, {"es": "Nunca se equivocaban en su orden de entrada en escena.", "zh": "这支大军的进场顺序从不错乱，真是让人叹为观止。", "t": [32200, 36000]}, {"es": "Era grandioso.", "zh": "这支大军的进场顺序从不错乱，真是让人叹为观止。", "t": [36000, 36863]}]}, {"id": "ch16p03", "audio": true, "sents": [{"es": "Solamente el farolero del único farol del polo norte y su colega del único farol del polo sur, llevaban una vida de ociosidad y descanso.", "zh": "惟有北极点灯人和他的南极同行，过着悠闲懒散的生活。", "t": [100, 8225]}, {"es": "No trabajaban más que dos veces al año.", "zh": "北极和南极各自仅有一盏灯，他们一年只点两次灯。", "t": [8225, 10425]}]}]}, {"id": "ch17", "title_es": "Capítulo 17", "title_zh": "第 17 章", "paras": [{"id": "ch17p00", "audio": true, "sents": [{"es": "Cuando se quiere ser ingenioso, sucede que se miente un poco.", "zh": "好出风头，喜欢卖弄聪明的人，多少会讲几句大话，吹点牛皮。", "t": [100, 4138]}, {"es": "No he sido muy honesto al hablar de los faroleros y corro el riesgo de dar una falsa idea de nuestro planeta a los que no lo conocen.", "zh": "我给你们介绍点灯人的时候，也不太老实。", "t": [4138, 11425]}, {"es": "Los hombres ocupan muy poco lugar sobre la Tierra.", "zh": "人在地球上占的位置微乎其微。", "t": [11425, 15000]}, {"es": "Si los dos mil millones de habitantes que la pueblan se pusieran de pie y un poco apretados, como en un mitin, cabrían fácilmente en una plaza de veinte millas de largo por veinte de ancho.", "zh": "倘若让散居在地球上的二十亿人口集中在一起开大会，他们可以松快地站在二十英里长二十英里宽的广场上。", "t": [15000, 25350]}, {"es": "La humanidad podría amontonarse sobre el más pequeño islote del Pacífico.", "zh": "当然，大人们不会相信这些话。", "t": [25350, 29100]}]}, {"id": "ch17p01", "audio": true, "sents": [{"es": "Las personas mayores no les creerán, seguramente, pues siempre se imaginan que ocupan mucho sitio.", "zh": "他们以为自己占了很大的位置，自以为自己像猴面包树那么庞大。", "t": [100, 6350]}, {"es": "Se creen importantes como los baobabs.", "zh": "他们不是喜欢数字吗？", "t": [6350, 9475]}, {"es": "Les dirán, pues, que hagan el cálculo; eso les gustará ya que adoran las cifras.", "zh": "但我劝你们别多此一举了，挺麻烦的，毫无用处的。", "t": [9475, 14912]}, {"es": "Pero no es necesario que pierdan el tiempo inútïlmente, puesto que tienen confianza en mí.", "zh": "小王子来到地球后，看不见一个人影，不由心里纳闷。", "t": [14912, 19187]}]}, {"id": "ch17p02", "audio": true, "sents": [{"es": "El principito, una vez que llegó a la Tierra, quedó sorprendido de no ver a nadie.", "zh": "他担心走错了路，到了别的星球了。", "t": [100, 5200]}, {"es": "Tenía miedo de haberse equivocado de planeta, cuando un anillo de color de luna se revolvió en la arena.", "zh": "“晚安！", "t": [5200, 10600]}]}, {"id": "ch17p03", "audio": true, "sents": [{"es": "-¡Buenas noches!", "zh": "“这儿是什么星球？", "t": [100, 2050]}, {"es": "-dijo el principito.", "zh": "”小王子问。", "t": [2050, 4125]}, {"es": "-¡Buenas noches!", "zh": "”小王子问。", "t": [4125, 6075]}, {"es": "-dijo la serpiente.", "zh": "“是地球，非洲。", "t": [6075, 8100]}, {"es": "-¿Sobre qué planeta he caído?", "zh": "“哦？", "t": [8100, 10550]}, {"es": "-preguntó el principito.", "zh": "……地球上没人吗？", "t": [10550, 11750]}]}, {"id": "ch17p04", "audio": true, "sents": [{"es": "-Sobre la Tierra, en Africa -respondió la serpiente.", "zh": "” “这儿是沙漠，沙漠里是没有人烟的，地球很大。", "t": [100, 3888]}, {"es": "-¡Ah!", "zh": "” “这儿是沙漠，沙漠里是没有人烟的，地球很大。", "t": [3888, 5150]}, {"es": "¿Y no hay nadie sobre la Tierra?", "zh": "”蛇说。", "t": [5150, 6700]}]}, {"id": "ch17p05", "audio": true, "sents": [{"es": "-Esto es el desierto.", "zh": "”蛇说。", "t": [100, 2338]}, {"es": "En los desiertos no hay nadie.", "zh": "小王子坐在一块石头上，抬头看天空： “我在想，星星发亮是否为了让每个人有一天能找到自己的星星。", "t": [2338, 4925]}, {"es": "La Tierra es muy grande -dijo la serpiente.", "zh": "小王子坐在一块石头上，抬头看天空： “我在想，星星发亮是否为了让每个人有一天能找到自己的星星。", "t": [4925, 7275]}]}, {"id": "ch17p06", "audio": true, "sents": [{"es": "El principito se sentó en una piedra y elevó los ojos al cielo.", "zh": "你看我的星球，它正好在我的头顶上……可它多么的遥远！", "t": [100, 3363]}]}, {"id": "ch17p07", "audio": true, "sents": [{"es": "-Yo me pregunto -dijo- si las estrellas están encendidas para que cada cual pueda un día encontrar la suya.", "zh": "” “它真美。", "t": [100, 6275]}, {"es": "Mira mi planeta; está precisamente encima de nosotros…", "zh": "” “我和一朵花赌气闹别扭呢。", "t": [6275, 10500]}, {"es": "Pero…", "zh": "”小王子说。", "t": [10500, 10788]}, {"es": "¡qué lejos está!", "zh": "”小王子说。", "t": [10788, 11600]}]}, {"id": "ch17p08", "audio": true, "sents": [{"es": "-Es muy bella -dijo la serpiente-.", "zh": "”蛇说。", "t": [100, 3038]}, {"es": "¿Y qué vienes tú a hacer aquí?", "zh": "“人在哪儿呢？", "t": [3038, 4500]}]}, {"id": "ch17p09", "audio": true, "sents": [{"es": "-Tengo problemas con una flor -dijo el principito.", "zh": "”小王子终于开口说话。", "t": [100, 3688]}, {"es": "-¡Ah!", "zh": "“待在沙漠有点孤独……” “跟人在一起也孤独。", "t": [3688, 3813]}]}, {"id": "ch17p10", "audio": true, "sents": [{"es": "Y se callaron.", "zh": "“待在沙漠有点孤独……” “跟人在一起也孤独。", "t": [100, 1862]}, {"es": "-¿Dónde están los hombres?", "zh": "“待在沙漠有点孤独……” “跟人在一起也孤独。", "t": [1862, 4188]}, {"es": "-prosiguió por fin el principito.", "zh": "”蛇说。", "t": [4188, 6850]}, {"es": "Se está un poco solo en el desierto…", "zh": "小王子久久凝视着它。", "t": [6850, 8824]}]}, {"id": "ch17p11", "audio": true, "sents": [{"es": "-También se está solo donde los hombres -afirmó la serpiente.", "zh": "“你是奇特的动物，”小王子终于说道，“你像一根指头般细……” “可我比国王的指头强大得多。", "t": [100, 3213]}]}, {"id": "ch17p12", "audio": true, "sents": [{"es": "El principito la miró largo rato y le dijo: -Eres un bicho raro, delgado como un dedo…", "zh": "”蛇说。", "t": [100, 4913]}]}, {"id": "ch17p13", "audio": true, "sents": [{"es": "-Pero soy más poderoso que el dedo de un rey -le interrumpió la serpiente.", "zh": "小王子微微一笑。", "t": [100, 3950]}]}, {"id": "ch17p14", "audio": true, "sents": [{"es": "El principito sonrió:", "zh": "“你没有那么强大吧……你连爪子都没有……你连走路都不会……” “船能送你走远路，可我能送你走更远的路。", "t": [100, 1363]}]}, {"id": "ch17p15", "audio": true, "sents": [{"es": "-No me pareces muy poderoso…", "zh": "“你没有那么强大吧……你连爪子都没有……你连走路都不会……” “船能送你走远路，可我能送你走更远的路。", "t": [100, 1612]}, {"es": "ni siquiera tienes patas…", "zh": "“你没有那么强大吧……你连爪子都没有……你连走路都不会……” “船能送你走远路，可我能送你走更远的路。", "t": [1612, 3225]}, {"es": "ni tan siquiera puedes viajar…", "zh": "” 它盘着小王子的脚踝，像一只金镯子。", "t": [3225, 4688]}]}, {"id": "ch17p16", "audio": true, "sents": [{"es": "-Puedo llevarte más lejos que un navío -dijo la serpiente.", "zh": "” 它盘着小王子的脚踝，像一只金镯子。", "t": [100, 3274]}]}, {"id": "ch17p17", "audio": true, "sents": [{"es": "Se enroscó alrededor del tobillo del principito como un brazalete de oro.", "zh": "“我碰到谁，就能把他送回他来的地方，”蛇还说，“但你纯洁，你是从星球上来的……” 小王子默默无言。", "t": [100, 3837]}]}, {"id": "ch17p18", "audio": true, "sents": [{"es": "-Al que yo toco, le hago volver a la tierra de donde salió.", "zh": "“我碰到谁，就能把他送回他来的地方，”蛇还说，“但你纯洁，你是从星球上来的……” 小王子默默无言。", "t": [100, 4112]}, {"es": "Pero tú eres puro y vienes de una estrella…", "zh": "“我同情你，在这花岗岩构成的地球上，你这么弱小。", "t": [4112, 6324]}]}, {"id": "ch17p19", "audio": true, "sents": [{"es": "El principito no respondió.", "zh": "“我同情你，在这花岗岩构成的地球上，你这么弱小。", "t": [100, 1625]}]}, {"id": "ch17p20", "audio": true, "sents": [{"es": "-Me das lástima, tan débil sobre esta tierra de granito.", "zh": "如果你有朝一日思念你的星球，我可以帮助你。", "t": [100, 4225]}, {"es": "Si algún día echas mucho de menos tu planeta, puedo ayudarte.", "zh": "我可以……” “啊！", "t": [4225, 8425]}, {"es": "Puedo…", "zh": "我完全明白你的意思，”小王子说，“但你的话为什么句句都像谜似的？", "t": [8425, 9012]}, {"es": "-¡Oh!", "zh": "我完全明白你的意思，”小王子说，“但你的话为什么句句都像谜似的？", "t": [9012, 10138]}, {"es": "-dijo el principito-.", "zh": "我完全明白你的意思，”小王子说，“但你的话为什么句句都像谜似的？", "t": [10138, 12212]}, {"es": "Te he comprendido.", "zh": "我完全明白你的意思，”小王子说，“但你的话为什么句句都像谜似的？", "t": [12212, 14150]}, {"es": "Pero ¿por qué hablas con enigmas?", "zh": "” “我能解一切谜。", "t": [14150, 15812]}]}, {"id": "ch17p21", "audio": true, "sents": [{"es": "-Yo los resuelvo todos -dijo la serpiente.", "zh": "”蛇说。", "t": [100, 2450]}]}, {"id": "ch17p22", "audio": true, "sents": [{"es": "Y se callaron.", "zh": "他们都不讲话了。", "t": [100, 875]}]}]}, {"id": "ch18", "title_es": "Capítulo 18", "title_zh": "第 18 章", "paras": [{"id": "ch18p00", "audio": true, "sents": [{"es": "El principito atravesó el desierto en el que sólo encontró una flor de tres pétalos, una flor de nada.", "zh": "一朵三瓣的花，一朵极普通平凡的花…… “你好。", "t": [100, 5350]}]}, {"id": "ch18p01", "audio": true, "sents": [{"es": "-¡Buenos días!", "zh": "”王子说。", "t": [100, 1950]}, {"es": "-dijo el principito.", "zh": "“你好。", "t": [1950, 4025]}, {"es": "-¡Buenos días!", "zh": "”花儿说。", "t": [4025, 5875]}, {"es": "-dijo la flor.", "zh": "“人在哪儿呢？", "t": [5875, 7588]}, {"es": "-¿Dónde están los hombres?", "zh": "”小王子彬彬有礼地问。", "t": [7588, 9912]}, {"es": "-preguntó cortésmente el principito.", "zh": "花儿有一天曾看见一队骆驼走过。", "t": [9912, 11825]}]}, {"id": "ch18p02", "audio": true, "sents": [{"es": "La flor, un día, había visto pasar una caravana.", "zh": "“人？", "t": [100, 3988]}, {"es": "-¿Los hombres?", "zh": "依我看，人是有的，大概六七个吧。", "t": [3988, 5712]}, {"es": "No existen más que seis o siete, me parece.", "zh": "好几年前我见过他们。", "t": [5712, 8175]}]}, {"id": "ch18p03", "audio": true, "sents": [{"es": "Los he visto hace ya años y nunca se sabe dónde encontrarlos.", "zh": "但我不知道在哪儿能找到他们。", "t": [100, 4400]}, {"es": "El viento los pasea.", "zh": "他们没有根，这就使他们吃尽了苦头。", "t": [4400, 6488]}, {"es": "Les faltan las raíces.", "zh": "他们没有根，这就使他们吃尽了苦头。", "t": [6488, 8875]}, {"es": "Esto les molesta.", "zh": "” “别了。", "t": [8875, 9874]}]}, {"id": "ch18p04", "audio": true, "sents": [{"es": "-Adiós -dijo el principito.", "zh": "”小王子说。", "t": [100, 1650]}]}, {"id": "ch18p05", "audio": true, "sents": [{"es": "-Adiós -dijo la flor.", "zh": "”花儿说。", "t": [100, 1350]}]}]}, {"id": "ch19", "title_es": "Capítulo 19", "title_zh": "第 19 章", "paras": [{"id": "ch19p00", "audio": true, "sents": [{"es": "El principito escaló hasta la cima de una alta montaña.", "zh": "小王子登上一座高山。", "t": [100, 3950]}, {"es": "Las únicas montañas que él había conocido eran los tres volcanes que le llegaban a la rodilla.", "zh": "以前他只见过自己的那三座火山，火山很矮，才到他的膝盖。", "t": [3950, 9512]}, {"es": "El volcán extinguido lo utilizaba como taburete.", "zh": "死火山只能给他当凳子坐。", "t": [9512, 13000]}, {"es": "\"Desde una montaña tan alta como ésta, se había dicho, podré ver todo el planeta y a todos los hombres…\" Pero no alcanzó a ver más que algunas puntas de rocas.", "zh": "“您好。", "t": [13000, 22088]}]}, {"id": "ch19p01", "audio": true, "sents": [{"es": "-¡Buenos días!", "zh": "“您好……您好……您好……”回声应道。", "t": [100, 1950]}, {"es": "-exclamó el principito al acaso.", "zh": "“您是谁？", "t": [1950, 4725]}, {"es": "-¡Buenos días!", "zh": "”小王子问。", "t": [4725, 6575]}, {"es": "¡Buenos días!", "zh": "”小王子问。", "t": [6575, 8425]}, {"es": "¡Buenos días!", "zh": "“您是谁……您是谁……您是谁……”回声应道。", "t": [8425, 10275]}, {"es": "-respondió el eco -¿Quién eres tú?", "zh": "“您是谁……您是谁……您是谁……”回声应道。", "t": [10275, 13125]}, {"es": "-preguntó el principito.", "zh": "“做我的朋友吧，我很孤单……”他说。", "t": [13125, 15312]}, {"es": "-¿Quién eres tú?…", "zh": "“做我的朋友吧，我很孤单……”他说。", "t": [15312, 17075]}, {"es": "¿Quién eres tú?…", "zh": "“做我的朋友吧，我很孤单……”他说。", "t": [17075, 18838]}, {"es": "¿Quién eres tú?…", "zh": "“做我的朋友吧，我很孤单……”他说。", "t": [18838, 19612]}, {"es": "-contestó el eco.", "zh": "“我很孤单……我很孤单……我很孤单……”回声又答应道。", "t": [19612, 20562]}]}, {"id": "ch19p02", "audio": true, "sents": [{"es": "-Sed mis amigos, estoy solo -dijo el principito.", "zh": "“我很孤单……我很孤单……我很孤单……”回声又答应道。", "t": [100, 2950]}]}, {"id": "ch19p03", "audio": true, "sents": [{"es": "-Estoy solo…", "zh": "“多么古怪的星球！", "t": [100, 962]}, {"es": "estoy solo…", "zh": "“多么古怪的星球！", "t": [962, 1950]}, {"es": "estoy solo…", "zh": "“多么古怪的星球！", "t": [1950, 2912]}, {"es": "-repitió el eco.", "zh": "”小王子想道。", "t": [2912, 3900]}]}, {"id": "ch19p04", "audio": true, "sents": [{"es": "\"¡Qué planeta más raro!", "zh": "”小王子想道。", "t": [100, 2250]}, {"es": "-pensó entonces el principito-, es seco, puntiagudo y salado.", "zh": "”小王子想道。", "t": [2250, 6500]}, {"es": "Y los hombres carecen de imaginación; no hacen más que repetir lo que se les dice…", "zh": "“干干巴巴的，尖尖峭峭的，带点咸味儿的，这儿的人缺乏想像力，他们净重复别人讲过的话……而在我的那个星球里，我有一朵花，她总是抢先讲话……”", "t": [6500, 11725]}, {"es": "En mi tierra tenía una flor: hablaba siempre la primera…", "zh": "“干干巴巴的，尖尖峭峭的，带点咸味儿的，这儿的人缺乏想像力，他们净重复别人讲过的话……而在我的那个星球里，我有一朵花，她总是抢先讲话……”", "t": [11725, 14837]}, {"es": "\"", "zh": "“干干巴巴的，尖尖峭峭的，带点咸味儿的，这儿的人缺乏想像力，他们净重复别人讲过的话……而在我的那个星球里，我有一朵花，她总是抢先讲话……”", "t": [14837, 15337]}]}]}, {"id": "ch20", "title_es": "Capítulo 20", "title_zh": "第 20 章", "paras": [{"id": "ch20p00", "audio": true, "sents": [{"es": "Pero sucedió que el principito, habiendo atravesado arenas, rocas y nieves, descubrió finalmente un camino.", "zh": "小王子在沙漠、山峰、大雪中长途跋涉。", "t": [100, 7138]}, {"es": "Y los caminos llevan siempre a la morada de los hombres.", "zh": "”他说。", "t": [7138, 9838]}]}, {"id": "ch20p01", "audio": true, "sents": [{"es": "-¡Buenos días!", "zh": "这是一座盛开着玫瑰花的花园。", "t": [100, 1950]}, {"es": "-dijo.", "zh": "“你好。", "t": [1950, 2338]}]}, {"id": "ch20p02", "audio": true, "sents": [{"es": "Era un jardín cuajado de rosas.", "zh": "“你好。", "t": [100, 2925]}, {"es": "-¡Buenos días!", "zh": "小王子看着她们。", "t": [2925, 4775]}, {"es": "-dijeran las rosas.", "zh": "小王子看着她们。", "t": [4775, 5887]}]}, {"id": "ch20p03", "audio": true, "sents": [{"es": "El principito las miró.", "zh": "她们一个个全像他的那朵花儿。", "t": [100, 2338]}, {"es": "¡Todas se parecían tanto a su flor!", "zh": "“你们是谁？", "t": [2338, 5100]}, {"es": "-¿Quiénes son ustedes?", "zh": "”小王子大吃一惊，问她们说。", "t": [5100, 7288]}, {"es": "-les preguntó estupefacto.", "zh": "“我们是玫瑰花。", "t": [7288, 8788]}]}, {"id": "ch20p04", "audio": true, "sents": [{"es": "-Somos las rosas -respondieron éstas.", "zh": "”玫瑰花们说。", "t": [100, 3462]}, {"es": "-¡Ah!", "zh": "“啊！", "t": [3462, 4725]}, {"es": "-exclamó el principito.", "zh": "”小王子说…… 小王子伤心极了。", "t": [4725, 6024]}]}, {"id": "ch20p05", "audio": true, "sents": [{"es": "Y se sintió muy desgraciado.", "zh": "”小王子说…… 小王子伤心极了。", "t": [100, 2650]}, {"es": "Su flor le había dicho que era la única de su especie en todo el universo.", "zh": "他的花儿告诉他，大千世界中，她是惟一的玫瑰花。", "t": [2650, 7312]}, {"es": "¡Y ahora t.enía ante sus ojos más de cinco mil.todas semejantes, en un solo jardín!", "zh": "可是在这儿，仅仅一座花园里就有五千朵玫瑰花，全都长得一模一样！", "t": [7312, 12175]}]}, {"id": "ch20p06", "audio": true, "sents": [{"es": "Si ella viese todo esto, se decía el principito, se sentiría vejada, tosería muchísimo y simularía morir para escapar al ridículo.", "zh": "可是在这儿，仅仅一座花园里就有五千朵玫瑰花，全都长得一模一样！", "t": [100, 8138]}, {"es": "Y yo tendría que fingirle cuidados, pues sería capaz de dejarse morir verdaderamente para humillarme a mí también…", "zh": "他想：“要是她看见这群玫瑰花，她又要恼羞成怒了……为了挽回面子，她又要装模作样地咳嗽，做出一副要死要活的样子，我也要呵护她，不然，她为了羞辱我，真会寻死的……” 他又想道：“我原以为我拥有一朵独一无二的花，我以为我很富足，原来她只是一朵极平常的花，她，以及我那三座只有我膝盖高的火山——其中一座也许永远都活不了，它们不能使我成为一位伟大的王子了……” 于是，他趴倒在草地上伤心地哭泣。", "t": [8138, 14037]}, {"es": "\"", "zh": "他想：“要是她看见这群玫瑰花，她又要恼羞成怒了……为了挽回面子，她又要装模作样地咳嗽，做出一副要死要活的样子，我也要呵护她，不然，她为了羞辱我，真会寻死的……” 他又想道：“我原以为我拥有一朵独一无二的花，我以为我很富足，原来她只是一朵极平常的花，她，以及我那三座只有我膝盖高的火山——其中一座也许永远都活不了，它们不能使我成为一位伟大的王子了……” 于是，他趴倒在草地上伤心地哭泣。", "t": [14037, 14537]}]}, {"id": "ch20p07", "audio": true, "sents": [{"es": "Y luego continuó diciéndose: \"Me creía rico con una flor única y resulta que no tengo más que una rosa ordinaria.", "zh": "他想：“要是她看见这群玫瑰花，她又要恼羞成怒了……为了挽回面子，她又要装模作样地咳嗽，做出一副要死要活的样子，我也要呵护她，不然，她为了羞辱我，真会寻死的……” 他又想道：“我原以为我拥有一朵独一无二的花，我以为我很富足，原来她只是一朵极平常的花，她，以及我那三座只有我膝盖高的火山——其中一座也许永远都活不了，它们不能使我成为一位伟大的王子了……” 于是，他趴倒在草地上伤心地哭泣。", "t": [100, 7338]}, {"es": "Eso y mis tres volcanes que apenas me llegan a la rodilla y uno de Ios cuales acaso esté extinguido para siempre.", "zh": "他想：“要是她看见这群玫瑰花，她又要恼羞成怒了……为了挽回面子，她又要装模作样地咳嗽，做出一副要死要活的样子，我也要呵护她，不然，她为了羞辱我，真会寻死的……” 他又想道：“我原以为我拥有一朵独一无二的花，我以为我很富足，原来她只是一朵极平常的花，她，以及我那三座只有我膝盖高的火山——其中一座也许永远都活不了，它们不能使我成为一位伟大的王子了……” 于是，他趴倒在草地上伤心地哭泣。", "t": [7338, 14450]}, {"es": "Realmente no soy un gran príncipe…", "zh": "他想：“要是她看见这群玫瑰花，她又要恼羞成怒了……为了挽回面子，她又要装模作样地咳嗽，做出一副要死要活的样子，我也要呵护她，不然，她为了羞辱我，真会寻死的……” 他又想道：“我原以为我拥有一朵独一无二的花，我以为我很富足，原来她只是一朵极平常的花，她，以及我那三座只有我膝盖高的火山——其中一座也许永远都活不了，它们不能使我成为一位伟大的王子了……” 于是，他趴倒在草地上伤心地哭泣。", "t": [14450, 17388]}, {"es": "\" Y echándose sobre la hierba, el principito lloró.", "zh": "他想：“要是她看见这群玫瑰花，她又要恼羞成怒了……为了挽回面子，她又要装模作样地咳嗽，做出一副要死要活的样子，我也要呵护她，不然，她为了羞辱我，真会寻死的……” 他又想道：“我原以为我拥有一朵独一无二的花，我以为我很富足，原来她只是一朵极平常的花，她，以及我那三座只有我膝盖高的火山——其中一座也许永远都活不了，它们不能使我成为一位伟大的王子了……” 于是，他趴倒在草地上伤心地哭泣。", "t": [17388, 19950]}]}]}, {"id": "ch21", "title_es": "Capítulo 21", "title_zh": "第 21 章", "paras": [{"id": "ch21p00", "audio": true, "sents": [{"es": "Entonces apareció el zorro:", "zh": "就在这个时候，出现了一只狐狸。", "t": [100, 1713]}]}, {"id": "ch21p01", "audio": true, "sents": [{"es": "-¡Buenos días!", "zh": "就在这个时候，出现了一只狐狸。", "t": [100, 1950]}, {"es": "-dijo el zorro.", "zh": "“你好。", "t": [1950, 3788]}, {"es": "-¡Buenos días!", "zh": "”狐狸说。", "t": [3788, 5638]}, {"es": "-respondió cortésmente el principito que se volvió pero no vío nada.", "zh": "”小王子彬彬有礼地回答，他转过身，但看不见有什么东西。", "t": [5638, 9038]}]}, {"id": "ch21p02", "audio": true, "sents": [{"es": "-Estoy aquí, bajo el manzano -díjo la voz.", "zh": "“我在这里，”那声音说，“在苹果树下。", "t": [100, 3525]}, {"es": "-¿Quién eres tú?", "zh": "“我在这里，”那声音说，“在苹果树下。", "t": [3525, 5288]}, {"es": "-preguntó el principito-.", "zh": "” “你是谁？", "t": [5288, 7475]}, {"es": "¡Qué bonito eres!", "zh": "” “你是谁？", "t": [7475, 8425]}]}, {"id": "ch21p03", "audio": true, "sents": [{"es": "-Soy un zorro -dijo el zorro.", "zh": "”小王子说，“你真漂亮……” “我是狐狸。", "t": [100, 1725]}]}, {"id": "ch21p04", "audio": true, "sents": [{"es": "-Ven a jugar conmigo -le propuso el principito-, ¡estoy tan triste!", "zh": "”狐狸说。", "t": [100, 3537]}]}, {"id": "ch21p05", "audio": true, "sents": [{"es": "-No puedo jugar contigo -dijo el zorro-, no estoy domesticado.", "zh": "”小王子向他建议。", "t": [100, 4375]}, {"es": "-¡Ah, perdón!", "zh": "“我非常伤心……” “我不能跟你一起玩，”狐狸说，“我不是驯养的动物。", "t": [4375, 6075]}, {"es": "-dijo el principito.", "zh": "“我非常伤心……” “我不能跟你一起玩，”狐狸说，“我不是驯养的动物。", "t": [6075, 7163]}]}, {"id": "ch21p06", "audio": true, "sents": [{"es": "Pero después de una breve reflexión, añadió: -¿Qué significa \"domesticar\"?", "zh": "” “哦，对不起。", "t": [100, 4200]}]}, {"id": "ch21p07", "audio": true, "sents": [{"es": "-Tú no eres de aquí -dijo el zorro- ¿qué buscas?", "zh": "小王子想了想，又问： “什么叫做‘驯养’？", "t": [100, 2650]}]}, {"id": "ch21p08", "audio": true, "sents": [{"es": "-Busco a los hombres -le respondió el principito-.", "zh": "” “你不是本地人。", "t": [100, 3700]}, {"es": "¿Qué significa \"domesticar\"?", "zh": "“人有枪，人打猎，太可恶了！", "t": [3700, 5113]}]}, {"id": "ch21p09", "audio": true, "sents": [{"es": "-Los hombres -dijo el zorro- tienen escopetas y cazan.", "zh": "可人也养鸡！", "t": [100, 4112]}, {"es": "¡Es muy molesto!", "zh": "你也找鸡吗？", "t": [4112, 5988]}, {"es": "Pero también crían gallinas.", "zh": "” “不！", "t": [5988, 8525]}, {"es": "Es lo único que les interesa.", "zh": "”小王子说，“我找朋友。", "t": [8525, 11125]}, {"es": "¿Tú buscas gallinas?", "zh": "什么叫做‘驯养’？", "t": [11125, 12250]}]}, {"id": "ch21p10", "audio": true, "sents": [{"es": "-No -díjo el principito-.", "zh": "什么叫做‘驯养’？", "t": [100, 2500]}, {"es": "Busco amigos.", "zh": "” “这是一件被人遗忘干净的事了，”狐狸说，“它的意思就是‘建立联系’……” “建立联系？", "t": [2500, 4412]}, {"es": "¿Qué significa \"domesticar\"?", "zh": "” “这是一件被人遗忘干净的事了，”狐狸说，“它的意思就是‘建立联系’……” “建立联系？", "t": [4412, 6800]}, {"es": "-volvió a preguntar el principito.", "zh": "” “这是一件被人遗忘干净的事了，”狐狸说，“它的意思就是‘建立联系’……” “建立联系？", "t": [6800, 8463]}]}, {"id": "ch21p11", "audio": true, "sents": [{"es": "-Es una cosa ya olvidada -dijo el zorro-, significa \"crear vínculos…", "zh": "” “当然，”狐狸说，“对我而言，你不过是一个小男孩，和千千万万的小男孩没有两样。", "t": [100, 5100]}, {"es": "\" -¿Crear vínculos?", "zh": "” “当然，”狐狸说，“对我而言，你不过是一个小男孩，和千千万万的小男孩没有两样。", "t": [5100, 6062]}]}, {"id": "ch21p12", "audio": true, "sents": [{"es": "-Efectivamente, verás -dijo el zorro-.", "zh": "” “当然，”狐狸说，“对我而言，你不过是一个小男孩，和千千万万的小男孩没有两样。", "t": [100, 3175]}, {"es": "Tú no eres para mí todavía más que un muchachito igual a otros cien mil muchachitos y no te necesito para nada.", "zh": "而且我不需要你，你也不需要我。", "t": [3175, 9675]}, {"es": "Tampoco tú tienes necesidad de mí y no soy para ti más que un zorro entre otros cien mil zorros semejantes.", "zh": "但如果你驯养了我，我们就互相需要了。", "t": [9675, 16012]}, {"es": "Pero si tú me domesticas, entonces tendremos necesidad el uno del otro.", "zh": "你就是我世界上惟一的人了，我也是你世上惟一的狐狸了……” “我有点明白了。", "t": [16012, 20700]}, {"es": "Tú serás para mí único en el mundo, yo seré para ti único en el mundo…", "zh": "”小王子说。", "t": [20700, 24512]}]}, {"id": "ch21p13", "audio": true, "sents": [{"es": "-Comienzo a comprender -dijo el principito-.", "zh": "“有一朵花儿……我认为她驯养了我……” “这可能，”狐狸说，“地球上有各色各样，形形色色的东西……” “啊！", "t": [100, 3300]}, {"es": "Hay una flor…", "zh": "“有一朵花儿……我认为她驯养了我……” “这可能，”狐狸说，“地球上有各色各样，形形色色的东西……” “啊！", "t": [3300, 4225]}, {"es": "creo que ella me ha domesticado…", "zh": "“有一朵花儿……我认为她驯养了我……” “这可能，”狐狸说，“地球上有各色各样，形形色色的东西……” “啊！", "t": [4225, 5776]}]}, {"id": "ch21p14", "audio": true, "sents": [{"es": "-Es posible -concedió el zorro-, en la Tierra se ven todo tipo de cosas.", "zh": "她不在地球上。", "t": [100, 4900]}, {"es": "-¡Oh, no es en la Tierra!", "zh": "狐狸露出大惊的神色。", "t": [4900, 7075]}, {"es": "-exclamó el principito.", "zh": "“在另一个星球上？", "t": [7075, 8374]}]}, {"id": "ch21p15", "audio": true, "sents": [{"es": "El zorro pareció intrigado: -¿En otro planeta?", "zh": "” “那颗星球上，有猎人吗？", "t": [100, 2500]}]}, {"id": "ch21p16", "audio": true, "sents": [{"es": "-Sí.", "zh": "” “那颗星球上，有猎人吗？", "t": [100, 1438]}, {"es": "-¿Hay cazadores en ese planeta?", "zh": "” “没有。", "t": [1438, 3062]}]}, {"id": "ch21p17", "audio": true, "sents": [{"es": "-No.", "zh": "” “那可有意思了！", "t": [100, 1450]}, {"es": "-¡Qué interesante!", "zh": "” “那可有意思了！", "t": [1450, 3312]}, {"es": "¿Y gallinas?", "zh": "有鸡吗？", "t": [3312, 3962]}]}, {"id": "ch21p18", "audio": true, "sents": [{"es": "-No.", "zh": "” “没有。", "t": [100, 338]}]}, {"id": "ch21p19", "audio": true, "sents": [{"es": "-Nada es perfecto -suspiró el zorro.", "zh": "” “没有。", "t": [100, 2288]}]}, {"id": "ch21p20", "audio": true, "sents": [{"es": "Y después volviendo a su idea:", "zh": "” “世上就没有十全十美的东西。", "t": [100, 1774]}]}, {"id": "ch21p21", "audio": true, "sents": [{"es": "-Mi vida es muy monótona.", "zh": "”狐狸叹了一口气。", "t": [100, 2462]}, {"es": "Cazo gallinas y los hombres me cazan a mí.", "zh": "狐狸又扯回原先的话题： “我的生活枯燥乏味，异常单调。", "t": [2462, 5562]}, {"es": "Todas las gallinas se parecen y todos los hombres son iguales; por consiguiente me aburro un poco.", "zh": "我逮鸡，人逮我。", "t": [5562, 11375]}, {"es": "Si tú me domesticas, mi vida estará llena de sól.", "zh": "但如果你驯养我，我的生活就会充满阳光。", "t": [11375, 13950]}]}, {"id": "ch21p22", "audio": true, "sents": [{"es": "Conoceré el rumor de unos pasos diferentes a todos los demás.", "zh": "我能辨得出与众不同的脚步声。", "t": [100, 4375]}, {"es": "Los otros pasos me hacen esconder bajo la tierra; los tuyos me llamarán fuera de la madriguera como una música.", "zh": "你的脚步声却像悦耳的音乐，召唤我走出洞穴。", "t": [4375, 11150]}, {"es": "Y además, ¡mira!", "zh": "你瞧！", "t": [11150, 13112]}, {"es": "¿Ves allá abajo los campos de trigo?", "zh": "你看那儿，那不是一片麦田吗？", "t": [13112, 15962]}, {"es": "Yo no como pan y por lo tanto el trigo es para mí algo inútil.", "zh": "我不吃面包，我不需要小麦，麦田引不起我的想像力。", "t": [15962, 19962]}, {"es": "Los campos de trigo no me recuerdan nada y eso me pone triste.", "zh": "说到这个，实在可悲！", "t": [19962, 24188]}, {"es": "¡Pero tú tienes los cabellos dorados y será algo maravilloso cuando me domestiques!", "zh": "但你的头发是金灿灿的，它会叫我想起你的，我就会爱上风吹麦子的声音……”狐狸没说下去，对小王子瞧了好久，又说： “请你……驯养我吧！", "t": [24188, 29275]}, {"es": "El trigo, que es dorado también, será un recuerdo de ti.", "zh": "但你的头发是金灿灿的，它会叫我想起你的，我就会爱上风吹麦子的声音……”狐狸没说下去，对小王子瞧了好久，又说： “请你……驯养我吧！", "t": [29275, 33238]}, {"es": "Y amaré el ruido del viento en el trigo.", "zh": "” “我很愿意，”小王子回答说，“但我的时间不多，我还要寻找朋友，还要了解许多新鲜的事物。", "t": [33238, 35212]}]}, {"id": "ch21p23", "audio": true, "sents": [{"es": "El zorro se calló y miró un buen rato al principito:", "zh": "” “我很愿意，”小王子回答说，“但我的时间不多，我还要寻找朋友，还要了解许多新鲜的事物。", "t": [100, 2850]}]}, {"id": "ch21p24", "audio": true, "sents": [{"es": "-Por favor…", "zh": "” “我很愿意，”小王子回答说，“但我的时间不多，我还要寻找朋友，还要了解许多新鲜的事物。", "t": [100, 762]}, {"es": "domestícame -le dijo.", "zh": "” “我很愿意，”小王子回答说，“但我的时间不多，我还要寻找朋友，还要了解许多新鲜的事物。", "t": [762, 2038]}]}, {"id": "ch21p25", "audio": true, "sents": [{"es": "-Bien quisiera -le respondió el principito pero no tengo mucho tiempo.", "zh": "” “人只认识自己驯养的东西。", "t": [100, 4738]}, {"es": "He de buscar amigos y conocer muchas cosas.", "zh": "“人再没时间认识什么事物。", "t": [4738, 7138]}]}, {"id": "ch21p26", "audio": true, "sents": [{"es": "-Sólo se conocen bien las cosas que se domestican -dijo el zorro-.", "zh": "他们到商店买现成的东西，但没有一家商店是出售朋友的，人也就没有朋友了。", "t": [100, 4475]}, {"es": "Los hombres ya no fienen tiempo de conocer nada.", "zh": "如果你想要朋友，你就驯养我吧！", "t": [4475, 7888]}, {"es": "Lo compran todo hecho en las tiendas.", "zh": "如果你想要朋友，你就驯养我吧！", "t": [7888, 10838]}, {"es": "Y como no hay tiendas donde vendan amigos, Ios hombres no tienen ya amigos.", "zh": "”小王子说。", "t": [10838, 16075]}, {"es": "¡Si quieres un amigo, domestícame!", "zh": "”狐狸回答说。", "t": [16075, 18888]}, {"es": "-¿Qué debo hacer?", "zh": "“首先你要离我稍远点，坐着，像这样，坐在草地上。", "t": [18888, 20662]}, {"es": "-preguntó el príncipito.", "zh": "“首先你要离我稍远点，坐着，像这样，坐在草地上。", "t": [20662, 21937]}]}, {"id": "ch21p27", "audio": true, "sents": [{"es": "-Debes tener mucha paciencia -respondió el zorro-.", "zh": "我斜瞟着你，你什么也别对我说。", "t": [100, 3962]}, {"es": "Te sentarás al principio ún poco lejos de mí, así, en el suelo; yo te miraré con el rabillo del ojo y tú no me dirás nada.", "zh": "可是每天你可以坐得稍近一点……” 翌日，小王子又来了。", "t": [3962, 11538]}, {"es": "El lenguaje es fuente de malos entendidos.", "zh": "“最好在同一个时间来，”狐狸说，“例如，如果你是下午四点钟来的，从三点钟开始，我就开始感觉到幸福的滋味了。", "t": [11538, 14762]}, {"es": "Pero cada día podrás sentarte un poco más cerca…", "zh": "“最好在同一个时间来，”狐狸说，“例如，如果你是下午四点钟来的，从三点钟开始，我就开始感觉到幸福的滋味了。", "t": [14762, 17288]}]}, {"id": "ch21p28", "audio": true, "sents": [{"es": "El principito volvió al día siguiente.", "zh": "越接近四点钟，我越觉得幸福。", "t": [100, 2075]}]}, {"id": "ch21p29", "audio": true, "sents": [{"es": "-Hubiera sido mejor -dijo el zorro- que vinieras a la misma hora.", "zh": "越接近四点钟，我越觉得幸福。", "t": [100, 4500]}, {"es": "Si vienes, por ejempló, a las cuatro de la tarde; desde las tres yo empezaría a ser dichoso.", "zh": "到了四点钟，我就心神恍惚，坐立不安了。", "t": [4500, 10262]}, {"es": "Cuanto más avance la hora, más feliz me sentiré.", "zh": "我发现了幸福的价值，但是如果你不按时来，我就不知道几点钟该装扮我的心，仪式还是需要的。", "t": [10262, 13950]}, {"es": "A las cuatro me sentiré agitado e inquieto, descubriré así lo que vale la feliçidad.", "zh": "” “什么叫做‘仪式’？", "t": [13950, 19275]}, {"es": "Pero si tú vienes a cualquier hora, nunça sabré cuándo preparar mi corazón…", "zh": "”狐狸说。", "t": [19275, 24038]}, {"es": "Los ritos son necesarios.", "zh": "“仪式就是使得某一日不同于其他日子，某一个小时不同于别的小时。", "t": [24038, 26638]}, {"es": "-¿Qué es un rito?", "zh": "“仪式就是使得某一日不同于其他日子，某一个小时不同于别的小时。", "t": [26638, 28500]}, {"es": "-inquirió el principito.", "zh": "“仪式就是使得某一日不同于其他日子，某一个小时不同于别的小时。", "t": [28500, 29787]}]}, {"id": "ch21p30", "audio": true, "sents": [{"es": "-Es también algo demasiado olvidado -dijo el zorro-.", "zh": "比如说，猎人们有个仪式，每逢星期四，他们就与村里的姑娘们跳舞，星期四就成了再美妙不过的日子了！", "t": [100, 3888]}, {"es": "Es lo que hace que un día no se parezca a otro día y que una hora sea diferente a otra.", "zh": "比如说，猎人们有个仪式，每逢星期四，他们就与村里的姑娘们跳舞，星期四就成了再美妙不过的日子了！", "t": [3888, 8362]}]}, {"id": "ch21p31", "audio": true, "sents": [{"es": "Entre los cazadores, por ejemplo, hay un rito.", "zh": "我也就可以到葡萄园里去闲逛了。", "t": [100, 3675]}, {"es": "Los jueves bailan con las muchachas del pueblo.", "zh": "如果猎人跳舞不挑日子，每一天都一样，我就没有假期了。", "t": [3675, 6975]}, {"es": "Los jueves entonces son días maravillosos en los que puedo ir de paseo hasta la viña.", "zh": "” 于是小王子驯养狐狸了。", "t": [6975, 12162]}, {"es": "Si los cazadores no bailaran en día fijo, todos los días se parecerían y yo no tendría vacaciones.", "zh": "”狐狸说，“……我想哭了。", "t": [12162, 17738]}]}, {"id": "ch21p32", "audio": true, "sents": [{"es": "De esta manera el principito domesticó al zorro.", "zh": "” “这就是你的不对了，”小王子说，“我一点也不想伤害你，但你却要我驯养你……” “不错。", "t": [100, 3575]}, {"es": "Y cuando se fue acercando eI día de la partida: -¡Ah!", "zh": "”狐狸说。", "t": [3575, 7212]}, {"es": "-dijo el zorro-, lloraré.", "zh": "”小王子说。", "t": [7212, 8637]}]}, {"id": "ch21p33", "audio": true, "sents": [{"es": "-Tuya es la culpa -le dijo el principito-, yo no quería hacerte daño, pero tú has querido que te domestique…", "zh": "“那你是一无所获了！", "t": [100, 5600]}]}, {"id": "ch21p34", "audio": true, "sents": [{"es": "-Ciertamente -dijo el zorro.", "zh": "” “我有收获的，”狐狸说，“我得到了小麦的颜色。", "t": [100, 1575]}]}, {"id": "ch21p35", "audio": true, "sents": [{"es": "-Y vas a llorar!, -dijo él principito.", "zh": "” 然后他又说： “你去探望玫瑰花们吧，你就会明白，你的玫瑰花是世界上独一无二的花儿。", "t": [100, 3050]}, {"es": "-¡Seguro!", "zh": "” 然后他又说： “你去探望玫瑰花们吧，你就会明白，你的玫瑰花是世界上独一无二的花儿。", "t": [3050, 3562]}]}, {"id": "ch21p36", "audio": true, "sents": [{"es": "-No ganas nada.", "zh": "” 然后他又说： “你去探望玫瑰花们吧，你就会明白，你的玫瑰花是世界上独一无二的花儿。", "t": [100, 1038]}]}, {"id": "ch21p37", "audio": true, "sents": [{"es": "-Gano -dijo el zoro- he ganado a causa del color del trigo.", "zh": "” 然后他又说： “你去探望玫瑰花们吧，你就会明白，你的玫瑰花是世界上独一无二的花儿。", "t": [100, 3362]}]}, {"id": "ch21p38", "audio": true, "sents": [{"es": "Y luego añadió:", "zh": "然后你回来与我告别，我会送你一桩秘密作为礼物。", "t": [100, 1000]}]}, {"id": "ch21p39", "audio": true, "sents": [{"es": "-Vete a ver las rosas; comprenderás que la tuya es única en el mundo.", "zh": "然后你回来与我告别，我会送你一桩秘密作为礼物。", "t": [100, 4762]}, {"es": "Volverás a decirme adiós y yo te regalaré un secreto.", "zh": "” 小王子探望玫瑰花们，并对她们说： “你们一点也不像我的玫瑰，你们还无足轻重，没有人驯养你们，你们也没有驯养任何人。", "t": [4762, 7650]}]}, {"id": "ch21p40", "audio": true, "sents": [{"es": "El principito se fue a ver las rosas a las que dijo:", "zh": "” 小王子探望玫瑰花们，并对她们说： “你们一点也不像我的玫瑰，你们还无足轻重，没有人驯养你们，你们也没有驯养任何人。", "t": [100, 2724]}]}, {"id": "ch21p41", "audio": true, "sents": [{"es": "-No son nada, ni en nada se parecen a mi rosa.", "zh": "你们的今天如同我的狐狸的昨天。", "t": [100, 3775]}, {"es": "Nadie las ha domesticado ni ustedes han domesticado a nadie.", "zh": "你们的今天如同我的狐狸的昨天。", "t": [3775, 6863]}]}, {"id": "ch21p42", "audio": true, "sents": [{"es": "Son como el zorro era antes, que en nada se diferenciaba de otros cien mil zorros.", "zh": "昨天的他与千千万万的狐狸一样，但自从我让他做了我的朋友，他就是世上绝无仅有的狐狸了。", "t": [100, 5412]}, {"es": "Pero yo le hice mi amigo y ahora es único en el mundo.", "zh": "” 玫瑰花们听了心里怪不自在的。", "t": [5412, 8012]}]}, {"id": "ch21p43", "audio": true, "sents": [{"es": "Las rosas se sentían molestas oyendo al principito, que continuó diciéndoles:", "zh": "“你们长得很美，但你们的感情世界一片空白。", "t": [100, 4188]}]}, {"id": "ch21p44", "audio": true, "sents": [{"es": "-Son muy bellas, pero están vacías y nadie daría la vida por ustedes.", "zh": "“没有人为你们而死。", "t": [100, 4688]}, {"es": "Cualquiera que las vea podrá creer indudablemente que mí rosa es igual que cualquiera de ustedes.", "zh": "不错，行人会认为我的玫瑰与你们没有两样，但只有她比你们重要，因为我给她浇了水，我给她盖上花罩，我给她竖起屏风，给她避风挡雨。", "t": [4688, 10400]}, {"es": "Pero ella se sabe más importante que todas, porque yo la he regado, porque ha sido a ella a la que abrigué con el fanal, porque yo le maté los gusanos (salvo dos o tres que se hicieron mariposas) y es a ella a la que yo he oído quejarse, alabarse y algunas veces hasta callarse.", "zh": "我为她杀死了几条毛虫（除了两三条我没杀，要让它们变成蝴蝶），我倾听她的抱怨，或她的吹嘘，有时也看着她默默无语的样子，因为她是我的玫瑰。", "t": [10400, 26062]}, {"es": "Porque es mi rosa, en fin.", "zh": "“别了。", "t": [26062, 27712]}]}, {"id": "ch21p45", "audio": true, "sents": [{"es": "Y volvió con el zorro.", "zh": "“别了。", "t": [100, 1274]}]}, {"id": "ch21p46", "audio": true, "sents": [{"es": "-Adiós -le dijo.", "zh": "”他说…… “别了，”狐狸说，“这就是我的秘密，它很简单：用心去看才能看清楚，用眼睛是看不见本质的东西的。", "t": [100, 1163]}]}, {"id": "ch21p47", "audio": true, "sents": [{"es": "-Adiós -dijo el zorro-.", "zh": "”他说…… “别了，”狐狸说，“这就是我的秘密，它很简单：用心去看才能看清楚，用眼睛是看不见本质的东西的。", "t": [100, 2450]}, {"es": "He aquí mi secreto, que no puede ser más simple: sólo con el corazón se puede ver bien; lo esencial es invisible para los ojos.", "zh": "” “用眼睛是看不见本质的东西的。", "t": [2450, 9500]}]}, {"id": "ch21p48", "audio": true, "sents": [{"es": "-Lo esencial es invisible para los ojos -repitió el principito para acordarse.", "zh": "”小王子重复念叨这句话，为了把它牢牢记住。", "t": [100, 4325]}]}, {"id": "ch21p49", "audio": true, "sents": [{"es": "-Lo que hace más importante a tu rosa, es el tiempo que tú has perdido con ella.", "zh": "“你为你的玫瑰失去的时间，使你的玫瑰变得重要了。", "t": [100, 4112]}]}, {"id": "ch21p50", "audio": true, "sents": [{"es": "-Es el tiempo que yo he perdido con ella…", "zh": "” “我为我的玫瑰失去的时间，使我的玫瑰……”小王子说道，为了把它记住。", "t": [100, 2350]}, {"es": "-repitió el principito para recordarlo.", "zh": "” “我为我的玫瑰失去的时间，使我的玫瑰……”小王子说道，为了把它记住。", "t": [2350, 4387]}]}, {"id": "ch21p51", "audio": true, "sents": [{"es": "-Los hombres han olvidado esta verdad -dijo el zorro-, pero tú no debes olvidarla.", "zh": "“人忘记了这条真理，”狐狸说，“但你不该忘。", "t": [100, 5025]}, {"es": "Eres responsable para siempre de lo que has domesticado.", "zh": "你应该永远对你驯养的对象负责，你要对你的玫瑰负责……” “我要对我的玫瑰负责……”小王子反复念叨狐狸的教诲，为了牢牢记住它。", "t": [5025, 8775]}, {"es": "Tú eres responsable de tu rosa…", "zh": "你应该永远对你驯养的对象负责，你要对你的玫瑰负责……” “我要对我的玫瑰负责……”小王子反复念叨狐狸的教诲，为了牢牢记住它。", "t": [8775, 10550]}]}, {"id": "ch21p52", "audio": true, "sents": [{"es": "-Yo soy responsable de mi rosa…", "zh": "你应该永远对你驯养的对象负责，你要对你的玫瑰负责……” “我要对我的玫瑰负责……”小王子反复念叨狐狸的教诲，为了牢牢记住它。", "t": [100, 2188]}, {"es": "-repitió el principito a fin de recordarlo", "zh": "你应该永远对你驯养的对象负责，你要对你的玫瑰负责……” “我要对我的玫瑰负责……”小王子反复念叨狐狸的教诲，为了牢牢记住它。", "t": [2188, 4337]}]}]}, {"id": "ch22", "title_es": "Capítulo 22", "title_zh": "第 22 章", "paras": [{"id": "ch22p00", "audio": true, "sents": [{"es": "-¡Buenos días!", "zh": "“你好。", "t": [100, 1950]}, {"es": "-dijo el principito.", "zh": "”小王子说。", "t": [1950, 4025]}, {"es": "-¡Buenos días!", "zh": "”扳道工说。", "t": [4025, 5875]}, {"es": "-respondió el guardavías.", "zh": "“你在这儿干什么？", "t": [5875, 8338]}, {"es": "-¿Qué haces aquí?", "zh": "” “我给旅客们分组。", "t": [8338, 10075]}, {"es": "-le preguntó el principito.", "zh": "一千人为一批。", "t": [10075, 11474]}]}, {"id": "ch22p01", "audio": true, "sents": [{"es": "-Formo con los viajeros paquetes de mil y despacho los trenes que los llevan, ya a la derecha, ya a la izquierda.", "zh": "“载乘客的火车也由我调度，它们有时开往左方，有时开往右方。", "t": [100, 5926]}]}, {"id": "ch22p02", "audio": true, "sents": [{"es": "Y un tren rápido iluminado, rugiendo como el trueno, hizo temblar la caseta del guardavías.", "zh": "” 一列灯火通明的火车风驰电掣般奔来，轰隆隆的响声震得调度室抖动摇晃。", "t": [100, 5312]}]}, {"id": "ch22p03", "audio": true, "sents": [{"es": "-Tienen mucha prisa -dijo el principito-.", "zh": "”小王子说。", "t": [100, 3425]}, {"es": "¿Qué buscan?", "zh": "“他们寻找什么？", "t": [3425, 4062]}]}, {"id": "ch22p04", "audio": true, "sents": [{"es": "-Ni siquiera el conductor de la locomotora lo sabe -dijo el guardavías.", "zh": "” “坐在火车头上的人也不知道他们要寻找什么。", "t": [100, 3788]}]}, {"id": "ch22p05", "audio": true, "sents": [{"es": "Un segundo rápido iluminado rugió en sentido inverso.", "zh": "第二列灯火通明的火车轰隆隆地，从相反的方向奔驰而来。", "t": [100, 4088]}, {"es": "-¿Ya vuelve?", "zh": "“他们已经回来了？", "t": [4088, 5650]}, {"es": "-preguntó el principito.", "zh": "“他们已经回来了？", "t": [5650, 6850]}]}, {"id": "ch22p06", "audio": true, "sents": [{"es": "-No son los mismos -contestó el guardvías-.", "zh": "”小王子问…… “这列车坐的不是刚才那些人。", "t": [100, 3438]}, {"es": "Es un cambio.", "zh": "”扳道工说。", "t": [3438, 5212]}, {"es": "-¿No se sentían contentos donde estaban?", "zh": "“这是对开的火车。", "t": [5212, 7437]}]}, {"id": "ch22p07", "audio": true, "sents": [{"es": "-Nunca se siente uno contento donde está -respondió el guardavías.", "zh": "” “他们对他们的居住地不满意？", "t": [100, 3975]}]}, {"id": "ch22p08", "audio": true, "sents": [{"es": "Y rugió el trueno de un tercer rápido iluminado.", "zh": "”扳道工说。", "t": [100, 3675]}, {"es": "-¿Van persiguiendo a los primeros viajeros?", "zh": "第三列灯火通明的火车也轰隆隆地响起来了。", "t": [3675, 6800]}, {"es": "-preguntó el principito.", "zh": "“他们在追赶第一批旅客吗？", "t": [6800, 8000]}]}, {"id": "ch22p09", "audio": true, "sents": [{"es": "-No persiguen absolutamente nada -le dijo el guardavías-; duermen o bostezan allí dentro.", "zh": "“他们从不追赶人，”扳道工说，“他们在车厢里睡大觉或打哈欠，只有孩子们才把鼻子贴在玻璃窗上看外面的世界。", "t": [100, 5812]}, {"es": "Unicamente los niños aplastan su nariz contra los vidrios.", "zh": "“他们从不追赶人，”扳道工说，“他们在车厢里睡大觉或打哈欠，只有孩子们才把鼻子贴在玻璃窗上看外面的世界。", "t": [5812, 9050]}]}, {"id": "ch22p10", "audio": true, "sents": [{"es": "-Unicamente los niños saben lo que buscan -dijo el principito.", "zh": "” “只有孩子才知道他们要寻觅什么。", "t": [100, 4288]}, {"es": "Pierden el tiempo con una muñeca de trapo que viene a ser lo más importante para ellos y si se la quitan, lloran…", "zh": "“他们花不少时间与布娃娃玩，布娃娃变得很重要，如果有人抢走他们的布娃娃，他们就哭鼻子……” “他们是有运气的人……”", "t": [4288, 10038]}, {"es": "-¡Qué suerte tienen!", "zh": "“他们花不少时间与布娃娃玩，布娃娃变得很重要，如果有人抢走他们的布娃娃，他们就哭鼻子……” “他们是有运气的人……”", "t": [10038, 11875]}, {"es": "-dijo el guardavías.", "zh": "“他们花不少时间与布娃娃玩，布娃娃变得很重要，如果有人抢走他们的布娃娃，他们就哭鼻子……” “他们是有运气的人……”", "t": [11875, 13000]}]}]}, {"id": "ch23", "title_es": "Capítulo 23", "title_zh": "第 23 章", "paras": [{"id": "ch23p00", "audio": true, "sents": [{"es": "-¡Buenos días!", "zh": "“你好。", "t": [100, 1950]}, {"es": "-dijo el principito.", "zh": "”小王子说。", "t": [1950, 4025]}, {"es": "-¡Buenos días!", "zh": "“你好。", "t": [4025, 5875]}, {"es": "-respondió el comerciante.", "zh": "”商人说。", "t": [5875, 7287]}]}, {"id": "ch23p01", "audio": true, "sents": [{"es": "Era un comerciante de píldoras perfeccionadas que quitan la sed.", "zh": "一个星期吃一颗这样的药丸，就不再需要喝水了。", "t": [100, 4200]}, {"es": "Se toma una por semana y ya no se sienten ganas de beber.", "zh": "“为什么你卖这种药？", "t": [4200, 8112]}, {"es": "-¿Por qué vendes eso?", "zh": "”小王子问。", "t": [8112, 10138]}, {"es": "-preguntó el principito.", "zh": "”小王子问。", "t": [10138, 11337]}]}, {"id": "ch23p02", "audio": true, "sents": [{"es": "-Porque con esto se economiza mucho tiempo.", "zh": "“为了节省更多的时间，”商人说，“专家们计算过，每个星期能节省五十三分钟。", "t": [100, 3275]}, {"es": "Según el cálculo hecho por los expertos, se ahorran cincuenta y tres minutos por semana.", "zh": "” “节省的这五十三分钟，有什么用途？", "t": [3275, 8850]}, {"es": "-¿Y qué se hace con esos cincuenta y tres minutos?", "zh": "” “节省的这五十三分钟，有什么用途？", "t": [8850, 11250]}]}, {"id": "ch23p03", "audio": true, "sents": [{"es": "-Lo que cada uno quiere…", "zh": "” “人可以干自己愿意干的事……” 小王子想：“要是我节省下这五十三分钟，我就要悠闲自在地朝一泓泉水走去……”", "t": [100, 1313]}, {"es": "\"", "zh": "” “人可以干自己愿意干的事……” 小王子想：“要是我节省下这五十三分钟，我就要悠闲自在地朝一泓泉水走去……”", "t": [1313, 1813]}]}, {"id": "ch23p04", "audio": true, "sents": [{"es": "\"Si yo dispusiera de cincuenta y tres minutos -pensó el principito- caminaría suavemente hacia una fuente…\"", "zh": "” “人可以干自己愿意干的事……” 小王子想：“要是我节省下这五十三分钟，我就要悠闲自在地朝一泓泉水走去……”", "t": [100, 5637]}]}]}, {"id": "ch24", "title_es": "Capítulo 24", "title_zh": "第 24 章", "paras": [{"id": "ch24p00", "audio": true, "sents": [{"es": "Era el octavo día de mi avería en el desierto y había escuchado la historia del comerciante bebiendo la última gota de mi provisión de agua.", "zh": "我的飞机在沙漠出故障的第八天，我听到了商人的故事，此时我储存的水已喝完了，一滴不剩。", "t": [100, 7900]}, {"es": "-¡Ah -le dije al principito-, son muy bonitos tus cuentos, pero yo no he reparado mi avión, no tengo nada para beber y sería muy feliz si pudiera irme muy tranquilo en busca de una fuente!", "zh": "你的这些回忆挺美好的，但我还没修好我的飞机，我的水也喝完了，如果我能悠闲自在地向一泓泉水走过去，我也会很幸福快活的！", "t": [7900, 17250]}]}, {"id": "ch24p01", "audio": true, "sents": [{"es": "-Mi amigo el zorro…, me dijo…", "zh": "” “我的朋友狐狸告诉我……” “我的小人儿，别再说狐狸的事了！", "t": [100, 1675]}]}, {"id": "ch24p02", "audio": true, "sents": [{"es": "-No se trata ahora del zorro, muchachito…", "zh": "” “我的朋友狐狸告诉我……” “我的小人儿，别再说狐狸的事了！", "t": [100, 2475]}, {"es": "-¿Por qué?", "zh": "” “为什么？", "t": [2475, 2812]}]}, {"id": "ch24p03", "audio": true, "sents": [{"es": "-Porque nos vamos a morir de sed…", "zh": "” “为什么？", "t": [100, 1663]}]}, {"id": "ch24p04", "audio": true, "sents": [{"es": "No comprendió mi razonamiento y replicó:", "zh": "” “因为我快渴死了……” 他听不懂我说的理由。", "t": [100, 2337]}]}, {"id": "ch24p05", "audio": true, "sents": [{"es": "-Es bueno haber tenido un amigo, aún si vamos a morir.", "zh": "” “因为我快渴死了……” 他听不懂我说的理由。", "t": [100, 4062]}, {"es": "Yo estoy muy contento de haber tenido un amigo zorro.", "zh": "他说道： “有个朋友真好，哪怕命在旦夕。", "t": [4062, 6850]}]}, {"id": "ch24p06", "audio": true, "sents": [{"es": "\"Es incapaz de medir el peligro -me dije - Nunca tiene hambre ni sed y un poco de sol le basta…\"", "zh": "我很满意狐狸做了我的朋友……” 我想：“他不知道危险的可怕，他从未尝过饥渴的滋味。", "t": [100, 5000]}]}, {"id": "ch24p07", "audio": true, "sents": [{"es": "El principito me miró y respondió a mi pensamiento:", "zh": "他只要一点儿阳光就满足了……” 他看着我，似乎猜中了我的念头： “我也渴……我们去找一口井吧……” 我做了个无法可想的手势。", "t": [100, 2788]}]}, {"id": "ch24p08", "audio": true, "sents": [{"es": "-Tengo sed también…", "zh": "他只要一点儿阳光就满足了……” 他看着我，似乎猜中了我的念头： “我也渴……我们去找一口井吧……” 我做了个无法可想的手势。", "t": [100, 1300]}, {"es": "vamos a buscar un pozo…", "zh": "他只要一点儿阳光就满足了……” 他看着我，似乎猜中了我的念头： “我也渴……我们去找一口井吧……” 我做了个无法可想的手势。", "t": [1300, 2588]}]}, {"id": "ch24p09", "audio": true, "sents": [{"es": "Tuve un gesto de cansancio; es absurdo buscar un pozo, al azar, en la inmensidad del desierto.", "zh": "他只要一点儿阳光就满足了……” 他看着我，似乎猜中了我的念头： “我也渴……我们去找一口井吧……” 我做了个无法可想的手势。", "t": [100, 6100]}, {"es": "Sin embargo, nos pusimos en marcha.", "zh": "在一望无际的沙漠中寻一口井，这不是太荒唐了吗？", "t": [6100, 7987]}]}, {"id": "ch24p10", "audio": true, "sents": [{"es": "Después de dos horas de caminar en silencio, cayó la noche y las estrellas comenzaron a brillar.", "zh": "但我们还是出发去寻找了。", "t": [100, 5875]}, {"es": "Yo las veía como en sueño, pues a causa de la sed tenía un poco de fiebre.", "zh": "夜幕降临，天上现出星星。", "t": [5875, 10550]}, {"es": "Las palabras del principito danzaban en mi mente.", "zh": "由于干渴，我在发烧，看见星星，还以为自己在梦中呢。", "t": [10550, 14038]}, {"es": "-¿Tienes sed, tú también?", "zh": "小王子说的话也似乎在我的脑海中跳跃。", "t": [14038, 16275]}, {"es": "-le pregunté.", "zh": "小王子说的话也似乎在我的脑海中跳跃。", "t": [16275, 18038]}, {"es": "Pero no respondió a mi pregunta, diciéndome simplemente:", "zh": "“你也口渴了吗？", "t": [18038, 21175]}]}, {"id": "ch24p11", "audio": true, "sents": [{"es": "-El agua puede ser buena también para el corazón…", "zh": "”我问他。", "t": [100, 2412]}]}, {"id": "ch24p12", "audio": true, "sents": [{"es": "No comprendí sus palabras, pero me callé; sabía muy bien que no había que interrogarlo.", "zh": "他不回答我的问题，只简单地对我说： “水对心也有好处……” 我听不懂他的话，但我不做声……我知道不应该问他。", "t": [100, 4687]}]}, {"id": "ch24p13", "audio": true, "sents": [{"es": "El principito estaba cansado y se sentó; yo me senté a su lado y después de un silencio me dijo:", "zh": "我靠着他坐下。", "t": [100, 5075]}]}, {"id": "ch24p14", "audio": true, "sents": [{"es": "-Las estrellas son hermosas, por una flor que no se ve…", "zh": "沉默了一会，他又说： “星星美丽，因为里面有一朵看不见的花。", "t": [100, 2975]}]}, {"id": "ch24p15", "audio": true, "sents": [{"es": "Respondí \"seguramente\" y miré sin hablar los pliegues que la arena formaba bajo la luna.", "zh": "”然后我不做声，看着月光下的起伏的沙丘。", "t": [100, 4512]}]}, {"id": "ch24p16", "audio": true, "sents": [{"es": "-El desierto es bello -añadió el principito.", "zh": "“沙漠真美。", "t": [100, 2575]}]}, {"id": "ch24p17", "audio": true, "sents": [{"es": "Era verdad; siempre me ha gustado el desierto.", "zh": "我素来喜爱沙漠。", "t": [100, 3575]}, {"es": "Puede uno sentarse en una duna, nada se ve, nada se oye y sin embargo, algo resplandece en el silencio…", "zh": "我们无所见，我们无所闻。", "t": [3575, 9450]}]}, {"id": "ch24p18", "audio": true, "sents": [{"es": "-Lo que más embellece al desierto -dijo el principito- es el pozo que oculta en algún sitio…", "zh": "”小王子说。", "t": [100, 5012]}]}, {"id": "ch24p19", "audio": true, "sents": [{"es": "Me quedé sorprendido al comprender súbitamente ese misterioso resplandor de la arena.", "zh": "我吃了一惊，因为我突然明白，沙漠中那神秘的闪闪发亮的东西是什么了。", "t": [100, 5500]}, {"es": "Cuando yo era niño vivía en una casa antigua en la que, según la leyenda, había un tesoro escondido.", "zh": "我还是一个小男孩的时候，住在一幢古老大屋里。", "t": [5500, 11525]}, {"es": "Sin duda que nadie supo jamás descubrirlo y quizás nadie lo buscó, pero parecía toda encantada por ese tesoro.", "zh": "也许甚至没人去找它。", "t": [11525, 18488]}, {"es": "Mi casa ocultaba un secreto en el fondo de su corazón…", "zh": "但它像给这幢屋子施了魔法，让它凭空增添了吸引力。", "t": [18488, 21350]}]}, {"id": "ch24p20", "audio": true, "sents": [{"es": "-Sí -le dije al principito- ya se trate de la casa, de las estrellas o del desierto, lo que les embellece es invisible.", "zh": "房里埋藏着秘密…… “你说得对，”我对小王子说，“房子也好，星星、沙漠也好，美化它们的东西是肉眼看不见的！", "t": [100, 6576]}]}, {"id": "ch24p21", "audio": true, "sents": [{"es": "-Me gusta -dijo el principito- que estés de acuerdo con mi zorro.", "zh": "” “我很欣慰，”他说，“你同意狐狸的看法。", "t": [100, 3162]}]}, {"id": "ch24p22", "audio": true, "sents": [{"es": "Como el principito se dormía, lo tomé en mis brazos y me puse nuevamente en camino.", "zh": "我把他抱在怀里，继续走我们的路。", "t": [100, 5475]}, {"es": "Me sentía emocionado llevando aquel frágil tesoro, y me parecía que nada más frágil había sobre la Tierra.", "zh": "我觉得我抱着一件脆弱的宝物。", "t": [5475, 11962]}, {"es": "Miraba a la luz de la luna aquella frente pálida, aquellos ojos cerrados, los cabellos agitados por el viento y me decía: \"lo que veo es sólo la corteza; lo más importante es invisible…", "zh": "借着银色的月光，我细细看他苍白的前额、闭着的双目、随风抖动的绺绺秀发。", "t": [11962, 22212]}, {"es": "\"", "zh": "我心想：“我看见的只是一具躯壳，最重要的东西是看不见的……” 他半张的嘴唇上泛出浅浅的微笑。", "t": [22212, 22712]}]}, {"id": "ch24p23", "audio": true, "sents": [{"es": "Como sus labios entreabiertos esbozaron una sonrisa, me dije: \"Lo que más me emociona de este principito dormido es su fidelidad a una flor, es la imagen de la rosa que resplandece en él como la llama de una lámpara, incluso cuando duerme…", "zh": "我又想：“这位睡着了的小王子打动了我，而打动了我的是他对花的忠贞。", "t": [100, 13400]}, {"es": "\" Y lo sentí más frágil aún.", "zh": "玫瑰花的倩影如同灯焰，在他心里闪闪发亮，即使是在梦乡……” 我把他想像得更脆弱了。", "t": [13400, 15875]}, {"es": "Pensaba que a las lámparas hay que protegerlas: una racha de viento puede apagarlas…", "zh": "灯是需要我们小心保护的，一股风就会把它吹灭……我就这样走着，曙光初露时我看见了那口井。", "t": [15875, 20362]}]}, {"id": "ch24p24", "audio": true, "sents": [{"es": "Continué caminando y al rayar el alba descubrí el pozo.", "zh": "灯是需要我们小心保护的，一股风就会把它吹灭……我就这样走着，曙光初露时我看见了那口井。", "t": [100, 2975]}]}]}, {"id": "ch25", "title_es": "Capítulo 25", "title_zh": "第 25 章", "paras": [{"id": "ch25p00", "audio": true, "sents": [{"es": "-Los hombres -dijo el principito- se meten en los rápidos pero no saben dónde van ni lo que quieren…", "zh": "“人挤在快车的车厢里，”小王子说，“却不知道他们要寻找什么。", "t": [100, 5975]}, {"es": "Entonces se agitan y dan vueltas…", "zh": "他们焦躁不安，团团乱转……” 他又说： “这又何苦呢……” 我们找到的井不像撒哈拉沙漠的井。", "t": [5975, 7850]}]}, {"id": "ch25p01", "audio": true, "sents": [{"es": "Y añadió: -¡No vale la pena!…", "zh": "他们焦躁不安，团团乱转……” 他又说： “这又何苦呢……” 我们找到的井不像撒哈拉沙漠的井。", "t": [100, 1588]}]}, {"id": "ch25p02", "audio": true, "sents": [{"es": "El pozo que habíamos encontrado no se parecía en nada a los pozos saharianos.", "zh": "他们焦躁不安，团团乱转……” 他又说： “这又何苦呢……” 我们找到的井不像撒哈拉沙漠的井。", "t": [100, 5088]}, {"es": "Estos pozos son simples agujeros que se abren en la arena.", "zh": "撒哈拉沙漠的井是在沙里挖个洞，而我们找到的这口井与村子里的井一样，可是这儿没有一个村子。", "t": [5088, 9188]}, {"es": "El que teníamos ante nosotros parecía el pozo de un pueblo; pero por allí no había ningún pueblo y me parecía estar soñando.", "zh": "我以为我正在做梦。", "t": [9188, 15388]}]}, {"id": "ch25p03", "audio": true, "sents": [{"es": "-¡Es extraño!", "zh": "“这就奇了，”我对小王子说，“这井一切齐备：辘轳，水桶，绳子……” 他笑了，抓住绳子，转动辘轳。", "t": [100, 1862]}, {"es": "-le dije al principito-.", "zh": "“这就奇了，”我对小王子说，“这井一切齐备：辘轳，水桶，绳子……” 他笑了，抓住绳子，转动辘轳。", "t": [1862, 4062]}, {"es": "Todo está a punto: la roldana, el balde y la cuerda…", "zh": "“这就奇了，”我对小王子说，“这井一切齐备：辘轳，水桶，绳子……” 他笑了，抓住绳子，转动辘轳。", "t": [4062, 7062]}]}, {"id": "ch25p04", "audio": true, "sents": [{"es": "Se rió y tocó la cuerda; hizo mover la roldana.", "zh": "辘轳吱吱呀呀地叫唤，活像一只老风信鸡在风长睡时的叫唤。", "t": [100, 3800]}, {"es": "Y la roldana gimió como una vieja veleta cuando el viento ha dormido mucho.", "zh": "“你听，”小王子说，“我们唤醒了这口井。", "t": [3800, 8425]}, {"es": "-¿Oyes?", "zh": "“你听，”小王子说，“我们唤醒了这口井。", "t": [8425, 9888]}, {"es": "-dijo el principito-.", "zh": "它在唱歌呢……” 我不忍心看他劳力费神。", "t": [9888, 11962]}, {"es": "Hemos despertado al pozo y canta.", "zh": "它在唱歌呢……” 我不忍心看他劳力费神。", "t": [11962, 13800]}]}, {"id": "ch25p05", "audio": true, "sents": [{"es": "No quería que el principito hiciera el menor esfuerzo y le dije:", "zh": "“让我来干吧，”我对他说，“你干这活太重了。", "t": [100, 3163]}]}, {"id": "ch25p06", "audio": true, "sents": [{"es": "-Déjame a mí, es demasiado pesado para ti.", "zh": "” 我轻轻把水桶提到井口，垂直放进井内。", "t": [100, 2500]}]}, {"id": "ch25p07", "audio": true, "sents": [{"es": "Lentamente subí el cubo hasta el brocal donde lo dejé bien seguro.", "zh": "倾听着辘轳的歌声，还看见在荡漾的井水中摇动的太阳。", "t": [100, 3475]}]}, {"id": "ch25p08", "audio": true, "sents": [{"es": "En mis oídos sonaba aún el canto de la roldana y veía temblar al sol en el agua agitada.", "zh": "“我渴望的就是这样的水，”小王子说，“让我喝上几口……”我明白他要寻找什么了。", "t": [100, 4775]}]}, {"id": "ch25p09", "audio": true, "sents": [{"es": "-Tengo sed de esta agua -dijo el principito-, dame de beber…", "zh": "“我渴望的就是这样的水，”小王子说，“让我喝上几口……”我明白他要寻找什么了。", "t": [100, 4288]}, {"es": "¡Comprendí entonces lo que él había buscado!", "zh": "他闭着双目喝水。", "t": [4288, 6563]}]}, {"id": "ch25p10", "audio": true, "sents": [{"es": "Levanté el balde hasta sus labios y el principito bebió con los ojos cerrados.", "zh": "这水不仅是饮料，它还是别的东西。", "t": [100, 5038]}, {"es": "Todo era bello como una fiesta.", "zh": "它是经过星光下的跋涉，在辘轳的歌声中和在我双臂的努力下诞生的。", "t": [5038, 6750]}]}, {"id": "ch25p11", "audio": true, "sents": [{"es": "Aquella agua era algo más que un alimento.", "zh": "它是经过星光下的跋涉，在辘轳的歌声中和在我双臂的努力下诞生的。", "t": [100, 3362]}, {"es": "Había nacido del caminar bajo las estrellas, del canto de la roldana, del esfuerzo de mis brazos.", "zh": "它像礼物一样愉悦心灵。", "t": [3362, 9462]}, {"es": "Era como un regalo para el corazón.", "zh": "我还是小男孩的时候，圣诞树上挂的灯、子夜弥撒的音乐、甜蜜的微笑，是我收到的圣诞礼物的光芒。", "t": [9462, 12312]}, {"es": "Cuando yo era niño, las luces del árbol de Navidad, la música de la misa de medianoche, la dulzura de las sonrisas, daban su resplandor a mi regalo de Navidad.", "zh": "“你们这儿的人在一个园里种植五千株玫瑰……但他们却找不到他们寻觅的东西……” “他们没找到。", "t": [12312, 21137]}]}, {"id": "ch25p12", "audio": true, "sents": [{"es": "-Los hombres de tu tierra -dijo el principito- cultivan cinco mil rosas en un jardín y no encuentran lo que buscan.", "zh": "”我说…… “然而他们寻找的东西可以在一朵玫瑰或一点点水里找到的……” “不错。", "t": [100, 6125]}]}, {"id": "ch25p13", "audio": true, "sents": [{"es": "-No lo encuentran nunca -le respondí.", "zh": "”我回答说。", "t": [100, 3088]}, {"es": "-Y sin embargo, lo que buscan podrían encontrarlo en una sola rosa o en un poco de agua…", "zh": "小王子又说： “然而肉眼是看不见的，要用心灵去寻找。", "t": [3088, 7450]}]}, {"id": "ch25p14", "audio": true, "sents": [{"es": "-Sin duda, respondí.", "zh": "” 我喝了水，呼吸畅通了。", "t": [100, 2400]}, {"es": "Y el principito añadió:", "zh": "天亮时分，沙子颜色如蜜。", "t": [2400, 3688]}]}, {"id": "ch25p15", "audio": true, "sents": [{"es": "-Pero los ojos son ciegos.", "zh": "我也喜欢蜜般的颜色。", "t": [100, 2500]}, {"es": "Hay que buscar con el corazón.", "zh": "但为什么我的心里总有点不快乐呢？", "t": [2500, 4050]}]}, {"id": "ch25p16", "audio": true, "sents": [{"es": "Yo había bebido y me encontraba bien.", "zh": "但为什么我的心里总有点不快乐呢？", "t": [100, 2988]}, {"es": "La arena, al alba, era color de miel, del que gozaba hasta sentirme dichoso.", "zh": "”小王子轻声对我说，他又靠近我坐着。", "t": [2988, 8012]}, {"es": "¿Por qué había de sentirme triste?", "zh": "“什么诺言？", "t": [8012, 9737]}]}, {"id": "ch25p17", "audio": true, "sents": [{"es": "-Es necesario que cumplas tu promesa -dijo dulcemente el principito que nuevamente se había sentado junto a mi.", "zh": "” “你知道的呀……给我的绵羊画一个口罩，我要对我的花儿负责呀！", "t": [100, 6712]}, {"es": "-¿Qué promesa?", "zh": "” 我从口袋里掏出画稿。", "t": [6712, 7362]}]}, {"id": "ch25p18", "audio": true, "sents": [{"es": "-Ya sabes…", "zh": "小王子看后，笑着对我说： “你画的猴面包树有点像卷心菜……” “呀！", "t": [100, 788]}, {"es": "el bozal para mi cordero…", "zh": "小王子看后，笑着对我说： “你画的猴面包树有点像卷心菜……” “呀！", "t": [788, 2350]}, {"es": "soy responsable de mi flor.", "zh": "小王子看后，笑着对我说： “你画的猴面包树有点像卷心菜……” “呀！", "t": [2350, 3800]}]}, {"id": "ch25p19", "audio": true, "sents": [{"es": "Saqué del bolsillo mis esbozos de dibujo.", "zh": "” 我还为我画的猴面包树自鸣得意呢！", "t": [100, 3288]}, {"es": "El principito los miró y dijo riendo:", "zh": "” 我还为我画的猴面包树自鸣得意呢！", "t": [3288, 5374]}]}, {"id": "ch25p20", "audio": true, "sents": [{"es": "-Tus baobabs parecen repollos…", "zh": "“你画的狐狸……它的耳朵……有点像角……太长了！", "t": [100, 2038]}, {"es": "-¡Oh!", "zh": "“你画的狐狸……它的耳朵……有点像角……太长了！", "t": [2038, 3100]}, {"es": "¡Y yo que estaba tan orgulloso de mis baobabs!", "zh": "” 他还在笑。", "t": [3100, 5362]}]}, {"id": "ch25p21", "audio": true, "sents": [{"es": "-Tu zorro tíene orejas que parecen cuernos; son demasiado largas.", "zh": "“你不公平，小人儿。", "t": [100, 3775]}]}, {"id": "ch25p22", "audio": true, "sents": [{"es": "Y volvió a reír.", "zh": "我并不会画画，只会画打开了肚子的蟒蛇和没打开肚子的蟒蛇。", "t": [100, 1075]}]}, {"id": "ch25p23", "audio": true, "sents": [{"es": "-Eres injusto, muchachito; yo no sabía dibujar más que boas cerradas y boas abiertas.", "zh": "” “啊！", "t": [100, 6062]}, {"es": "-¡Oh, todo se arreglará!", "zh": "”他说。", "t": [6062, 8312]}, {"es": "-dijo el principito-.", "zh": "”他说。", "t": [8312, 10388]}, {"es": "Los niños entienden.", "zh": "我用铅笔画了一个口罩，把它交给他的时候，我的心揪得紧紧的： “你已有了我不知道的计划吧……” 但他避而不答。", "t": [10388, 11650]}]}, {"id": "ch25p24", "audio": true, "sents": [{"es": "Bosquejé, pues, un bozal y se lo alargué con el corazón oprimido:", "zh": "我用铅笔画了一个口罩，把它交给他的时候，我的心揪得紧紧的： “你已有了我不知道的计划吧……” 但他避而不答。", "t": [100, 3474]}]}, {"id": "ch25p25", "audio": true, "sents": [{"es": "-Tú tienes proyectos que yo ignoro…", "zh": "我用铅笔画了一个口罩，把它交给他的时候，我的心揪得紧紧的： “你已有了我不知道的计划吧……” 但他避而不答。", "t": [100, 1962]}]}, {"id": "ch25p26", "audio": true, "sents": [{"es": "Pero no me respondió.", "zh": "他只对我说： “你知道，我落到地球上……明天已是一周年了……” 然后，沉默片刻，他又说： “当时我就落在附近……” 他的脸红了。", "t": [100, 2188]}, {"es": "-¿Sabes?", "zh": "他只对我说： “你知道，我落到地球上……明天已是一周年了……” 然后，沉默片刻，他又说： “当时我就落在附近……” 他的脸红了。", "t": [2188, 3738]}, {"es": "-me dijo-.", "zh": "他只对我说： “你知道，我落到地球上……明天已是一周年了……” 然后，沉默片刻，他又说： “当时我就落在附近……” 他的脸红了。", "t": [3738, 5262]}, {"es": "Mañana hace un año de mi caída en la Tierra…", "zh": "他只对我说： “你知道，我落到地球上……明天已是一周年了……” 然后，沉默片刻，他又说： “当时我就落在附近……” 他的脸红了。", "t": [5262, 7612]}]}, {"id": "ch25p27", "audio": true, "sents": [{"es": "Y después de un silencio, añadió:", "zh": "他只对我说： “你知道，我落到地球上……明天已是一周年了……” 然后，沉默片刻，他又说： “当时我就落在附近……” 他的脸红了。", "t": [100, 2050]}]}, {"id": "ch25p28", "audio": true, "sents": [{"es": "-Caí muy cerca de aquí…", "zh": "他只对我说： “你知道，我落到地球上……明天已是一周年了……” 然后，沉默片刻，他又说： “当时我就落在附近……” 他的脸红了。", "t": [100, 1313]}]}, {"id": "ch25p29", "audio": true, "sents": [{"es": "El principito se sonrojó y nuevamente, sin comprender por qué, experimenté una extraña tristeza.", "zh": "不知何故，我有说不出来的惆怅悲哀。", "t": [100, 5012]}]}, {"id": "ch25p30", "audio": true, "sents": [{"es": "Sin embargo, se me ocurrió preguntar:", "zh": "不知何故，我有说不出来的惆怅悲哀。", "t": [100, 2063]}]}, {"id": "ch25p31", "audio": true, "sents": [{"es": "-Entonces no te encontré por azar hace ocho días, cuando paseabas por estos lugares, a mil millas de distancia del lugar habitado más próximo.", "zh": "我提出了一个问题： “这么说，一个星期之前，认识你的那天早上，你不是偶尔一人来到这远离人烟的沙漠的？", "t": [100, 8588]}, {"es": "¿Es que volvías al punto de tu caída?", "zh": "” 小王子的脸又红了。", "t": [8588, 10500]}]}, {"id": "ch25p32", "audio": true, "sents": [{"es": "El principito enrojeció nuevamente.", "zh": "我犹豫着又问： “也许是为了纪念降落周年？", "t": [100, 2025]}]}, {"id": "ch25p33", "audio": true, "sents": [{"es": "Y añadí vacilante.", "zh": "……” 小王子的脸再次红了。", "t": [100, 2162]}, {"es": "-¿Quizás por el aniversario?", "zh": "……” 小王子的脸再次红了。", "t": [2162, 3563]}]}, {"id": "ch25p34", "audio": true, "sents": [{"es": "El principito se ruborizó una vez más.", "zh": "他从不回答我提的问题。", "t": [100, 3250]}, {"es": "Aunque nunca respondía a las preguntas, su rubor signifícaba una respuesta afirmativa.", "zh": "但一个人脸红，就意味着默认，意味着做了“是的”的回答，对吧？", "t": [3250, 8962]}, {"es": "-¡Ah!", "zh": "“啊！", "t": [8962, 10225]}, {"es": "-le dije- tengo miedo.", "zh": "“啊！", "t": [10225, 11476]}]}, {"id": "ch25p35", "audio": true, "sents": [{"es": "Pero él me respondió:", "zh": "”我对他说，“我怕……” 他却对我说： “现在你该干活了。", "t": [100, 1137]}]}, {"id": "ch25p36", "audio": true, "sents": [{"es": "-Tú debes trabajar ahora; vuelve, pues, junto a tu máquina, que yo te espero aquí.", "zh": "你该到你的机器旁忙活儿了。", "t": [100, 5762]}, {"es": "Vuelve mañana por la tarde.", "zh": "我在这儿等你，明天晚上再来……” 但我不放心。", "t": [5762, 7188]}]}, {"id": "ch25p37", "audio": true, "sents": [{"es": "Pero yo no estaba tranquilo y me acordaba del zorro.", "zh": "我在这儿等你，明天晚上再来……” 但我不放心。", "t": [100, 3638]}, {"es": "Si se deja uno domesticar, se expone a llorar un poco…", "zh": "我想起了狐狸的事，让别人驯养，难免要掉掉眼泪……", "t": [3638, 6813]}]}]}, {"id": "ch26", "title_es": "Capítulo 26", "title_zh": "第 26 章", "paras": [{"id": "ch26p00", "audio": true, "sents": [{"es": "A1 lado del pozo había una ruina de un viejo muro de piedras.", "zh": "井旁有一堵断墙残壁。", "t": [100, 3524]}]}, {"id": "ch26p01", "audio": true, "sents": [{"es": "Cuando volví de mi trabajo al día siguiente por la tarde, vi desde lejos al principito sentado en lo alto con las piernas colgando.", "zh": "我听见他说： “你不记得了吗？", "t": [100, 7512]}, {"es": "Lo oí que hablaba.", "zh": "不完全在这里！", "t": [7512, 8488]}]}, {"id": "ch26p02", "audio": true, "sents": [{"es": "-¿No te acuerdas?", "zh": "” 无疑有另一个声音回了他的话，因为他反驳说： “没错！", "t": [100, 2012]}, {"es": "¡No es aquí con exactitud!", "zh": "” 无疑有另一个声音回了他的话，因为他反驳说： “没错！", "t": [2012, 3462]}]}, {"id": "ch26p03", "audio": true, "sents": [{"es": "Alguien le respondió sín duda, porque él replicó: -¡Sí, sí; es el día, pero no es este el lugar!", "zh": "没错！", "t": [100, 5487]}]}, {"id": "ch26p04", "audio": true, "sents": [{"es": "Proseguí mi marcha hacia el muro, pero no veía ni oía a nadie.", "zh": "就是这一天，但不是这个地方……” 我向断墙残壁走过去，我看不见也听不见有什么人在那儿。", "t": [100, 4550]}, {"es": "Y sin embargo, el principito replicó de nuevo.", "zh": "然而小王子又反驳了： “……当然，你会看到我留在沙地上的足迹，看到它是从哪儿开始的。", "t": [4550, 7812]}, {"es": "-¡Claro!", "zh": "然而小王子又反驳了： “……当然，你会看到我留在沙地上的足迹，看到它是从哪儿开始的。", "t": [7812, 9175]}, {"es": "Ya verás dónde comienza mi huella en la arena.", "zh": "然而小王子又反驳了： “……当然，你会看到我留在沙地上的足迹，看到它是从哪儿开始的。", "t": [9175, 12400]}, {"es": "No tienes más que esperarme, que allí estaré yo esta noche.", "zh": "你在那儿等我就行了。", "t": [12400, 15562]}, {"es": "¿", "zh": "今夜我会在那儿等你。", "t": [15562, 16538]}, {"es": "Yo estaba a veinte metros y continuaba sin distinguir nada.", "zh": "” 我离开墙才二十米，还是一无所见。", "t": [16538, 19663]}]}, {"id": "ch26p05", "audio": true, "sents": [{"es": "El principito, después de un silencio, dijo aún:", "zh": "小王子沉默片刻后又说： “你有毒液吗？", "t": [100, 2776]}]}, {"id": "ch26p06", "audio": true, "sents": [{"es": "Tienes un buen veneno?", "zh": "你能肯定不让我经受很久的痛苦？", "t": [100, 2188]}, {"es": "¿Estás segura de no hacerme sufrir mucho?", "zh": "你能肯定不让我经受很久的痛苦？", "t": [2188, 4363]}]}, {"id": "ch26p07", "audio": true, "sents": [{"es": "Me detuve con el corazón oprimido, siempre sin comprender.", "zh": "我仍然听不懂他的话。", "t": [100, 4288]}, {"es": "-¡Ahora vete -dijo el principito-, quiero volver a bajarme!", "zh": "”他说。", "t": [4288, 7087]}]}, {"id": "ch26p08", "audio": true, "sents": [{"es": "Dirigí la mirada hacia el pie del muro e instintivamente di un brinco.", "zh": "” 我的眼光落到墙根，我吓了一跳！", "t": [100, 4612]}, {"es": "Una serpiente de esas amarillas que matan a una persona en menos de treínta segundos, se erguía en dirección al principito.", "zh": "这种黄蛇最毒了，三十秒钟内就能要你的命。", "t": [4612, 11825]}, {"es": "Echando mano al bolsillo para sacar mi revólver, apreté el paso, pero, al ruido que hice, la serpiente se dejó deslizar suavemente por la arena como un surtidor que muere, y, sin apresurarse demasiado, se escurrió entre las piedras con un lígero ruido metálico.", "zh": "我及时赶到墙边，用双臂接住我的小人儿。", "t": [11825, 26074]}]}, {"id": "ch26p09", "audio": true, "sents": [{"es": "Llegué junto al muro a tiempo de recibir en mis brazos a mi principito, que estaba blanco como la nieve.", "zh": "” 我解下他从不离身的金围巾，用水湿湿他的太阳穴，给他喝水。", "t": [100, 6288]}, {"es": "-¿Pero qué historia es ésta?", "zh": "现在我不敢再向他提什么问题了。", "t": [6288, 8638]}, {"es": "¿De charla también con las serpientes?", "zh": "他神情凝重地看着我，双臂搂住我的脖子。", "t": [8638, 10563]}]}, {"id": "ch26p10", "audio": true, "sents": [{"es": "Le quité su eterna bufanda de oro, le humedecí las sienes y le di de beber, sin atreverme a hacerle pregunta alguna.", "zh": "我感觉到他的心的狂跳，如同中弹濒死的小鸟。", "t": [100, 7212]}, {"es": "Me miró gravemente rodeándome el cuello con sus brazos.", "zh": "他对我说：“你找到了机器的毛病，我很高兴。", "t": [7212, 11250]}, {"es": "Sentí latir su corazón, como el de un pajarillo que muere a tiros de carabina.", "zh": "你可以回家了……” “你怎么知道的？", "t": [11250, 15300]}]}, {"id": "ch26p11", "audio": true, "sents": [{"es": "-Me alegra -dijo el principito- que hayas encontrado lo que faltaba a tu máquina.", "zh": "” 我来找他，正是要告诉他：出乎我的意料，我竟修好了我的飞机。", "t": [100, 5250]}, {"es": "Así podrás volver a tu tierra…", "zh": "他不回答我的问题，却又说： “今天我也要回家了……” 然后，他神色凄伤，黯然说道： “我的家要远多了……也难回去得多……” 我感觉到发生了非比寻常的事情。", "t": [5250, 7250]}, {"es": "-¿Cómo lo sabes?", "zh": "他不回答我的问题，却又说： “今天我也要回家了……” 然后，他神色凄伤，黯然说道： “我的家要远多了……也难回去得多……” 我感觉到发生了非比寻常的事情。", "t": [7250, 8063]}]}, {"id": "ch26p12", "audio": true, "sents": [{"es": "Precisamente venía a comunicarle que, a pesar de que no lo esperaba, había logrado terminar mi trabajo.", "zh": "他不回答我的问题，却又说： “今天我也要回家了……” 然后，他神色凄伤，黯然说道： “我的家要远多了……也难回去得多……” 我感觉到发生了非比寻常的事情。", "t": [100, 5537]}]}, {"id": "ch26p13", "audio": true, "sents": [{"es": "No respondió a mi pregunta, sino que añadió:", "zh": "我把他搂进怀里，如同他是个小孩子。", "t": [100, 2400]}]}, {"id": "ch26p14", "audio": true, "sents": [{"es": "-También yo vuelvo hoy a mi planeta…", "zh": "我把他搂进怀里，如同他是个小孩子。", "t": [100, 1862]}]}, {"id": "ch26p15", "audio": true, "sents": [{"es": "Luego, con melancolía:", "zh": "我把他搂进怀里，如同他是个小孩子。", "t": [100, 1400]}]}, {"id": "ch26p16", "audio": true, "sents": [{"es": "-Es mucho más lejos…", "zh": "然而我觉得他直往深渊里坠下去，我一点也抓不住他…… 他目光严肃，落到远方。", "t": [100, 1400]}, {"es": "y más difícil…", "zh": "然而我觉得他直往深渊里坠下去，我一点也抓不住他…… 他目光严肃，落到远方。", "t": [1400, 2200]}]}, {"id": "ch26p17", "audio": true, "sents": [{"es": "Me daba cuenta de que algo extraordinario pasaba en aquellos momentos.", "zh": "然而我觉得他直往深渊里坠下去，我一点也抓不住他…… 他目光严肃，落到远方。", "t": [100, 4662]}, {"es": "Estreché al principito entre mis brazos como sí fuera un niño pequeño, y no obstante, me pareció que descendía en picada hacia un abismo sin que fuera posible hacer nada para retenerlo.", "zh": "我等了许久。", "t": [4662, 13862]}]}, {"id": "ch26p18", "audio": true, "sents": [{"es": "Su mirada, seria, estaba perdída en la lejanía.", "zh": "他温和地笑笑： “今晚我会更害怕！", "t": [100, 2725]}]}, {"id": "ch26p19", "audio": true, "sents": [{"es": "Tengo tu cordero y la caja para el cordero.", "zh": "” 我又一次体会到无可奈何的感觉。", "t": [100, 3088]}, {"es": "Y tengo tambíén el bozal.", "zh": "” 我又一次体会到无可奈何的感觉。", "t": [3088, 4550]}]}, {"id": "ch26p20", "audio": true, "sents": [{"es": "Y sonreía melancólicamente.", "zh": "我全身冰冷。", "t": [100, 1850]}]}, {"id": "ch26p21", "audio": true, "sents": [{"es": "Esperé un buen rato.", "zh": "我知道，听不见他的笑声，我会忍受不了的。", "t": [100, 2325]}, {"es": "Sentía que volvía a entrar en calor poco a poco:", "zh": "我知道，听不见他的笑声，我会忍受不了的。", "t": [2325, 4900]}]}, {"id": "ch26p22", "audio": true, "sents": [{"es": "-Has tenido miedo, muchachito…", "zh": "他的笑声对我来说，如同沙漠里的一口井。", "t": [100, 1775]}]}, {"id": "ch26p23", "audio": true, "sents": [{"es": "Lo había tenido, sin duda, pero sonrió con dulzura:", "zh": "“小人儿，我还想听到你的笑声……” 但他对我说： “今夜是我到这儿的一周年。", "t": [100, 2862]}]}, {"id": "ch26p24", "audio": true, "sents": [{"es": "-Esta noche voy a tener más miedo…", "zh": "“小人儿，我还想听到你的笑声……” 但他对我说： “今夜是我到这儿的一周年。", "t": [100, 1937]}]}, {"id": "ch26p25", "audio": true, "sents": [{"es": "Me quedé de nuevo helado por un sentimiento de algo irreparable.", "zh": "“小人儿，我还想听到你的笑声……” 但他对我说： “今夜是我到这儿的一周年。", "t": [100, 4300]}, {"es": "Comprendí que no podía soportar la idea de no volver a oír nunca más su risa.", "zh": "我的星星正好在我去年降落处的正上方……” “小人儿，蛇呀、约会呀、星星的故事，莫非都是一场噩梦？", "t": [4300, 9212]}, {"es": "Era para mí como una fuente en el desierto.", "zh": "……” 但他不回答我的问题。", "t": [9212, 11387]}]}, {"id": "ch26p26", "audio": true, "sents": [{"es": "-Muchachito, quiero oír otra vez tu risa…", "zh": "……” 但他不回答我的问题。", "t": [100, 2438]}]}, {"id": "ch26p27", "audio": true, "sents": [{"es": "Pero él me dijo:", "zh": "……” 但他不回答我的问题。", "t": [100, 850]}]}, {"id": "ch26p28", "audio": true, "sents": [{"es": "-Esta noche hará un año.", "zh": "他对我说： “最重要的东西，是肉眼看不到的……” “当然……” “花儿也是这样，如果你爱上了一朵长在一颗星星里的花儿，夜里看看星空，你会觉得甜蜜。", "t": [100, 2438]}, {"es": "Mi estrella se encontrará precisamente encima del lugar donde caí el año pasado…", "zh": "他对我说： “最重要的东西，是肉眼看不到的……” “当然……” “花儿也是这样，如果你爱上了一朵长在一颗星星里的花儿，夜里看看星空，你会觉得甜蜜。", "t": [2438, 6775]}]}, {"id": "ch26p29", "audio": true, "sents": [{"es": "-¿No es cierto -le interrumpí- que toda esta historia de serpientes, de citas y de estrellas es tan sólo una pesadilla?", "zh": "所有的星星都像开了花。", "t": [100, 6575]}]}, {"id": "ch26p30", "audio": true, "sents": [{"es": "Pero el principito no respondió a mi pregunta y dijo:", "zh": "” “不错……” “水也是这样。", "t": [100, 2700]}]}, {"id": "ch26p31", "audio": true, "sents": [{"es": "-Lo más importante nunca se ve…", "zh": "你给我喝的水，有了辘轳和绳子，水就如同音乐……你记得……它是甘甜的。", "t": [100, 1700]}]}, {"id": "ch26p32", "audio": true, "sents": [{"es": "-Indudablemente…", "zh": "你给我喝的水，有了辘轳和绳子，水就如同音乐……你记得……它是甘甜的。", "t": [100, 1062]}]}, {"id": "ch26p33", "audio": true, "sents": [{"es": "-Es lo mismo que la flor.", "zh": "” “不错。", "t": [100, 2300]}, {"es": "Si te gusta una flor que habita en una estrella, es muy dulce mirar al cielo por la noche.", "zh": "” “夜里你仰望星空吧，我的那颗星太渺小，没法子告诉你它在哪儿。", "t": [2300, 6938]}]}, {"id": "ch26p34", "audio": true, "sents": [{"es": "Todas las estrellas han florecido.", "zh": "” “夜里你仰望星空吧，我的那颗星太渺小，没法子告诉你它在哪儿。", "t": [100, 1900]}]}, {"id": "ch26p35", "audio": true, "sents": [{"es": "-Es indudable…", "zh": "这样更好……你就把我的星看做是万千星星中的一颗吧，这样你就会爱看所有的星星……它们全都成了你的朋友。", "t": [100, 962]}]}, {"id": "ch26p36", "audio": true, "sents": [{"es": "-Es como el agua.", "zh": "这样更好……你就把我的星看做是万千星星中的一颗吧，这样你就会爱看所有的星星……它们全都成了你的朋友。", "t": [100, 2012]}, {"es": "La que me diste a beber, gracias a la roldana y la cuerda, era como una música ¿te acuerdas?", "zh": "这样更好……你就把我的星看做是万千星星中的一颗吧，这样你就会爱看所有的星星……它们全都成了你的朋友。", "t": [2012, 7962]}, {"es": "¡Qué buena era!", "zh": "然后我会赠给你一份礼物……” 他还在笑。", "t": [7962, 8700]}]}, {"id": "ch26p37", "audio": true, "sents": [{"es": "-Sí, cierto…", "zh": "然后我会赠给你一份礼物……” 他还在笑。", "t": [100, 963]}]}, {"id": "ch26p38", "audio": true, "sents": [{"es": "-Por la noche mirarás las estrellas; mi casa es demasiado pequeña para que yo pueda señalarte dónde se encuentra.", "zh": "“啊，小人儿，小人儿，我喜欢听你的笑声！", "t": [100, 6688]}, {"es": "Así es mejor; mi estrella será para ti una cualquiera de ellas.", "zh": "” “这正是我给你的礼物……这就和水一样……” “你想说什么？", "t": [6688, 11338]}, {"es": "Te gustará entonces mirar todas las estrellas.", "zh": "” “不同的人有不同的星星。", "t": [11338, 14850]}, {"es": "Todas ellas serán tus amigas.", "zh": "” “不同的人有不同的星星。", "t": [14850, 17538]}, {"es": "Y además, te haré un regalo…", "zh": "星星是旅行的人的向导，星星只是其他人的小灯，星星是学者研究的问题，星星是我说过的那个商人的金子。", "t": [17538, 19050]}]}, {"id": "ch26p39", "audio": true, "sents": [{"es": "Y rió una vez más.", "zh": "星星是旅行的人的向导，星星只是其他人的小灯，星星是学者研究的问题，星星是我说过的那个商人的金子。", "t": [100, 2238]}, {"es": "-¡Ah, muchachito, muchachito, cómo me gusta oír tu risa!", "zh": "星星是旅行的人的向导，星星只是其他人的小灯，星星是学者研究的问题，星星是我说过的那个商人的金子。", "t": [2238, 5276]}]}, {"id": "ch26p40", "audio": true, "sents": [{"es": "-Mi regalo será ése precisamente, será como el agua…", "zh": "但所有的星星都沉默不语。", "t": [100, 3112]}, {"es": "-¿Qué quieres decir?", "zh": "你的那颗星星是别人没有的……” “你想说什么？", "t": [3112, 4038]}]}, {"id": "ch26p41", "audio": true, "sents": [{"es": "La gente tiene estrellas que no son las mismas.", "zh": "你的那颗星星是别人没有的……” “你想说什么？", "t": [100, 3575]}, {"es": "Para los que viajan, las estrellas son guías; para otros sólo son pequeñas lucecítas.", "zh": "” “既然我住在天上一颗星星里，既然我在其中一颗星星里笑，这就如同所有的星星都在冲你笑，你就拥有无数会笑的星星了！", "t": [3575, 9188]}, {"es": "Para los sabios las estrellas son problemas.", "zh": "” “既然我住在天上一颗星星里，既然我在其中一颗星星里笑，这就如同所有的星星都在冲你笑，你就拥有无数会笑的星星了！", "t": [9188, 12400]}, {"es": "Para mi hombre de negocios, eran oro.", "zh": "” 他还在笑。", "t": [12400, 15338]}, {"es": "Pero todas esas estrellas se callan.", "zh": "” 他还在笑。", "t": [15338, 18262]}, {"es": "Tú tendrás estrellas como nadie ha tenido…", "zh": "“你得到了安慰之后（人常常自我安慰），你会为认识我而高兴。", "t": [18262, 20662]}, {"es": "-¿Qué quieres decir?", "zh": "“你得到了安慰之后（人常常自我安慰），你会为认识我而高兴。", "t": [20662, 22525]}, {"es": "-Cuando por las noches mires al cielo, al pensar que en una de aquellas estrellas estoy yo riendo, será para ti como si todas las estrellas riesen.", "zh": "你会成为我永远的朋友，你会想与我一起笑。", "t": [22525, 31012]}, {"es": "¡Tú sólo tendrás estrellas que saben reír!", "zh": "有时候，当你想笑而打开窗户的时候……你的朋友看见你仰望星空独自发笑，他们一定会惊讶，你就对他们说：‘是的，我看见星星就要笑！", "t": [31012, 33262]}]}, {"id": "ch26p42", "audio": true, "sents": [{"es": "Y rió nuevamente.", "zh": "有时候，当你想笑而打开窗户的时候……你的朋友看见你仰望星空独自发笑，他们一定会惊讶，你就对他们说：‘是的，我看见星星就要笑！", "t": [100, 1150]}]}, {"id": "ch26p43", "audio": true, "sents": [{"es": "-Cuando te hayas consolado (siempre se consuela uno) estarás contento de haberme conocido.", "zh": "’他们会以为你神经出了毛病。", "t": [100, 6025]}, {"es": "Serás mi amigo y tendrás ganas de reír conmigo.", "zh": "看来是我捉弄了你了……” 他还在笑。", "t": [6025, 9575]}, {"es": "Algunas veces abrirás tu ventana sólo por placer y tus amigos quedarán asombrados de verte reír mirando al cielo.", "zh": "“这样一来，我给你的不是星星，而是一大批会笑的小铃铛……” 他还在笑。", "t": [9575, 16450]}, {"es": "Tú les explicarás: \"Las estrellas me hacen reír siempre\".", "zh": "然后他收敛了笑容： “今晚……你知道……你不要来了。", "t": [16450, 20575]}, {"es": "Ellos te creerán loco.", "zh": "” “我不会离开你的。", "t": [20575, 22925]}, {"es": "Y yo te habré jugado una mala pasada…", "zh": "” “我会很难看的……会像个死人，别来看我的死了的样子，没有必要。", "t": [22925, 24950]}]}, {"id": "ch26p44", "audio": true, "sents": [{"es": "Y se rió otra vez.", "zh": "” “我会很难看的……会像个死人，别来看我的死了的样子，没有必要。", "t": [100, 1187]}]}, {"id": "ch26p45", "audio": true, "sents": [{"es": "-Será como si en vez de estrellas, te hubiese dado multitud de cascabelitos que saben reír…", "zh": "” “我不会离开你的。", "t": [100, 4726]}]}, {"id": "ch26p46", "audio": true, "sents": [{"es": "Una vez más dejó oír su risa y luego se puso serio.", "zh": "” 他露出忧心忡忡的神色。", "t": [100, 3075]}]}, {"id": "ch26p47", "audio": true, "sents": [{"es": "-Esta noche ¿sabes?", "zh": "“我跟你讲这些话……也是因为蛇，不该让它伤害你……蛇是凶残的动物，高兴时也咬人……” “我不离开你。", "t": [100, 1375]}, {"es": "no vengas…", "zh": "“我跟你讲这些话……也是因为蛇，不该让它伤害你……蛇是凶残的动物，高兴时也咬人……” “我不离开你。", "t": [1375, 1988]}]}, {"id": "ch26p48", "audio": true, "sents": [{"es": "-No te dejaré.", "zh": "“我跟你讲这些话……也是因为蛇，不该让它伤害你……蛇是凶残的动物，高兴时也咬人……” “我不离开你。", "t": [100, 875]}]}, {"id": "ch26p49", "audio": true, "sents": [{"es": "-Pareceré enfermo…", "zh": "“我跟你讲这些话……也是因为蛇，不该让它伤害你……蛇是凶残的动物，高兴时也咬人……” “我不离开你。", "t": [100, 2038]}, {"es": "Parecerá un poco que me muero…", "zh": "“我跟你讲这些话……也是因为蛇，不该让它伤害你……蛇是凶残的动物，高兴时也咬人……” “我不离开你。", "t": [2038, 3700]}, {"es": "es así.", "zh": "“我跟你讲这些话……也是因为蛇，不该让它伤害你……蛇是凶残的动物，高兴时也咬人……” “我不离开你。", "t": [3700, 5150]}, {"es": "¡No vale la pena que vengas a ver eso…!", "zh": "” 他想起什么，随即放宽了心： “真的，蛇咬的第二口不再有毒液……” 那天夜里我没看见他离开我。", "t": [5150, 7076]}]}, {"id": "ch26p50", "audio": true, "sents": [{"es": "-No te dejaré.", "zh": "” 他想起什么，随即放宽了心： “真的，蛇咬的第二口不再有毒液……” 那天夜里我没看见他离开我。", "t": [100, 875]}]}, {"id": "ch26p51", "audio": true, "sents": [{"es": "Pero estaba preocupado.", "zh": "” 他想起什么，随即放宽了心： “真的，蛇咬的第二口不再有毒液……” 那天夜里我没看见他离开我。", "t": [100, 1363]}]}, {"id": "ch26p52", "audio": true, "sents": [{"es": "-Te digo esto por la serpiente; no debe morderte.", "zh": "” 他想起什么，随即放宽了心： “真的，蛇咬的第二口不再有毒液……” 那天夜里我没看见他离开我。", "t": [100, 3812]}, {"es": "Las serpientes son malas.", "zh": "他是悄悄走的。", "t": [3812, 6288]}, {"es": "A veces muerden por gusto…", "zh": "他是悄悄走的。", "t": [6288, 7737]}]}, {"id": "ch26p53", "audio": true, "sents": [{"es": "-He dicho que no te dejaré.", "zh": "我终于赶上他。", "t": [100, 1325]}]}, {"id": "ch26p54", "audio": true, "sents": [{"es": "Pero algo lo tranquilizó.", "zh": "他大步走着，步子迈得又大又坚决。", "t": [100, 1338]}]}, {"id": "ch26p55", "audio": true, "sents": [{"es": "-Bien es verdad que no tienen veneno para la segunda mordedura…", "zh": "他见了我，只说了一句：“呀，你在这儿……” 他牵住我的手。", "t": [100, 3176]}]}, {"id": "ch26p56", "audio": true, "sents": [{"es": "Aquella noche no lo vi ponerse en camino.", "zh": "然后他苦恼地说： “你不该来的。", "t": [100, 3212]}, {"es": "Cuando le alcancé marchaba con paso rápido y decidido y me dijo solamente: -¡Ah, estás ahí!", "zh": "你会难过的。", "t": [3212, 8025]}]}, {"id": "ch26p57", "audio": true, "sents": [{"es": "Me cogió de la mano y todavía se atormentó:", "zh": "我会像个死人，其实我不是真死……” 我不做声。", "t": [100, 2338]}]}, {"id": "ch26p58", "audio": true, "sents": [{"es": "-Has hecho mal.", "zh": "“你知道吧，路途太远，我拖不动这副皮囊，它太沉了。", "t": [100, 1812]}, {"es": "Tendrás pena.", "zh": "“你知道吧，路途太远，我拖不动这副皮囊，它太沉了。", "t": [1812, 3612]}, {"es": "Parecerá que estoy muerto, pero no es verdad.", "zh": "” 我不做声。", "t": [3612, 5924]}]}, {"id": "ch26p59", "audio": true, "sents": [{"es": "Yo me callaba.", "zh": "” 我不做声。", "t": [100, 1912]}, {"es": "-¿Comprendes?", "zh": "“也不过如同蜕了旧壳，一副旧壳不值得悲哀……” 我还是不做声。", "t": [1912, 3612]}, {"es": "Es demasiado lejos y no puedo llevar este cuerpo que pesa demasiado.", "zh": "“也不过如同蜕了旧壳，一副旧壳不值得悲哀……” 我还是不做声。", "t": [3612, 7063]}]}, {"id": "ch26p60", "audio": true, "sents": [{"es": "-Seguí callado.", "zh": "他有点泄气了，但还在竭力安慰我： “你知道，想起你，我的心会温暖的。", "t": [100, 900]}]}, {"id": "ch26p61", "audio": true, "sents": [{"es": "-Será como una corteza vieja que se abandona.", "zh": "他有点泄气了，但还在竭力安慰我： “你知道，想起你，我的心会温暖的。", "t": [100, 3425]}, {"es": "No son nada tristes las viejas cortezas…", "zh": "他有点泄气了，但还在竭力安慰我： “你知道，想起你，我的心会温暖的。", "t": [3425, 5825]}]}, {"id": "ch26p62", "audio": true, "sents": [{"es": "Yo me callaba.", "zh": "以后我也会仰望星空，所有的星星会成了带有生锈辘轳的井，所有的星星给我倒水喝……” 我还是不做声。", "t": [100, 1912]}, {"es": "El principito perdió un poco de ánimo.", "zh": "以后我也会仰望星空，所有的星星会成了带有生锈辘轳的井，所有的星星给我倒水喝……” 我还是不做声。", "t": [1912, 4875]}, {"es": "Pero hizo un esfuerzo y dijo:", "zh": "以后我也会仰望星空，所有的星星会成了带有生锈辘轳的井，所有的星星给我倒水喝……” 我还是不做声。", "t": [4875, 6463]}]}, {"id": "ch26p63", "audio": true, "sents": [{"es": "Será agradable ¿sabes?", "zh": "以后我也会仰望星空，所有的星星会成了带有生锈辘轳的井，所有的星星给我倒水喝……” 我还是不做声。", "t": [100, 2638]}, {"es": "Yo miraré también las estrellas.", "zh": "“那会是多有趣的事情！", "t": [2638, 5375]}, {"es": "Todas serán pozos con roldana herrumbrosa.", "zh": "“那会是多有趣的事情！", "t": [5375, 8662]}, {"es": "Todas las estrellas me darán de beber.", "zh": "你会有五亿个小铃铛，我有五亿口井……” 他也不做声了，因为他哭了…… “就在这儿吧。", "t": [8662, 10650]}]}, {"id": "ch26p64", "audio": true, "sents": [{"es": "Yo me callaba.", "zh": "你会有五亿个小铃铛，我有五亿口井……” 他也不做声了，因为他哭了…… “就在这儿吧。", "t": [100, 1912]}, {"es": "-¡Será tan divertido!", "zh": "你会有五亿个小铃铛，我有五亿口井……” 他也不做声了，因为他哭了…… “就在这儿吧。", "t": [1912, 3988]}, {"es": "Tú tendrás quinientos millones de cascabeles y yo quinientos millones de fuentes…", "zh": "你让我独自走一步。", "t": [3988, 7937]}]}, {"id": "ch26p65", "audio": true, "sents": [{"es": "El principito se calló también; estaba llorando.", "zh": "” 他坐了下来，因为他害怕了。", "t": [100, 2700]}]}, {"id": "ch26p66", "audio": true, "sents": [{"es": "-Es allí; déjame ir solo.", "zh": "他还说： “你知道……我的花……我要对她负责！", "t": [100, 1888]}]}, {"id": "ch26p67", "audio": true, "sents": [{"es": "Se sentó porque tenía miedo.", "zh": "她弱不禁风！", "t": [100, 2638]}, {"es": "Dijo aún: -¿Sabes?…", "zh": "她聪明纯洁！", "t": [2638, 4888]}, {"es": "mi flor…", "zh": "她一无所有！", "t": [4888, 5612]}, {"es": "soy responsable…", "zh": "她一无所有！", "t": [5612, 6800]}, {"es": "¡y ella es tan débil y tan inocente!", "zh": "只凭四根刺保护自己，抵御世上的侵害……” 我瘫坐在地上。", "t": [6800, 9750]}, {"es": "Sólo tiene cuatro espinas para defenderse contra todo el mundo…", "zh": "因为我站不住了。", "t": [9750, 13013]}]}, {"id": "ch26p68", "audio": true, "sents": [{"es": "Me senté, ya no podía mantenerme en pie.", "zh": "因为我站不住了。", "t": [100, 2276]}]}, {"id": "ch26p69", "audio": true, "sents": [{"es": "-Ahí está…", "zh": "他说： “我的话……讲完了……” 他还犹豫了片刻，然后站起来，向前走了一步。", "t": [100, 1038]}, {"es": "eso es todo…", "zh": "他说： “我的话……讲完了……” 他还犹豫了片刻，然后站起来，向前走了一步。", "t": [1038, 1800]}]}, {"id": "ch26p70", "audio": true, "sents": [{"es": "Vacíló todavía un instante, luego se levantó y dio un paso.", "zh": "而我不能动弹。", "t": [100, 4325]}, {"es": "Yo no pude moverme.", "zh": "而我不能动弹。", "t": [4325, 5413]}]}, {"id": "ch26p71", "audio": true, "sents": [{"es": "Un relámpago amarillo centelleó en su tobillo.", "zh": "他凝然不动。", "t": [100, 3600]}, {"es": "Quedó un instante inmóvil, sin exhalar un grito.", "zh": "好一会儿之后，他像大树倒地似的倒下。", "t": [3600, 7238]}, {"es": "Luego cayó lentamente camo cae un árbol, sin hacer el menor ruido a causa de la arena.", "zh": "因为这儿是沙地，他倒下去的时候，一点声音都没有。", "t": [7238, 11863]}]}]}, {"id": "ch27", "title_es": "Capítulo 27", "title_zh": "第 27 章", "paras": [{"id": "ch27p00", "audio": true, "sents": [{"es": "Ahora hace ya seis años de esto.", "zh": "当然，这已是六年前的事了……我从来没对别人讲过这个故事。", "t": [100, 3000]}, {"es": "Jamás he contado esta historia y los compañeros que me vuelven a ver se alegran de encontrarme vivo.", "zh": "我的同事们看见我活着回来，都替我庆幸。", "t": [3000, 8688]}, {"es": "Estaba triste, pero yo les decía: \"Es el cansancio\".", "zh": "我神色哀伤，但我告诉他们：“这是因为累……” 现在，我的离愁别绪已经减轻了一些。", "t": [8688, 11788]}]}, {"id": "ch27p01", "audio": true, "sents": [{"es": "AI correr del tiempo me he consolado un poco, pero no completamente.", "zh": "我神色哀伤，但我告诉他们：“这是因为累……” 现在，我的离愁别绪已经减轻了一些。", "t": [100, 4525]}, {"es": "Sé que ha vuelto a su planeta, pues al amanecer no encontré su cuerpo, que no era en realidad tan pesado…", "zh": "我很明白，他回他的星球去了，因为天亮时我没找到他的尸体。", "t": [4525, 10850]}, {"es": "Y me gusta por la noche escuchar a las estrellas, que suenan como quinientos millones de cascabeles…", "zh": "他的躯体并不沉重……我喜欢在夜里倾听星星的呢喃，它们就像五亿个小铃铛…… 可是出了非同寻常的事了：我给小王子画了口罩，但我忘了给口罩配上皮带！", "t": [10850, 15862]}]}, {"id": "ch27p02", "audio": true, "sents": [{"es": "Pero sucede algo extraordinario.", "zh": "他的躯体并不沉重……我喜欢在夜里倾听星星的呢喃，它们就像五亿个小铃铛…… 可是出了非同寻常的事了：我给小王子画了口罩，但我忘了给口罩配上皮带！", "t": [100, 2862]}, {"es": "AI bozal que dibujé para el principito se me olvidó añadirle la correa de cuero; no habrá podido atárselo al cordero.", "zh": "他别想把口罩套上羊嘴了。", "t": [2862, 9762]}, {"es": "Entonces me pregunto:", "zh": "我于是想：“他的星球发生了什么事呢？", "t": [9762, 10975]}]}, {"id": "ch27p03", "audio": true, "sents": [{"es": "\"¿Qué habrá sucedido en su planeta?", "zh": "绵羊很可能吃了花儿……” 有时我又想：“一定不会的！", "t": [100, 2688]}, {"es": "Quízás el cordero se ha comido la flor…\"", "zh": "绵羊很可能吃了花儿……” 有时我又想：“一定不会的！", "t": [2688, 4676]}]}, {"id": "ch27p04", "audio": true, "sents": [{"es": "A veces me digo: \"¡Seguro que no!", "zh": "绵羊很可能吃了花儿……” 有时我又想：“一定不会的！", "t": [100, 2762]}, {"es": "El príncipito cubre la flor con su fanal todas las noches y vigila a su cordero\".", "zh": "小王子每天夜里把他的花儿罩在玻璃罩里，他一定会看管好他的绵羊……”于是我放心了，天上所有的星星都温和地微笑。", "t": [2762, 6900]}]}, {"id": "ch27p05", "audio": true, "sents": [{"es": "Entonces me siento dichoso y todas las estrellas ríen dulcemente.", "zh": "有时我想：“人总免不了有疏忽大意的时候，这就够糟的了！", "t": [100, 3675]}]}, {"id": "ch27p06", "audio": true, "sents": [{"es": "Pero otras veces pienso: \"Alguna que otra vez se distrae uno y eso basta.", "zh": "有时我想：“人总免不了有疏忽大意的时候，这就够糟的了！", "t": [100, 5262]}, {"es": "Si una noche ha olvidado poner el fanal o el cordero ha salido sin hacer ruido, durante la noche…\".", "zh": "要是有天晚上他忘了给花罩上玻璃罩，或者绵羊在夜里悄悄地溜出来呢……”于是，铃铛全变成了泪珠…… 这件事始终是无法解开的谜。", "t": [5262, 11175]}, {"es": "Y entonces los cascabeles se convierten en lágrimas…", "zh": "要是有天晚上他忘了给花罩上玻璃罩，或者绵羊在夜里悄悄地溜出来呢……”于是，铃铛全变成了泪珠…… 这件事始终是无法解开的谜。", "t": [11175, 13926]}]}, {"id": "ch27p07", "audio": true, "sents": [{"es": "Y ahí está el gran misterio.", "zh": "在宇宙中不知哪个角落，我们不认识的绵羊有没有吃掉一朵玫瑰花，你们——喜爱小王子的人，和我一样，看法绝不相同…… 请你们仰望星空吧。", "t": [100, 2600]}, {"es": "Para ustedes que quieren al principito, lo mismo que para mí, nada en el universo habrá cambiado si en cualquier parte, quien sabe dónde, un cordero desconocido se ha comido o no se ha comido una rosa…", "zh": "在宇宙中不知哪个角落，我们不认识的绵羊有没有吃掉一朵玫瑰花，你们——喜爱小王子的人，和我一样，看法绝不相同…… 请你们仰望星空吧。", "t": [2600, 12426]}]}, {"id": "ch27p08", "audio": true, "sents": [{"es": "Pero miren al cielo y pregúntense: el cordero ¿se ha comido la flor?", "zh": "你们就会看到，天上所有的星星发生了变化…… 没有一个大人明白，弄清楚这个问题有多重要！", "t": [100, 4950]}, {"es": "Y veréis cómo todo cambia…", "zh": "你们就会看到，天上所有的星星发生了变化…… 没有一个大人明白，弄清楚这个问题有多重要！", "t": [4950, 7312]}, {"es": "¡Ninguna persona mayor comprenderá jamás que esto sea verdaderamente importante!", "zh": "我认为这幅图画是世界上最凄美的图画了。", "t": [7312, 11450]}]}, {"id": "ch27p09", "audio": true, "sents": [{"es": "Este es para mí el paisaje más hermoso y el más triste del mundo.", "zh": "我再一次画它，是为了让你们好好地看看它。", "t": [100, 3462]}]}, {"id": "ch27p10", "audio": true, "sents": [{"es": "Es el mismo paisaje de la página anterior que he dibujado una vez más para que lo vean bien.", "zh": "小王子就是在这里出现在地球上的，然后又是从这里离开了地球。", "t": [100, 5512]}, {"es": "Fue aquí donde el principito apareció sobre la Tierra, desapareciendo luego.", "zh": "请你们仔细看清楚这幅画，有朝一日你们到沙漠，到非洲旅行，才能认出这地方来。", "t": [5512, 9487]}]}, {"id": "ch27p11", "audio": true, "sents": [{"es": "Exaxnínenlo atentamente para que sepan reconocerlo, si algún día, viajando por Africa cruzan el desierto.", "zh": "如果你经过这个地方，我恳求你们，别匆忙离去，请在那颗星下稍待片刻！", "t": [100, 7025]}, {"es": "Si por casualidad pasan por allí, no se apresuren, se los ruego, y deténganse un poco, precisamente bajo la estrella.", "zh": "如果有个孩子向你走过来；如果他笑吟吟的；如果他长着一头金发；如果你向他提问题，他不回答；你们就会猜到他是谁了。", "t": [7025, 14325]}, {"es": "Si un niño llega hasta ustedes, si este niño ríe y tiene cabellos de oro y nunca responde a sus preguntas, adivinarán en seguida quién es.", "zh": "果真如此，请你们行行好！", "t": [14325, 22800]}, {"es": "¡Sean amables con él!", "zh": "别眼睁睁看着我为思念他而悲伤，别坐视不理，别无动于衷：请你们快点写信告诉我，他回来了…… 【注释】 [1] 美国的一个州。", "t": [22800, 24025]}]}, {"id": "ch27p12", "audio": true, "sents": [{"es": "Y comuníquenme rápidamente que ha regresado.", "zh": "别眼睁睁看着我为思念他而悲伤，别坐视不理，别无动于衷：请你们快点写信告诉我，他回来了…… 【注释】 [1] 美国的一个州。", "t": [100, 3438]}, {"es": "¡No me dejen tan triste!", "zh": "别眼睁睁看着我为思念他而悲伤，别坐视不理，别无动于衷：请你们快点写信告诉我，他回来了…… 【注释】 [1] 美国的一个州。", "t": [3438, 4775]}]}]}]}